(function(){"use strict";var w=window.ScripturaJosephusWorks||(window.ScripturaJosephusWorks={});var a=w.guerra||(w.guerra={});a[2]={"work":"guerra","book":2,"title":"Φλαυίου Ἰωσήπου ἱστορία Ἰουδαϊκοῦ πολέμου πρὸς Ῥωμαίους λόγος β.","chapters":{"1":[{"number":1,"text":"Ἀρχελάῳ δὲ νέων ἦρξε θορύβων ἡ τῆς ἐπὶ Ῥώμην ἀποδημίας ἀνάγκη. πενθήσας γὰρ ἡμέρας ἑπτὰ τὸν πατέρα καὶ τὴν ἐπιτάφιον ἑστίασιν πολυτελῆ τῷ πλήθει παρασχών· ἔθος δὲ τοῦτο παρὰ Ἰουδαίοις πολλοῖς πενίας αἴτιον διὰ τὸ πλῆθος ἑστιᾶν οὐκ ἄνευ ἀνάγκης· εἰ γὰρ παραλείποι τις, οὐχ ὅσιος· μεταλαμβάνει μὲν ἐσθῆτα λευκήν, πρόεισι δὲ εἰς τὸ ἱερόν, ἔνθα ποικίλαις αὐτὸν εὐφημίαις ὁ λαὸς ἐκδέχεται."},{"number":2,"text":"κἀκεῖνος τὸ πλῆθος ἀφʼ ὑψηλοῦ βήματος καὶ χρυσοῦ θρόνου δεξιωσάμενος τῆς τε σπουδῆς, ἣν ἐνεδείξαντο περὶ τὴν κηδείαν τοῦ πατρός, εὐχαριστεῖ καὶ τῆς πρὸς αὐτὸν θεραπείας ὡς πρὸς βέβαιον ἤδη βασιλέα· φείδεσθαί γε μὴν οὐ μόνον ἔφη τῆς ἐξουσίας ἐπὶ τοῦ παρόντος, ἀλλὰ καὶ τῶν ὀνομάτων, ἕως ἂν αὐτῷ Καῖσαρ ἐπικυρώσῃ τὴν διαδοχήν, ὁ καὶ κατὰ τὰς διαθήκας τῶν ὅλων δεσπότης·"},{"number":3,"text":"οὐδὲ γὰρ ἐν Ἱεριχοῦντι τῆς στρατιᾶς τὸ διάδημα περιαπτούσης αὐτῷ δεδέχθαι· τοῦ μέντοι προθύμου καὶ τῆς εὐνοίας ὥσπερ τοῖς στρατιώταις οὕτω καὶ τῷ δήμῳ πλήρεις ἀποδώσειν τὰς ἀμοιβάς, ὁπόταν ὑπὸ τῶν κρατούντων βασιλεὺς ἀποδειχθῇ βέβαιος· σπουδάσειν γὰρ ἐν πᾶσιν πρὸς αὐτοὺς φανῆναι τοῦ πατρὸς ἀμείνων."},{"number":4,"text":"Ἐπὶ τούτοις ἡδόμενον τὸ πλῆθος εὐθέως ἀπεπειρᾶτο τῆς διανοίας αὐτοῦ μεγάλοις αἰτήμασιν· οἱ μὲν γὰρ ἐβόων ἐπικουφίζειν τὰς εἰσφοράς, οἱ δὲ ἀναιρεῖν τὰ τέλη, τινὲς δὲ ἀπολύειν τοὺς δεσμώτας. ἐπένευσε δʼ ἑτοίμως ἅπασι θεραπεύων τὸ πλῆθος."},{"number":5,"text":"ἔπειτα θύσας ἐν εὐωχίᾳ μετὰ τῶν φίλων ἦν. ἔνθα δὴ περὶ δείλην ἀθροισθέντες οὐκ ὀλίγοι τῶν νεωτερίζειν προῃρημένων ἤρξαντο ἰδίου πένθους, ὅτε τὸ κοινὸν ἐπὶ τῷ βασιλεῖ πέπαυτο, κατολοφυρόμενοι τοὺς κολασθέντας ὑπὸ Ἡρώδου διὰ τὸν ἐκκοπέντα χρυσοῦν ἀετὸν τῆς πύλης τοῦ ναοῦ."},{"number":6,"text":"ἦν δὲ τὸ πένθος οὐχ ὑπεσταλμένον, ἀλλʼ οἰμωγαὶ διαπρύσιοι καὶ θρῆνος ἐγκέλευστος κοπετοί τε περιηχοῦντες ὅλην τὴν πόλιν ὡς ἂν ἐπʼ ἀνδράσιν, οὓς ἔφασκον ὑπὲρ τῶν πατρίων νόμων καὶ τοῦ ναοῦ πυρὶ παραπολέσθαι."},{"number":7,"text":"τιμωρεῖν δʼ αὐτοῖς ἀνεβόων ἐκ τῶν ὑφʼ Ἡρώδου τετιμημένων χρῆναι καὶ πρῶτον τὸν ὑπʼ ἐκείνου κατασταθέντα παύειν ἀρχιερέα· προσήκειν γὰρ αὐτοῖς εὐσεβέστερον αἱρεῖσθαι καὶ καθαρώτερον."},{"number":8,"text":"Πρὸς ἃ παρωξύνετο μὲν Ἀρχέλαος, ἐπεῖχε δὲ τὴν ἄμυναν ὑπὸ τῆς περὶ τὴν ἔξοδον ἐπείξεως, δεδοικὼς μή ποτε τὸ πλῆθος ἐκπολεμώσας κατασχεθείη τῷ κινήματι. διὸ πειθοῖ μᾶλλον ἢ βίᾳ καταστέλλειν ἐπειρᾶτο τοὺς νεωτερίζοντας καὶ τὸν στρατηγὸν ὑποπέμψας παύσασθαι παρεκάλει."},{"number":9,"text":"τοῦτον εἰς τὸ ἱερὸν παρελθόντα πρὶν φθέγξασθαί τι λίθοις ἀπήλαυνον οἱ στασιασταὶ καὶ τοὺς μετʼ αὐτοῦ ἐπὶ σωφρονισμῷ προσιόντας, ἐνίει δὲ πολλοὺς ὁ Ἀρχέλαος, καὶ πάντα πρὸς ὀργὴν ἀπεκρίναντο δῆλοί τε ἦσαν οὐκ ἠρεμήσοντες εἰ πλήθους ἐπιλάβοιντο."},{"number":10,"text":"καὶ δὴ τῆς τῶν ἀζύμων ἐνστάσης ἑορτῆς, ἣ πάσχα παρὰ Ἰουδαίοις καλεῖται πολύ τι θυμάτων πλῆθος ἐκδεχομένη, κάτεισι μὲν ἐκ τῆς χώρας λαὸς ἄπειρος ἐπὶ τὴν θρησκείαν, οἱ δὲ τοὺς σοφιστὰς πενθοῦντες ἐν τῷ ἱερῷ συνειστήκεσαν τροφὴν τῇ στάσει ποριζόμενοι."},{"number":11,"text":"πρὸς ὃ δείσας Ἀρχέλαος πρὶν διʼ ὅλου τοῦ πλήθους διαδραμεῖν τὴν νόσον ὑποπέμπει μετὰ σπείρας χιλίαρχον προστάξας βίᾳ τοὺς ἐξάρχοντας τῆς στάσεως κατασχεῖν. πρὸς οὓς τὸ πλῆθος ἅπαν παροξύνεται καὶ τοὺς μὲν πολλοὺς τῆς σπείρας βάλλοντες λίθοις διέφθειρον, ὁ δὲ χιλίαρχος ἐκφεύγει τραυματίας μόλις."},{"number":12,"text":"ἔπειθʼ οἱ μὲν ὡς μηδενὸς δεινοῦ γεγονότος ἐτρέποντο πρὸς θυσίαν· οὐ μὴν Ἀρχελάῳ δίχα φόνου καθεκτὸν ἔτι τὸ πλῆθος ἐφαίνετο, τὴν δὲ στρατιὰν ἐπαφίησιν αὐτοῖς ὅλην, τοὺς μὲν πεζοὺς διὰ τῆς πόλεως ἀθρόους, τοὺς δὲ ἱππεῖς ἀνὰ τὸ πεδίον·"},{"number":13,"text":"οἳ θύουσιν ἑκάστοις ἐξαίφνης προσπεσόντες διαφθείρουσι μὲν περὶ τρισχιλίους, τὸ δὲ λοιπὸν πλῆθος εἰς τὰ πλησίον ὄρη διεσκέδασαν. εἵποντο δὲ Ἀρχελάου κήρυκες κελεύοντες ἕκαστον ἀναχωρεῖν ἐπʼ οἴκου, καὶ πάντες ᾤχοντο τὴν ἑορτὴν ἀπολιπόντες."}],"2":[{"number":14,"text":"Αὐτὸς δὲ μετὰ τῆς μητρὸς καὶ τῶν φίλων Ποπλᾶ καὶ Πτολεμαίου καὶ Νικολάου κατῄει πρὸς θάλασσαν καταλιπὼν ἐπίτροπόν τε τῶν βασιλείων καὶ κηδεμόνα τῶν οἰκείων Φίλιππον."},{"number":15,"text":"συνεξῄει δʼ ἅμα τοῖς τέκνοις Σαλώμη καὶ τοῦ βασιλέως ἀδελφιδοῖ τε καὶ γαμβροί, τῷ μὲν δοκεῖν συναγωνιούμενοι περὶ τῆς διαδοχῆς Ἀρχελάῳ, τὸ δʼ ἀληθὲς κατηγορήσοντες περὶ τῶν κατὰ τὸ ἱερὸν παρανομηθέντων."},{"number":16,"text":"Συναντᾷ δʼ αὐτοῖς κατὰ τὴν Καισάρειαν Σαβῖνος ὁ τῆς Συρίας ἐπίτροπος εἰς Ἰουδαίαν ἀνιὼν ἐπὶ φυλακῇ τῶν Ἡρώδου χρημάτων. τοῦτον ἐπέσχεν προσωτέρω χωρεῖν ἐπελθὼν Οὔαρος, ὃν διὰ Πτολεμαίου πολλὰ δεηθεὶς Ἀρχέλαος μετεπέμψατο."},{"number":17,"text":"τότε μὲν οὖν Σαβῖνος Οὐάρῳ χαριζόμενος οὔτʼ ἐπὶ τὰς ἄκρας ἔσπευσεν οὔτε τὰ ταμιεῖα τῶν πατρῴων χρημάτων ἀπέκλεισεν Ἀρχελάῳ, μέχρι δὲ τῆς Καίσαρος διαγνώσεως ἠρεμήσειν ὑπέσχετο καὶ διέτριβεν ἐπὶ τῆς Καισαρείας."},{"number":18,"text":"ὡς δὲ τῶν ἐμποδιζόντων ὁ μὲν εἰς Ἀντιόχειαν ἀπῆρεν, Ἀρχέλαος δὲ εἰς Ῥώμην ἀνήχθη, διὰ τάχους ἐπὶ Ἱεροσολύμων ὁρμήσας παραλαμβάνει τὰ βασίλεια καὶ μεταπεμπόμενος τούς τε φρουράρχους καὶ διοικητὰς ἐπειρᾶτο διερευνᾶν τοὺς τῶν χρημάτων ἀναλογισμοὺς τάς τε ἄκρας παραλαμβάνειν."},{"number":19,"text":"οὐ μὴν οἱ φύλακες τῶν Ἀρχελάου κατημέλουν ἐντολῶν, ἔμενον δὲ φρουροῦντες ἕκαστα καὶ τὴν φρουρὰν ἀνατιθέντες Καίσαρι μᾶλλον ἢ Ἀρχελάῳ."},{"number":20,"text":"Κἀν τούτῳ πάλιν Ἀντίπας ἀμφισβητῶν περὶ τῆς βασιλείας ἐπέξεισιν ἀξιῶν τῆς ἐπιδιαθήκης κυριωτέραν εἶναι τὴν διαθήκην, ἐν ᾗ βασιλεὺς αὐτὸς ἐγέγραπτο. συλλήψεσθαι δʼ αὐτῷ προϋπέσχετο Σαλώμη καὶ πολλοὶ τῶν σὺν Ἀρχελάῳ πλεόντων συγγενῶν."},{"number":21,"text":"ἐπήγετο δὲ τὴν μητέρα καὶ τὸν ἀδελφὸν Νικολάου Πτολεμαῖον ῥοπὴν εἶναι δοκοῦντα διὰ τὴν παρὰ Ἡρώδῃ πίστιν· γεγόνει γὰρ δὴ τῶν φίλων ἐκείνου τιμιώτατος· πλεῖστον μέντοι πεποίθει διὰ δεινότητα λόγων Εἰρηναίῳ τῷ ῥήτορι, διὸ καὶ τοὺς νουθετοῦντας εἴκειν Ἀρχελάῳ κατὰ τὸ πρεσβεῖον καὶ τὰς ἐπιδιαθήκας διεκρούσατο."},{"number":22,"text":"μεθίστατο δὲ ἐν Ῥώμῃ πάντων πρὸς αὐτὸν ἡ σπουδὴ τῶν συγγενῶν, οἷς διὰ μίσους ἦν Ἀρχέλαος, καὶ προηγουμένως ἕκαστος αὐτονομίας ἐπεθύμει στρατηγῷ Ῥωμαίων διοικουμένης, εἰ δὲ τοῦτο διαμαρτάνοι, βασιλεύειν Ἀντίπαν ἤθελεν."},{"number":23,"text":"Συνήργει δʼ αὐτοῖς εἰς τοῦτο καὶ Σαβῖνος διʼ ἐπιστολῶν κατηγορήσας μὲν Ἀρχελάου παρὰ Καίσαρι, πολλὰ δʼ ἐπαινέσας Ἀντίπαν."},{"number":24,"text":"συντάξαντες δὲ τὰ ἐγκλήματα οἱ περὶ Σαλώμην ἐνεχείρισαν Καίσαρι, καὶ μετὰ τούτους Ἀρχέλαος τά τε κεφάλαια τῶν ἑαυτοῦ δικαίων γράψας καὶ τὸν δακτύλιον τοῦ πατρὸς καὶ τοὺς λόγους εἰσπέμπει διὰ Πτολεμαίου."},{"number":25,"text":"προσκεψάμενος δὲ ὁ Καῖσαρ τὰ παρʼ ἀμφοῖν κατʼ ἰδίαν τό τε μέγεθος τῆς βασιλείας καὶ τὸ πλῆθος τῆς προσόδου, πρὸς οἷς τὸν ἀριθμὸν τῆς Ἡρώδου γενεᾶς, προαναγνοὺς δὲ καὶ τὰ παρὰ Οὐάρου καὶ Σαβίνου περὶ τούτων ἐπεσταλμένα, συνέδριον μὲν ἀθροίζει τῶν ἐν τέλει Ῥωμαίων, ἐν ᾧ καὶ τὸν ἐξ Ἀγρίππα καὶ Ἰουλίας τῆς θυγατρὸς θετὸν παῖδα Γάιον πρώτως ἐκάθισεν, ἀποδίδωσι δὲ λόγον αὐτοῖς."},{"number":26,"text":"Ἔνθα καταστὰς ὁ Σαλώμης υἱὸς Ἀντίπατρος, ἦν δὲ τῶν ἐναντιουμένων Ἀρχελάῳ δεινότατος εἰπεῖν, κατηγόρει φάσκων τοῖς μὲν λόγοις ἀμφισβητεῖν ἄρτι βασιλείας Ἀρχέλαον, τοῖς δʼ ἔργοις πάλαι γεγονέναι βασιλέα, κατειρωνεύεσθαι δὲ νῦν τῶν Καίσαρος ἀκοῶν,"},{"number":27,"text":"ὃν δικαστὴν τῆς διαδοχῆς οὐ περιέμεινεν, εἴ γε μετὰ τὴν Ἡρώδου τελευτὴν ἐγκαθέτους μὲν ὑποπέμψας τοὺς περιθήσοντας αὐτῷ τὸ διάδημα, προκαθίσας δʼ ἐπὶ τοῦ θρόνου καὶ χρηματίσας βασιλεὺς τάξεις τε τῆς στρατιᾶς ἀμείψας καὶ προκοπὰς χαρισάμενος,"},{"number":28,"text":"ἔτι δὲ τῷ δήμῳ πάντα κατανεύσας ὅσων ὡς παρὰ βασιλέως τυχεῖν ἠξίουν καὶ τοὺς ἐπὶ μεγίσταις αἰτίαις παρὰ τοῦ πατρὸς δεδεμένους λύσας, νῦν ἥκει παρὰ τοῦ δεσπότου σκιὰν αἰτησόμενος βασιλείας, ἧς ἥρπασεν ἑαυτῷ τὸ σῶμα, καὶ ποιῶν οὐ τῶν πραγμάτων ἀλλὰ τῶν ὀνομάτων κύριον Καίσαρα."},{"number":29,"text":"προσωνείδιζεν δʼ ὡς καὶ τὸ πένθος κατειρωνεύσατο τοῦ πατρός, μεθʼ ἡμέραν μὲν ἐπισχηματίζων τὸ πρόσωπον εἰς λύπην, νύκτωρ δὲ μέχρις κώμων μεθυσκόμενος, ἐν ᾧ καὶ τὴν ταραχὴν τοῦ πλήθους ἐκ τῆς ἐπὶ τούτοις ἀγανακτήσεως ἔλεγεν γεγονέναι."},{"number":30,"text":"καὶ τὸν ἀγῶνα τοῦ λόγου παντὸς ἐναπηρείσατο τῷ πλήθει τῶν περὶ τὸν ναὸν φονευθέντων, οὓς ἐληλυθέναι μὲν ἐφʼ ἑορτήν, παρὰ δὲ ταῖς ἰδίαις θυσίαις ὠμῶς ἀπεσφάχθαι· καὶ τοσοῦτον ἐν τῷ ἱερῷ σεσωρεῦσθαι νεκρῶν πλῆθος, ὅσον οὐδʼ ἂν ἀλλόφυλος ἐσώρευσεν πόλεμος ἐπελθὼν ἀκήρυκτος."},{"number":31,"text":"ταύτην μέντοι τὴν ὠμότητα προσκεψάμενον αὐτοῦ καὶ τὸν πατέρα μηδʼ ἐλπίδος αὐτόν ποτε ἀξιῶσαι βασιλικῆς ἢ ὅτε χεῖρον τὴν ψυχὴν κάμνων τοῦ σώματος ἀκρατὴς ἦν ὑγιαίνοντος λογισμοῦ καὶ οὐδʼ ὃν ἔγραφεν ἐν ταῖς ἐπιδιαθήκαις ᾔδει διάδοχον, καὶ ταῦτα μηδὲν τὸν ἐν ταῖς διαθήκαις μέμψασθαι δυνάμενος, ἃς ἔγραψεν ὑγιαίνων μὲν τὸ σῶμα, καθαρὰν δὲ τὴν ψυχὴν ἔχων πάθους παντός."},{"number":32,"text":"εἰ μέντοι καὶ κυριωτέραν τὴν τοῦ κάμνοντος κρίσιν τιθείη τις, ἀποκεχειροτονῆσθαι βασιλείας Ἀρχέλαον ὑφʼ ἑαυτοῦ τοῖς εἰς αὐτὴν παρανομηθεῖσιν· ποταπὸν γὰρ ἂν γενέσθαι λαβόντα τὴν ἀρχὴν παρὰ Καίσαρος τὸν πρὶν λαβεῖν τοσούτους ἀνῃρηκότα;"},{"number":33,"text":"Πολλὰ τοιαῦτα διεξελθὼν Ἀντίπατρος καὶ τοὺς πλείστους τῶν συγγενῶν παραστησάμενος ἐφʼ ἑκάστῳ τῶν κατηγορημένων μάρτυρας καταπαύει τὸν λόγον."},{"number":34,"text":"ἀνίσταται δὲ Νικόλαος ὑπὲρ Ἀρχελάου, καὶ τὸν μὲν ἐν τῷ ἱερῷ φόνον ἀναγκαῖον ἀπέφηνεν· πολεμίους γὰρ γεγονέναι τοὺς ἀνῃρημένους οὐ τῆς βασιλείας μόνον ἀλλὰ καὶ τοῦ δικάζοντος αὐτὴν Καίσαρος."},{"number":35,"text":"τῶν δʼ ἄλλων ἐγκλημάτων συμβούλους ἀπεδείκνυεν αὐτοὺς τοὺς κατηγόρους γεγονέναι. τήν γε μὴν ἐπιδιαθήκην ἠξίου διὰ τοῦτο μάλιστα εἶναι κυρίαν, ὅτι βεβαιωτὴν ἐν αὐτῇ Καίσαρα καθίστατο τοῦ διαδόχου·"},{"number":36,"text":"ὁ γὰρ σωφρονῶν ὥστε τῷ δεσπότῃ τῶν ὅλων παραχωρεῖν τῆς ἐξουσίας οὐ δή που περὶ κληρονόμου κρίσιν ἐσφάλλετο, σωφρονῶν δʼ ᾑρεῖτο καὶ τὸν καθιστάμενον ὁ γινώσκων τὸν καθιστάντα."},{"number":37,"text":"Διεξελθόντος δὲ πάντα καὶ Νικολάου παρελθὼν Ἀρχέλαος προπίπτει τῶν Καίσαρος γονάτων ἡσυχῆ. κἀκεῖνος αὐτὸν μάλα φιλοφρόνως ἀναστήσας ἐνέφηνεν μὲν ὡς ἄξιος εἴη τῆς πατρῴας διαδοχῆς, οὐ μήν τι βέβαιον ἀπεφήνατο."},{"number":38,"text":"διαλύσας δὲ τοὺς συνέδρους ἐκείνης τῆς ἡμέρας καθʼ ἑαυτὸν περὶ ὧν διήκουσεν ἐσκέπτετο, εἴτε χρὴ τῶν ἐν ταῖς διαθήκαις καταστῆσαί τινα διάδοχον, εἴτε καὶ πάσῃ τῇ γενεᾷ διανεῖμαι τὴν ἀρχήν· ἐδόκει γὰρ ἐπικουρίας τὸ πλῆθος τῶν προσώπων χρῄζειν."}],"3":[{"number":39,"text":"Πρὶν δὲ ὁρίσαι τι περὶ τούτων Καίσαρα τελευτᾷ μὲν ἡ Ἀρχελάου μήτηρ Μαλθακὴ νοσήσασα, παρὰ Οὐάρου δʼ ἐκομίσθησαν ἐκ Συρίας ἐπιστολαὶ περὶ τῆς Ἰουδαίων ἀποστάσεως,"},{"number":40,"text":"ἣν προϊδόμενος ὁ Οὔαρος, ἀνέβη γὰρ μετὰ τὸν Ἀρχελάου πλοῦν εἰς Ἱεροσόλυμα τοὺς παρακινοῦντας καθέξων, ἐπειδὴ πρόδηλον ἦν τὸ πλῆθος οὐκ ἠρεμῆσον, ἓν τῶν τριῶν ἀπὸ Συρίας ταγμάτων, ὅπερ ἄγων ἧκεν, ἐν τῇ πόλει καταλείπει."},{"number":41,"text":"καὶ αὐτὸς μὲν ὑπέστρεψεν εἰς Ἀντιόχειαν, ἐπελθὼν δὲ ὁ Σαβῖνος ἀφορμὴν αὐτοῖς παρέσχεν νεωτεροποιίας· τούς τε γὰρ φρουροὺς παραδιδόναι τὰς ἄκρας ἐβιάζετο καὶ πικρῶς τὰ βασιλικὰ χρήματα διηρεύνα, πεποιθὼς οὐ μόνον τοῖς ὑπὸ Οὐάρου καταλειφθεῖσι στρατιώταις, ἀλλὰ καὶ πλήθει δούλων ἰδίων, οὓς ἅπαντας ὁπλίσας ὑπηρέταις ἐχρῆτο τῆς πλεονεξίας."},{"number":42,"text":"ἐνστάσης δὲ τῆς πεντηκοστῆς, οὕτω καλοῦσίν τινα ἑορτὴν Ἰουδαῖοι παρʼ ἑπτὰ γινομένην ἑβδομάδας καὶ τὸν ἀριθμὸν τῶν ἡμερῶν προσηγορίαν ἔχουσαν, οὐχ ἡ συνήθης θρησκεία συνήγαγεν τὸν δῆμον, ἀλλʼ ἡ ἀγανάκτησις."},{"number":43,"text":"συνέδραμεν γοῦν πλῆθος ἄπειρον ἔκ τε τῆς Γαλιλαίας καὶ ἐκ τῆς Ἰδουμαίας Ἱεριχοῦντός τε καὶ τῆς ὑπὲρ Ἰορδάνην Περαίας, ὑπερεῖχεν δὲ πλήθει καὶ προθυμίαις ἀνδρῶν ὁ γνήσιος ἐξ αὐτῆς Ἰουδαίας λαός."},{"number":44,"text":"διανείμαντες δὲ σφᾶς αὐτοὺς εἰς τρία μέρη τριχῆ στρατοπεδεύονται, πρός τε τῷ βορείῳ τοῦ ἱεροῦ κλίματι καὶ πρὸς τῷ μεσημβρινῷ κατὰ τὸν ἱππόδρομον, ἡ δὲ τρίτη μοῖρα πρὸς τοῖς βασιλείοις κατὰ δύσιν. περικαθεζόμενοι δὲ πανταχόθεν τοὺς Ῥωμαίους ἐπολιόρκουν."},{"number":45,"text":"Ὁ δὲ Σαβῖνος πρός τε τὸ πλῆθος αὐτῶν ὑποδείσας καὶ τὰ φρονήματα συνεχεῖς μὲν ἀγγέλους ἔπεμπεν πρὸς Οὔαρον ἐπαμύνειν ἐν τάχει δεόμενος ὡς εἰ βραδύνοι κατακοπησομένου τοῦ τάγματος·"},{"number":46,"text":"αὐτὸς δὲ ἐπὶ τὸν ὑψηλότατον τοῦ φρουρίου πύργον ἀναβάς, ὃς ἐκαλεῖτο Φασάηλος ἐπώνυμον ἔχων ἀδελφὸν Ἡρώδου διαφθαρέντα ὑπὸ Πάρθων, ἐντεῦθεν κατέσειεν τοῖς ἐν τῷ τάγματι στρατιώταις ἐπιχειρεῖν τοῖς πολεμίοις· διʼ ἔκπληξιν γὰρ οὐδʼ εἰς τοὺς σφετέρους καταβαίνειν ἐθάρρει."},{"number":47,"text":"παραπεισθέντες δὲ οἱ στρατιῶται προπηδῶσιν εἰς τὸ ἱερὸν καὶ μάχην καρτερὰν τοῖς Ἰουδαίοις συνάπτουσιν, ἐν ᾗ μέχρι μὲν οὐδεὶς καθύπερθεν ἐπήμυνεν περιῆσαν ἐμπειρίᾳ πολέμου τῶν ἀπείρων·"},{"number":48,"text":"ἐπεὶ δὲ πολλοὶ Ἰουδαίων ἀναβάντες ἐπὶ τὰς στοὰς κατὰ κεφαλῆς αὐτῶν ἠφίεσαν τὰ βέλη, συνετρίβοντο πολλοὶ καὶ οὔτε τοὺς ἄνωθεν βάλλοντας ἀμύνεσθαι ῥᾴδιον ἦν οὔτε τοὺς συστάδην μαχομένους ὑπομένειν."},{"number":49,"text":"Καταπονούμενοι μὲν πρὸς ἀμφοτέρων ὑποπιμπρᾶσιν τὰς στοάς, ἔργα θαυμάσια μεγέθους τε καὶ πολυτελείας ἕνεκεν· οἱ δʼ ἐπʼ αὐτῶν ἐξαίφνης ὑπὸ τῆς φλογὸς περισχεθέντες πολλοὶ μὲν ἐν αὐτῇ διεφθάρησαν, πολλοὶ δὲ ὑπὸ τῶν πολεμίων πηδῶντες εἰς αὐτούς, τινὲς δʼ εἰς τοὐπίσω κατὰ τοῦ τείχους ἐκρημνίζοντο, ἔνιοι δʼ ὑπʼ ἀμηχανίας τοῖς ἰδίοις ξίφεσιν τὸ πῦρ ἔφθανον·"},{"number":50,"text":"ὅσοι δὲ καθερπύσαντες ἀπὸ τῶν τειχῶν ᾖξαν εἰς τοὺς Ῥωμαίους εὐμεταχείριστοι διὰ τὴν ἔκπληξιν ἦσαν. καὶ τῶν μὲν ἀπολωλότων, τῶν δʼ ὑπὸ τοῦ δέους σκεδασθέντων ἐρήμῳ τῷ τοῦ θεοῦ θησαυρῷ προσπεσόντες οἱ στρατιῶται περὶ τετρακόσια τάλαντα διήρπασαν, ὧν ὅσα μὴ διεκλάπη Σαβῖνος ἤθροισεν."},{"number":51,"text":"Ἰουδαίους δὲ ἥ τε τῶν ἔργων καὶ ἀνδρῶν φθορὰ πολὺ πλείους καὶ μαχιμωτέρους ἐπισυνέστησεν Ῥωμαίοις καὶ περισχόντες τὰ βασίλεια πάντας ἠπείλουν διαφθείρειν, εἰ μὴ θᾶττον ἀπίοιεν· ὑπισχνοῦντο γὰρ ἄδειαν τῷ Σαβίνῳ βουλομένῳ μετὰ τοῦ τάγματος ἐξιέναι."},{"number":52,"text":"συνελάμβανον δʼ αὐτοῖς οἱ πλείους τῶν βασιλικῶν αὐτομολήσαντες. τὸ μέντοι πολεμικώτατον μέρος, Σεβαστηνοὶ τρισχίλιοι Ῥοῦφός τε καὶ Γρᾶτος ἐπὶ τούτοις, ὁ μὲν τοὺς πεζοὺς τῶν βασιλικῶν ὑπʼ αὐτὸν ἔχων, Ῥοῦφος δὲ τοὺς ἱππεῖς, ὢν ἑκάτερος καὶ χωρὶς ὑπηκόου δυνάμεως διʼ ἀλκὴν καὶ σύνεσιν πολέμου ῥοπή, προσέθεντο Ῥωμαίοις."},{"number":53,"text":"Ἰουδαῖοι μὲν οὖν ἐνέκειντο τῇ πολιορκίᾳ τῶν τειχῶν ἅμα πειρώμενοι τοῦ φρουρίου καὶ τοῖς περὶ τὸν Σαβῖνον ἐμβοῶντες ἀπιέναι μηδʼ ἐμποδὼν αὐτοῖς γενέσθαι διὰ χρόνου πολλοῦ κομιζομένοις τὴν πάτριον αὐτονομίαν."},{"number":54,"text":"Σαβίνῳ δʼ ἀγαπητὸν μὲν ἦν ὑπεξελθεῖν, ἠπίστει δὲ ταῖς ὑποσχέσεσιν καὶ τὸ πρᾷον αὐτῶν δέλεαρ εἰς ἐνέδραν ὑπώπτευεν· ἅμα δὲ καὶ τὴν ἀπὸ Οὐάρου βοήθειαν ἐλπίζων διέτριβεν τὴν πολιορκίαν."}],"4":[{"number":55,"text":"Ἐν δὲ τούτῳ καὶ τὰ κατὰ τὴν χώραν πολλαχόθεν ἐταράσσετο, καὶ συχνοὺς βασιλειᾶν ὁ καιρὸς ἀνέπειθεν. κατὰ μέν γε τὴν Ἰδουμαίαν δισχίλιοι τῶν ὑπὸ Ἡρώδῃ πάλαι στρατευσαμένων συστάντες ἔνοπλοι διεμάχοντο τοῖς βασιλικοῖς, οἷς Ἀχίαβος ἀνεψιὸς βασιλέως ἀπὸ τῶν ἐρυμνοτάτων χωρίων ἐπολέμει ὑποφεύγων τὴν ἐν τοῖς πεδίοις συμπλοκήν·"},{"number":56,"text":"ἐν δὲ Σεπφώρει τῆς Γαλιλαίας Ἰούδας υἱὸς Ἐζεκία τοῦ κατατρέχοντός ποτε τὴν χώραν ἀρχιλῃστοῦ καὶ χειρωθέντος ὑφʼ Ἡρώδου βασιλέως συστήσας πλῆθος οὐκ ὀλίγον ἀναρρήγνυσιν τὰς βασιλικὰς ὁπλοθήκας καὶ τοὺς περὶ αὐτὸν ὁπλίσας τοῖς τὴν δυναστείαν ζηλοῦσιν ἐπεχείρει."},{"number":57,"text":"Κατὰ δὲ τὴν Περαίαν Σίμων τις τῶν βασιλικῶν δούλων εὐμορφίᾳ σώματος καὶ μεγέθει πεποιθὼς περιτίθησιν μὲν ἑαυτῷ διάδημα, περιιὼν δὲ μεθʼ ὧν συνήθροισεν λῃστῶν τά τε ἐν Ἱεριχοῖ βασίλεια καταπίμπρησιν καὶ πολλὰς ἑτέρας τῶν πολυτελῶν ἐπαύλεις, ἁρπαγὰς ῥᾳδίως ἐκ τοῦ πυρὸς αὑτῷ ποριζόμενος."},{"number":58,"text":"κἂν ἔφθη πᾶσαν οἴκησιν εὐπρεπῆ καταφλέξας, εἰ μὴ Γρᾶτος ὁ τῶν βασιλικῶν πεζῶν ἡγεμὼν τούς τε Τραχωνίτας τοξότας καὶ τὸ μαχιμώτατον τῶν Σεβαστηνῶν ἀναλαβὼν ὑπαντιάζει τὸν ἄνδρα."},{"number":59,"text":"τῶν μὲν οὖν Περαίων συχνοὶ διεφθάρησαν ἐν τῇ μάχῃ, τὸν Σίμωνα δʼ αὐτὸν ἀναφεύγοντα διʼ ὀρθίου φάραγγος ὁ Γρᾶτος ὑποτέμνεται καὶ φεύγοντος ἐκ πλαγίου τὸν αὐχένα πλήξας ἀπέρραξε. κατεφλέγη δὲ καὶ τὰ πλησίον Ἰορδάνου βασίλεια κατὰ βηθαραμινενθα συστάντων ἑτέρων τινῶν ἐκ τῆς Περαίας."},{"number":60,"text":"Τότε καὶ ποιμήν τις ἀντιποιηθῆναι βασιλείας ἐτόλμησεν· Ἀθρογγαῖος ἐκαλεῖτο, προυξένει δʼ αὐτῷ τὴν ἐλπίδα σώματος ἰσχὺς καὶ ψυχὴ θανάτου καταφρονοῦσα, πρὸς δὲ τούτοις ἀδελφοὶ τέσσαρες ὅμοιοι."},{"number":61,"text":"τούτων ἑκάστῳ λόχον ὑποζεύξας ἔνοπλον ὥσπερ στρατηγοῖς ἐχρῆτο καὶ σατράπαις ἐπὶ τὰς καταδρομάς, αὐτὸς δὲ καθάπερ βασιλεὺς τῶν σεμνοτέρων ἥπτετο πραγμάτων."},{"number":62,"text":"τότε μὲν οὖν ἑαυτῷ περιτίθησιν διάδημα, διέμεινεν δʼ ὕστερον οὐκ ὀλίγον χρόνον τὴν χώραν κατατρέχων σὺν τοῖς ἀδελφοῖς· καὶ τὸ κτείνειν αὐτοῖς προηγούμενον ἦν Ῥωμαίους τε καὶ τοὺς βασιλικούς, διέφευγεν δὲ οὐδὲ Ἰουδαίων εἴ τις εἰς χεῖρας ἔλθοι φέρων κέρδος."},{"number":63,"text":"ἐτόλμησαν δέ ποτε Ῥωμαίων λόχον ἄθρουν περισχεῖν κατʼ Ἀμμαοῦντα· σῖτα δʼ οὗτοι καὶ ὅπλα διεκόμιζον τῷ τάγματι. τὸν μὲν οὖν ἑκατοντάρχην αὐτῶν Ἄρειον καὶ τεσσαράκοντα τοὺς γενναιοτάτους κατηκόντισαν, οἱ δὲ λοιποὶ κινδυνεύοντες ταὐτὸ παθεῖν Γράτου σὺν τοῖς Σεβαστηνοῖς ἐπιβοηθήσαντος ἐξέφυγον."},{"number":64,"text":"πολλὰ τοιαῦτα τοὺς ἐπιχωρίους καὶ τοὺς ἀλλοφύλους παρʼ ὅλον τὸν πόλεμον ἐργασάμενοι μετὰ χρόνον οἱ μὲν τρεῖς ἐχειρώθησαν, ὑπʼ Ἀρχελάου μὲν ὁ πρεσβύτατος, οἱ δʼ ἑξῆς δύο Γράτῳ καὶ Πτολεμαίῳ περιπεσόντες· ὁ δὲ τέταρτος Ἀρχελάῳ προσεχώρησεν κατὰ δεξιάν."},{"number":65,"text":"τοῦτο μὲν δὴ τὸ τέλος ὕστερον αὐτοὺς ἐξεδέχετο, τότε δὲ λῃστρικοῦ πολέμου τὴν Ἰουδαίαν πᾶσαν ἐνεπίμπλασαν."}],"5":[{"number":66,"text":"Οὐάρῳ δὲ δεξαμένῳ τὰ παρὰ Σαβίνου καὶ τῶν ἡγεμόνων γράμματα δεῖσαί τε περὶ τοῦ τάγματος ὅλου παρέστη καὶ σπεύδειν ἐπὶ τὴν βοήθειαν."},{"number":67,"text":"ἀναλαβὼν δὴ τὰ λοιπὰ δύο τάγματα καὶ τὰς σὺν αὐτοῖς τέσσαρας ἴλας ἱππέων ἐπὶ Πτολεμαΐδος ᾔει, προστάξας ἐκεῖ καὶ τοὺς παρὰ τῶν βασιλέων καὶ δυναστῶν ἐπικούρους συνελθεῖν· προσέλαβεν δὲ καὶ παρὰ Βηρυτίων διερχόμενος τὴν πόλιν χιλίους καὶ πεντακοσίους ὁπλίτας."},{"number":68,"text":"ἐπεὶ δʼ εἰς τὴν Πτολεμαΐδα τό τε ἄλλο συμμαχικὸν πλῆθος αὐτῷ παρῆν καὶ κατὰ τὸ πρὸς Ἡρώδην ἔχθος Ἀρέτας ὁ Ἄραψ οὐκ ὀλίγην ἄγων δύναμιν ἱππικήν τε καὶ πεζικήν, μέρος τῆς στρατιᾶς εὐθέως ἔπεμπεν εἰς τὴν Γαλιλαίαν γειτνιῶσαν τῇ Πτολεμαΐδι καὶ Γάιον ἡγεμόνα τῶν αὐτοῦ φίλων, ὃς τούς τε ὑπαντιάσαντας τρέπεται καὶ Σέπφωριν πόλιν ἑλὼν αὐτὴν μὲν ἐμπίπρησι, τοὺς δʼ ἐνοικοῦντας ἀνδραποδίζεται."},{"number":69,"text":"μετὰ δὲ τῆς ὅλης δυνάμεως αὐτὸς Οὔαρος εἰς Σαμάρειαν ἐλάσας τῆς μὲν πόλεως ἀπέσχετο μηδὲν ἐν τοῖς τῶν ἄλλων θορύβοις παρακεκινηκυῖαν εὑρών, αὐλίζεται δὲ περί τινα κώμην Ἀροῦν καλουμένην· κτῆμα δὲ ἦν Πτολεμαίου καὶ διὰ τοῦτο ὑπὸ τῶν Ἀράβων διηρπάσθη μηνιόντων καὶ τοῖς Ἡρώδου φίλοις."},{"number":70,"text":"ἔνθεν εἰς Σαπφὼ πρόεισιν κώμην ἑτέραν ἐρυμνήν, ἣν ὁμοίως διήρπασαν τάς τε προσόρους πάσας ὅσαις ἐπετύγχανον. πυρὸς δὲ καὶ φόνου πεπλήρωτο πάντα καὶ πρὸς τὰς ἁρπαγὰς τῶν Ἀράβων οὐδὲν ἀντεῖχεν."},{"number":71,"text":"κατεφλέγη δὲ καὶ Ἀμμαοῦς φυγόντων τῶν οἰκητόρων, Οὐάρου διʼ ὀργὴν τῶν περὶ Ἄρειον ἀποσφαγέντων κελεύσαντος."},{"number":72,"text":"Ἐνθένδε εἰς Ἱεροσόλυμα προελθὼν ὀφθείς τε μόνον μετὰ τῆς δυνάμεως τὰ στρατόπεδα τῶν Ἰουδαίων διεσκέδασεν. καὶ οἱ μὲν ᾤχοντο φυγόντες ἀνὰ τὴν χώραν·"},{"number":73,"text":"δεξάμενοι δὲ αὐτὸν οἱ κατὰ τὴν πόλιν ἀπεσκευάζοντο τὰς αἰτίας τῆς ἀποστάσεως, αὐτοὶ μὲν οὐδὲν παρακινῆσαι λέγοντες, διὰ δὲ τὴν ἑορτὴν ἀναγκαίως δεξάμενοι τὸ πλῆθος συμπολιορκηθῆναι μᾶλλον Ῥωμαίοις ἢ συμπολεμῆσαι τοῖς ἀποστᾶσιν."},{"number":74,"text":"προϋπηντήκεισαν δὲ αὐτῷ Ἰώσηπος ὁ ἀνεψιὸς Ἀρχελάου καὶ σὺν Γράτῳ Ῥοῦφος, ἄγοντες ἅμα τῷ βασιλικῷ στρατῷ καὶ τοὺς Σεβαστηνούς, οἵ τε ἀπὸ τοῦ Ῥωμαϊκοῦ τάγματος τὸν συνήθη τρόπον κεκοσμημένοι· Σαβῖνος μὲν γὰρ οὐδʼ εἰς ὄψιν ὑπομείνας ἐλθεῖν Οὐάρῳ προεξῆλθεν τῆς πόλεως ἐπὶ θάλασσαν."},{"number":75,"text":"Οὔαρος δὲ κατὰ μοῖραν τῆς στρατιᾶς ἐπὶ τοὺς αἰτίους τοῦ κινήματος ἔπεμψεν περὶ τὴν χώραν, καὶ πολλῶν ἀγομένων τοὺς μὲν ἧττον θορυβώδεις φανέντας ἐφρούρει, τοὺς δὲ αἰτιωτάτους ἀνεσταύρωσεν περὶ δισχιλίους."},{"number":76,"text":"Ἠγγέλθη δʼ αὐτῷ κατὰ τὴν Ἰδουμαίαν ἔτι συμμένειν μυρίους ὁπλίτας. ὁ δὲ τοὺς μὲν Ἄραβας εὑρὼν οὐ συμμάχων ἦθος ἔχοντας, ἀλλʼ ἰδίῳ πάθει στρατευομένους καὶ πέρα τῆς ἑαυτοῦ προαιρέσεως τὴν χώραν κακοῦντας ἔχθει τῷ πρὸς Ἡρώδην ἀποπέμπεται, μετὰ δὲ τῶν ἰδίων ταγμάτων ἐπὶ τοὺς ἀφεστῶτας ἠπείγετο."},{"number":77,"text":"κἀκεῖνοι πρὶν εἰς χεῖρας ἐλθεῖν Ἀχιάβου συμβουλεύσαντος σφᾶς αὐτοὺς παρέδοσαν, Οὔαρος δὲ τῷ πλήθει μὲν ἠφίει τὰς αἰτίας, τοὺς δὲ ἡγεμόνας ἐξετασθησομένους ἔπεμπεν ἐπὶ Καίσαρα."},{"number":78,"text":"Καῖσαρ δὲ τοῖς μὲν ἄλλοις συνέγνω, τινὰς δὲ τῶν τοῦ βασιλέως συγγενῶν, ἦσαν γὰρ ἐν αὐτοῖς ἔνιοι προσήκοντες Ἡρώδῃ κατὰ γένος, κολάσαι προσέταξεν, ὅτι κατʼ οἰκείου βασιλέως ἐστρατεύσαντο."},{"number":79,"text":"Οὔαρος μὲν οὖν τοῦτον τὸν τρόπον καταστησάμενος τὰ ἐν Ἱεροσολύμοις καὶ φρουρὰν καταλιπὼν τὸ καὶ πρότερον τάγμα εἰς Ἀντιόχειαν ἐπάνεισιν."}],"6":[{"number":80,"text":"Ἀρχελάῳ δʼ ἐπὶ Ῥώμης πάλιν ἄλλη συνίσταται δίκη πρὸς Ἰουδαίους, οἳ πρὸ τῆς ἀποστάσεως ἐπιτρέψαντος Οὐάρου πρέσβεις ἐξεληλύθεσαν περὶ τῆς τοῦ ἔθνους αὐτονομίας· ἦσαν δὲ πεντήκοντα μὲν οἱ παρόντες, συμπαρίσταντο δὲ αὐτοῖς τῶν ἐπὶ Ῥώμης Ἰουδαίων ὑπὲρ ὀκτακισχιλίους."},{"number":81,"text":"ἀθροίσαντος δὲ Καίσαρος συνέδριον τῶν ἐν τέλει Ῥωμαίων καὶ τῶν φίλων ἐν τῷ κατὰ τὸ Παλάτιον Ἀπόλλωνος ἱερῷ, κτίσμα δʼ ἦν ἴδιον αὐτοῦ θαυμασίῳ πολυτελείᾳ κεκοσμημένον, μετὰ μὲν τῶν πρεσβευτῶν τὸ Ἰουδαϊκὸν πλῆθος ἔστη,"},{"number":82,"text":"σὺν δὲ τοῖς φίλοις ἄντικρυς Ἀρχέλαος, τῶν δὲ τούτου συγγενῶν οἱ φίλοι παρʼ οὐδετέροις, συμπαρίστασθαι μὲν Ἀρχελάῳ διὰ μῖσος καὶ φθόνον οὐχ ὑπομένοντες, ὀφθῆναι δὲ μετὰ τῶν κατηγόρων ὑπὸ Καίσαρος αἰδούμενοι."},{"number":83,"text":"τούτοις παρῆν καὶ Φίλιππος ἀδελφὸς Ἀρχελάου, προπεμφθεὶς κατʼ εὔνοιαν ὑπὸ Οὐάρου δυοῖν ἕνεκα, Ἀρχελάῳ τε συναγωνίσασθαι, κἂν διανέμῃ τὸν Ἡρώδου Καῖσαρ οἶκον πᾶσι τοῖς ἐγγόνοις, κλήρου τινὸς ἀξιωθῆναι."},{"number":84,"text":"Ἐπιτραπὲν δὲ λέγειν τοῖς κατηγόροις τὰς Ἡρώδου παρανομίας πρῶτον διεξῄεσαν, οὐ βασιλέα λέγοντες ἀλλὰ τῶν πώποτε τυραννησάντων ὠμότατον ἐνηνοχέναι τύραννον· πλείστων γοῦν ἀνῃρημένων ὑπʼ αὐτοῦ τοιαῦτα πεπονθέναι τοὺς καταλειφθέντας, ὥστε μακαρίζεσθαι τοὺς ἀπολωλότας·"},{"number":85,"text":"βεβασανικέναι γὰρ οὐ μόνον τὰ σώματα τῶν ὑποτεταγμένων ἀλλὰ καὶ τὰς πόλεις· τὰς μὲν γὰρ ἰδίας λελωβῆσθαι, τὰς δὲ τῶν ἀλλοφύλων κεκοσμηκέναι καὶ τὸ τῆς Ἰουδαίας αἷμα κεχαρίσθαι τοῖς ἔξωθεν δήμοις."},{"number":86,"text":"ἀντὶ δὲ τῆς παλαιᾶς εὐδαιμονίας καὶ τῶν πατρίων νόμων πενίας τὸ ἔθνος καὶ παρανομίας ἐσχάτης πεπληρωκέναι, καθόλου δὲ πλείους ὑπομεμενηκέναι τὰς ἐξ Ἡρώδου συμφορὰς ἐν ὀλίγοις ἔτεσιν Ἰουδαίους ὧν ἐν παντὶ τῷ χρόνῳ μετὰ τὴν ἐκ Βαβυλῶνος ἀναχώρησιν ἔπαθον οἱ πρόγονοι Ξέρξου βασιλεύοντος ἀπαναστάντες."},{"number":87,"text":"εἰς τοσοῦτον μέντοι μετριότητος καὶ τοῦ δυστυχεῖν ἔθους προελθεῖν, ὥστε ὑπομεῖναι τῆς πικρᾶς δουλείας καὶ διαδοχὴν αὐθαίρετον·"},{"number":88,"text":"Ἀρχέλαον γοῦν τὸν τηλικούτου τυράννου παῖδα μετὰ τὴν τοῦ πατρὸς τελευτὴν βασιλέα τε προσειπεῖν ἑτοίμως καὶ συμπενθῆσαι τὸν Ἡρώδου θάνατον αὐτῷ καὶ συνεύξασθαι περὶ τῆς διαδοχῆς."},{"number":89,"text":"τὸν δʼ ὥσπερ ἀγωνιάσαντα, μὴ νόθος υἱὸς εἶναι δόξειεν Ἡρώδου, προοιμιάσασθαι τὴν βασιλείαν τρισχιλίων πολιτῶν φόνῳ, καὶ τοσαῦτα μὲν παρεστακέναι θύματα περὶ τῆς ἀρχῆς τῷ θεῷ, τοσούτοις δʼ ἐμπεπληκέναι νεκροῖς τὸ ἱερὸν ἐν ἑορτῇ."},{"number":90,"text":"τοὺς μέντοι περιλειφθέντας ἐκ τοσούτων κακῶν εἰκότως ἐπεστράφθαι ποτὲ ἤδη πρὸς τὰς συμφορὰς καὶ πολέμου νόμῳ τὰς πληγὰς ἐθέλειν κατὰ πρόσωπον δέχεσθαι, δεῖσθαι δὲ Ῥωμαίων ἐλεῆσαι τά τε τῆς Ἰουδαίας λείψανα καὶ μὴ τὸ περισσὸν αὐτῆς ὑπορρῖψαι τοῖς ὠμῶς σπαράττουσιν,"},{"number":91,"text":"συνάψαντας δὲ τῇ Συρίᾳ τὴν χώραν αὐτῶν διοικεῖν ἐπʼ ἰδίοις ἡγεμόσιν· ἐπιδείξεσθαι γάρ, ὡς οἱ νῦν στασιώδεις διαβαλλόμενοι καὶ πολεμικοὶ φέρειν οἴδασιν μετρίους ἡγεμόνας."},{"number":92,"text":"Ἰουδαῖοι μὲν οὖν ἐκ τῆς κατηγορίας κατέληξαν εἰς τοιαύτην ἀξίωσιν, ἀναστὰς δὲ Νικόλαος ἀπελύσατο μὲν τὰς εἰς τοὺς βασιλεῖς αἰτίας, κατηγόρει δὲ τοῦ ἔθνους τό τε δύσαρκτον καὶ τὸ δυσπειθὲς φύσει πρὸς τοὺς βασιλεῖς. συνδιέβαλλε δὲ καὶ τοὺς Ἀρχελάου συγγενεῖς, ὅσοι πρὸς τοὺς κατηγόρους ἀφεστήκεσαν."},{"number":93,"text":"Τότε μὲν οὖν Καῖσαρ ἀκούσας ἑκατέρων διέλυσε τὸ συνέδριον, μετὰ δʼ ἡμέρας ὀλίγας τὸ μὲν ἥμισυ τῆς βασιλείας Ἀρχελάῳ δίδωσιν ἐθνάρχην προσειπών, ὑποσχόμενος δὲ καὶ βασιλέα ποιήσειν,"},{"number":94,"text":"εἰ ἄξιον ἑαυτὸν παράσχοι, τὸ δὲ λοιπὸν ἥμισυ διελὼν εἰς δύο τετραρχίας δυσὶν ἑτέροις παισὶν Ἡρώδου δίδωσιν, τὴν μὲν Φιλίππῳ, τὴν δὲ Ἀντίπᾳ τῷ πρὸς Ἀρχέλαον ἀμφισβητοῦντι περὶ τῆς βασιλείας."},{"number":95,"text":"ἐγένετο δὲ ὑπὸ τούτῳ μὲν ἥ τε Περαία καὶ Γαλιλαία, πρόσοδος διακόσια τάλαντα, Βατανέα δὲ καὶ Τράχων Αὐρανῖτίς τε καὶ μέρη τινὰ τοῦ Ζήνωνος οἴκου τὰ περὶ ἰννάνω, πρόσοδον ἔχοντα ταλάντων ἑκατόν, ὑπὸ Φιλίππῳ τέτακτο."},{"number":96,"text":"τῆς Ἀρχελάου δʼ ἐθναρχίας Ἰδουμαία τε καὶ Ἰουδαία πᾶσα καὶ Σαμαρεῖτις ἦν κεκουφισμένη τετάρτῳ μέρει τῶν φόρων εἰς τιμὴν τοῦ μὴ μετὰ τῶν ἄλλων ἀποστῆναι."},{"number":97,"text":"πόλεις δʼ ὑπηκόους παρέλαβεν Στράτωνος πύργον καὶ Σεβαστὴν καὶ Ἰόππην καὶ Ἱεροσόλυμα· τὰς γὰρ Ἑλληνίδας Γάζαν καὶ Γάδαρα καὶ Ἵππον ἀποτεμόμενος τῆς βασιλείας προσέθηκεν Συρίᾳ. πρόσοδος ἦν τῆς Ἀρχελάῳ δοθείσης χώρας τετρακοσίων ταλάντων."},{"number":98,"text":"Σαλώμη δὲ πρὸς οἷς ὁ βασιλεὺς ἐν ταῖς διαθήκαις κατέλιπεν Ἰαμνείας τε καὶ Ἀζώτου καὶ Φασαηλίδος ἀποδείκνυται δεσπότις, χαρίζεται δʼ αὐτῇ Καῖσαρ καὶ τὰ ἐν Ἀσκάλωνι βασίλεια· συνήγετο δʼ ἐκ πάντων ἑξήκοντα προσόδου τάλαντα· τὸν δὲ οἶκον αὐτῆς ὑπὸ τὴν Ἀρχελάου τοπαρχίαν ἔταξεν."},{"number":99,"text":"τῆς δʼ ἄλλης Ἡρώδου γενεᾶς ἕκαστος τὸ καταλειφθὲν ἐν ταῖς διαθήκαις ἐκομίζετο. δυσὶ δʼ αὐτοῦ θυγατράσι παρθένοις Καῖσαρ ἔξωθεν χαρίζεται πεντήκοντα μυριάδας ἀργυρίου καὶ συνῴκισεν αὐτὰς τοῖς Φερώρα παισίν."},{"number":100,"text":"μετὰ δὲ τὸν οἶκον ἐπιδιένειμεν αὐτοῖς τὴν ἑαυτῷ καταλειφθεῖσαν ὑφʼ Ἡρώδου δωρεὰν οὖσαν χιλίων ταλάντων, εὐτελῆ τινα τῶν κειμηλίων εἰς τὴν τοῦ κατοιχομένου τιμὴν ἐξελόμενος."}],"7":[{"number":101,"text":"Κἀν τούτῳ νεανίας τις Ἰουδαῖος μὲν τὸ γένος, τραφεὶς δὲ ἐν Σιδῶνι παρά τῳ τῶν Ῥωμαίων ἀπελευθέρῳ, διʼ ὁμοιότητα μορφῆς ψευδόμενος ἑαυτὸν Ἀλέξανδρον τὸν ἀναιρεθέντα ὑφʼ Ἡρώδου κατʼ ἐλπίδα τοῦ λήσειν ἧκεν εἰς Ῥώμην."},{"number":102,"text":"συνεργὸς δʼ ἦν τις ὁμόφυλος αὐτῷ πάντα τὰ κατὰ τὴν βασιλείαν ἐπιστάμενος, ὑφʼ οὗ διδαχθεὶς ἔλεγεν, ὡς οἱ πεμφθέντες ἐπὶ τὴν ἀναίρεσιν αὐτοῦ τε καὶ Ἀριστοβούλου διʼ οἶκτον ἐκκλέψειαν αὐτοὺς ὁμοίων ὑποβολῇ σωμάτων."},{"number":103,"text":"τούτοις γοῦν τοὺς ἐν Κρήτῃ Ἰουδαίους ἐξαπατήσας καὶ λαμπρῶς ἐφοδιασθεὶς διέπλευσεν εἰς Μῆλον· ἔνθα συναγείρας πολλῷ πλέον διʼ ὑπερβολὴν ἀξιοπιστίας ἀνέπεισεν καὶ τοὺς ἰδιοξένους εἰς Ῥώμην αὐτῷ συνεκπλεῦσαι."},{"number":104,"text":"καταχθεὶς δὲ εἰς Δικαιάρχειαν δῶρά τε παμπληθῆ παρὰ τῶν ἐκεῖ Ἰουδαίων λαμβάνει καὶ καθάπερ βασιλεὺς ὑπὸ τῶν πατρῴων προεπέμφθη φίλων. προεληλύθει δʼ εἰς τοσοῦτον πίστεως τὸ τῆς μορφῆς ὅμοιον, ὥστε τοὺς ἑωρακότας Ἀλέξανδρον καὶ σαφῶς ἐπισταμένους διόμνυσθαι τοῦτον εἶναι."},{"number":105,"text":"τό γε μὴν Ἰουδαϊκὸν ἐν τῇ Ῥώμῃ ἅπαν ἐξεχύθη πρὸς τὴν θέαν αὐτοῦ, καὶ πλῆθος ἄπειρον ἦν περὶ τοὺς στενωπούς, διʼ ὧν ἐκομίζετο· καὶ γὰρ προῆλθον εἰς τοσοῦτον φρενοβλαβείας οἱ Μήλιοι, ὥστε φορείῳ τε αὐτὸν κομίζειν καὶ θεραπείαν βασιλικὴν ἰδίοις παρασχεῖν ἀναλώμασιν."},{"number":106,"text":"Καῖσαρ δὲ γινώσκων [ἀκριβῶς] τοὺς Ἀλεξάνδρου χαρακτῆρας, κατηγόρητο γὰρ ὑφʼ Ἡρώδου παρʼ αὐτῷ, συνεώρα μὲν καὶ πρὶν ἰδεῖν τὸν ἄνθρωπον τὴν τῆς ὁμοιότητος ἀπάτην, διδοὺς δέ τι καὶ πίστεως ταῖς ἱλαρωτέραις ἐλπίσιν Κέλαδόν τινα πέμπει τῶν σαφῶς ἐπισταμένων Ἀλέξανδρον, κελεύσας ἀγαγεῖν αὐτῷ τὸν νεανίσκον."},{"number":107,"text":"ὁ δὲ ὡς εἶδεν, ἐτεκμήρατο μὲν τάχιστα καὶ τὰς διαφορὰς τοῦ προσώπου τό τε ὅλον σῶμα σκληρότερόν τε καὶ δουλοφανὲς καταμαθὼν ἐνόησεν πᾶν τὸ σύνταγμα,"},{"number":108,"text":"πάνυ δὲ αὐτὸν παρώξυνεν ἡ τόλμα τῶν παρʼ αὐτοῦ λεγομένων· τοῖς γὰρ πυνθανομένοις περὶ Ἀριστοβούλου σώζεσθαι μὲν κἀκεῖνον ἔλεγεν, ἀπολελεῖφθαι δὲ ἐπίτηδες ἐν Κύπρῳ τὰς ἐπιβουλὰς φυλασσόμενον· ἧττον γὰρ ἐπιχειρεῖσθαι διεζευγμένους."},{"number":109,"text":"ἀπολαβόμενος οὖν αὐτὸν κατʼ ἰδίαν μισθόν, ἔφη, παρὰ Καίσαρος ἔχεις τὸ ζῆν τοῦ μηνῦσαι τὸν ἀναπείσαντά σε πλανᾶσθαι τηλικαῦτα. κἀκεῖνος αὐτῷ δηλώσειν εἰπὼν ἕπεται πρὸς Καίσαρα καὶ τὸν Ἰουδαῖον ἐνδείκνυται καταχρησάμενον αὐτοῦ τῇ ὁμοιότητι πρὸς ἐργασίαν· τοσαῦτα γὰρ εἰληφέναι δῶρα καθʼ ἑκάστην πόλιν ὅσα ζῶν Ἀλέξανδρος οὐκ ἔλαβεν."},{"number":110,"text":"γελάσας δὲ Καῖσαρ ἐπὶ τούτοις τὸν μὲν ψευδαλέξανδρον διʼ εὐεξίαν σώματος ἐγκατέταξεν τοῖς ἐρέταις, τὸν ἀναπείσαντα δὲ ἐκέλευσεν ἀναιρεθῆναι· Μηλίοις δʼ ἤρκεσεν ἐπιτίμιον τῆς ἀνοίας τὰ ἀναλώματα."},{"number":111,"text":"Παραλαβὼν δὲ τὴν ἐθναρχίαν Ἀρχέλαος καὶ κατὰ μνήμην τῶν πάλαι διαφορῶν οὐ μόνον Ἰουδαίοις ἀλλὰ καὶ Σαμαρεῦσι χρησάμενος ὠμῶς, πρεσβευσαμένων ἑκατέρων κατʼ αὐτοῦ πρὸς Καίσαρα ἔτει τῆς ἀρχῆς ἐνάτῳ φυγαδεύεται μὲν αὐτὸς εἰς Βίενναν πόλιν τῆς Γαλλίας, ἡ οὐσία δʼ αὐτοῦ τοῖς Καίσαρος θησαυροῖς ἐγκατατάσσεται."},{"number":112,"text":"πρὶν κληθῆναι δʼ αὐτὸν ὑπὸ τοῦ Καίσαρος ὄναρ ἰδεῖν φασιν τοιόνδε· ἔδοξεν ὁρᾶν στάχυς ἐννέα πλήρεις καὶ μεγάλους ὑπὸ βοῶν καταβιβρωσκομένους. μεταπεμψάμενος δὲ τοὺς μάντεις καὶ τῶν Χαλδαίων τινὰς ἐπυνθάνετο, τί σημαίνειν δοκοῖεν."},{"number":113,"text":"ἄλλων δʼ ἄλλως ἐξηγουμένων Σίμων τις Ἐσσαῖος τὸ γένος ἔφη τοὺς μὲν στάχυς ἐνιαυτοὺς νομίζειν, βόας δὲ μεταβολὴν πραγμάτων διὰ τὸ τὴν χώραν ἀροτριῶντας ἀλλάσσειν· ὥστε βασιλεύσειν μὲν αὐτὸν τὸν τῶν ἀσταχύων ἀριθμόν, ἐν ποικίλαις δὲ πραγμάτων μεταβολαῖς γενόμενον τελευτήσειν. ταῦτα ἀκούσας Ἀρχέλαος μετὰ πέντε ἡμέρας ἐπὶ τὴν δίκην ἐκλήθη."},{"number":114,"text":"Ἄξιον δὲ μνήμης ἡγησάμην καὶ τὸ τῆς γυναικὸς αὐτοῦ Γλαφύρας ὄναρ, ἥπερ ἦν θυγάτηρ μὲν Ἀρχελάου τοῦ Καππαδόκων βασιλέως, γυνὴ δὲ Ἀλεξάνδρου γεγονυῖα τὸ πρῶτον, ὃς ἦν ἀδελφὸς Ἀρχελάου περὶ οὗ διέξιμεν, υἱὸς δὲ Ἡρώδου τοῦ βασιλέως, ὑφʼ οὗ καὶ ἀνῃρέθη, καθάπερ δεδηλώκαμεν."},{"number":115,"text":"μετὰ δὲ τὸν ἐκείνου θάνατον συνῴκησεν Ἰόβᾳ τῷ βασιλεύοντι Λιβύης, οὗ τελευτήσαντος ἐπανελθοῦσαν αὐτὴν καὶ χηρεύουσαν παρὰ τῷ πατρὶ θεασάμενος ὁ ἐθνάρχης Ἀρχέλαος ἐπὶ τοσοῦτον ἔρωτος ἦλθεν, ὥστε παραχρῆμα τὴν συνοικοῦσαν αὐτῷ Μαριάμμην ἀποπεμψάμενος ἐκείνην ἀγαγέσθαι."},{"number":116,"text":"παραγενομένη τοίνυν εἰς Ἰουδαίαν μετʼ ὀλίγον τῆς ἀφίξεως χρόνον ἔδοξεν ἐπιστάντα τὸν Ἀλέξανδρον αὐτῇ λέγειν ἀπέχρη μὲν ὁ κατὰ Λιβύην σοι γάμος, σὺ δὲ οὐκ ἀρκεσθεῖσα τούτῳ πάλιν ἐπὶ τὴν ἐμὴν ἀνακάμπτεις ἑστίαν, τρίτον ἄνδρα καὶ ταῦτα τὸν ἀδελφόν, ὦ τολμηρά, τὸν ἐμὸν ᾑρημένη. πλὴν οὐ περιόψομαι τὴν ὕβριν, ἀπολήψομαι δέ σε καὶ μὴ θέλουσαν. τοῦτο διηγησαμένη τὸ ὄναρ μόλις δύο ἡμέρας ἐβίω."}],"8":[{"number":117,"text":"Τῆς δὲ Ἀρχελάου χώρας εἰς ἐπαρχίαν περιγραφείσης ἐπίτροπος τῆς ἱππικῆς παρὰ Ῥωμαίοις τάξεως Κωπώνιος πέμπεται μέχρι τοῦ κτείνειν λαβὼν παρὰ Καίσαρος ἐξουσίαν."},{"number":118,"text":"ἐπὶ τούτου τις ἀνὴρ Γαλιλαῖος Ἰούδας ὄνομα εἰς ἀπόστασιν ἐνῆγε τοὺς ἐπιχωρίους κακίζων, εἰ φόρον τε Ῥωμαίοις τελεῖν ὑπομενοῦσιν καὶ μετὰ τὸν θεὸν οἴσουσι θνητοὺς δεσπότας. ἦν δʼ οὗτος σοφιστὴς ἰδίας αἱρέσεως οὐδὲν τοῖς ἄλλοις προσεοικώς."},{"number":119,"text":"Τρία γὰρ παρὰ Ἰουδαίοις εἴδη φιλοσοφεῖται, καὶ τοῦ μὲν αἱρετισταὶ Φαρισαῖοι, τοῦ δὲ Σαδδουκαῖοι, τρίτον δέ, ὃ δὴ καὶ δοκεῖ σεμνότητα ἀσκεῖν, Ἐσσηνοὶ καλοῦνται, Ἰουδαῖοι μὲν γένος ὄντες, φιλάλληλοι δὲ καὶ τῶν ἄλλων πλέον."},{"number":120,"text":"οὗτοι τὰς μὲν ἡδονὰς ὡς κακίαν ἀποστρέφονται, τὴν δὲ ἐγκράτειαν καὶ τὸ μὴ τοῖς πάθεσιν ὑποπίπτειν ἀρετὴν ὑπολαμβάνουσιν. καὶ γάμου μὲν παρʼ αὐτοῖς ὑπεροψία, τοὺς δʼ ἀλλοτρίους παῖδας ἐκλαμβάνοντες ἁπαλοὺς ἔτι πρὸς τὰ μαθήματα συγγενεῖς ἡγοῦνται καὶ τοῖς ἤθεσιν αὐτῶν ἐντυποῦσι,"},{"number":121,"text":"τὸν μὲν γάμον καὶ τὴν ἐξ αὐτοῦ διαδοχὴν οὐκ ἀναιροῦντες, τὰς δὲ τῶν γυναικῶν ἀσελγείας φυλαττόμενοι καὶ μηδεμίαν τηρεῖν πεπεισμένοι τὴν πρὸς ἕνα πίστιν."},{"number":122,"text":"Καταφρονηταὶ δὲ πλούτου, καὶ θαυμάσιον αὐτοῖς τὸ κοινωνικόν, οὐδὲ ἔστιν εὑρεῖν κτήσει τινὰ παρʼ αὐτοῖς ὑπερέχοντα· νόμος γὰρ τοὺς εἰς τὴν αἵρεσιν εἰσιόντας δημεύειν τῷ τάγματι τὴν οὐσίαν, ὥστε ἐν ἅπασιν μήτε πενίας ταπεινότητα φαίνεσθαι μήθʼ ὑπεροχὴν πλούτου, τῶν δʼ ἑκάστου κτημάτων ἀναμεμιγμένων μίαν ὥσπερ ἀδελφοῖς ἅπασιν οὐσίαν εἶναι."},{"number":123,"text":"κηλῖδα δʼ ὑπολαμβάνουσι τὸ ἔλαιον, κἂν ἀλειφθῇ τις ἄκων, σμήχεται τὸ σῶμα· τὸ γὰρ αὐχμεῖν ἐν καλῷ τίθενται λευχειμονεῖν τε διαπαντός. χειροτονητοὶ δʼ οἱ τῶν κοινῶν ἐπιμεληταὶ καὶ ἀδιαίρετοι πρὸς ἁπάντων εἰς τὰς χρείας ἕκαστοι."},{"number":124,"text":"Μία δʼ οὐκ ἔστιν αὐτῶν πόλις ἀλλʼ ἐν ἑκάστῃ μετοικοῦσιν πολλοί. καὶ τοῖς ἑτέρωθεν ἥκουσιν αἱρετισταῖς πάντʼ ἀναπέπταται τὰ παρʼ αὐτοῖς ὁμοίως ὥσπερ ἴδια, καὶ πρὸς οὓς οὐ πρότερον εἶδον εἰσίασιν ὡς συνηθεστάτους·"},{"number":125,"text":"διὸ καὶ ποιοῦνται τὰς ἀποδημίας οὐδὲν μὲν ὅλως ἐπικομιζόμενοι, διὰ δὲ τοὺς λῃστὰς ἔνοπλοι. κηδεμὼν δʼ ἐν ἑκάστῃ πόλει τοῦ τάγματος ἐξαιρέτως τῶν ξένων ἀποδείκνυται ταμιεύων ἐσθῆτα καὶ τὰ ἐπιτήδεια."},{"number":126,"text":"καταστολὴ δὲ καὶ σχῆμα σώματος ὅμοιον τοῖς μετὰ φόβου παιδαγωγουμένοις παισίν. οὔτε δὲ ἐσθῆτας οὔτε ὑποδήματα ἀμείβουσι πρὶν διαρραγῆναι τὸ πρότερον παντάπασιν ἢ δαπανηθῆναι τῷ χρόνῳ."},{"number":127,"text":"οὐδὲν δʼ ἐν ἀλλήλοις οὔτʼ ἀγοράζουσιν οὔτε πωλοῦσιν, ἀλλὰ τῷ χρῄζοντι διδοὺς ἕκαστος τὰ παρʼ αὐτῷ τὸ παρʼ ἐκείνου χρήσιμον ἀντικομίζεται· καὶ χωρὶς δὲ τῆς ἀντιδόσεως ἀκώλυτος ἡ μετάληψις αὐτοῖς παρʼ ὧν ἂν θέλωσιν."},{"number":128,"text":"Πρός γε μὴν τὸ θεῖον εὐσεβεῖς ἰδίως· πρὶν γὰρ ἀνασχεῖν τὸν ἥλιον οὐδὲν φθέγγονται τῶν βεβήλων, πατρίους δέ τινας εἰς αὐτὸν εὐχὰς ὥσπερ ἱκετεύοντες ἀνατεῖλαι."},{"number":129,"text":"καὶ μετὰ ταῦτα πρὸς ἃς ἕκαστοι τέχνας ἴσασιν ὑπὸ τῶν ἐπιμελητῶν διαφίενται, καὶ μέχρι πέμπτης ὥρας ἐργασάμενοι συντόνως πάλιν εἰς ἓν συναθροίζονται χωρίον, ζωσάμενοί τε σκεπάσμασιν λινοῖς οὕτως ἀπολούονται τὸ σῶμα ψυχροῖς ὕδασιν, καὶ μετὰ ταύτην τὴν ἁγνείαν εἰς ἴδιον οἴκημα συνίασιν, ἔνθα μηδενὶ τῶν ἑτεροδόξων ἐπιτέτραπται παρελθεῖν· αὐτοί τε καθαροὶ καθάπερ εἰς ἅγιόν τι τέμενος παραγίνονται τὸ δειπνητήριον."},{"number":130,"text":"καὶ καθισάντων μεθʼ ἡσυχίας ὁ μὲν σιτοποιὸς ἐν τάξει παρατίθησι τοὺς ἄρτους, ὁ δὲ μάγειρος ἓν ἀγγεῖον ἐξ ἑνὸς ἐδέσματος ἑκάστῳ παρατίθησιν."},{"number":131,"text":"προκατεύχεται δʼ ὁ ἱερεὺς τῆς τροφῆς, καὶ γεύσασθαί τινα πρὶν τῆς εὐχῆς ἀθέμιτον· ἀριστοποιησάμενος δʼ ἐπεύχεται πάλιν· ἀρχόμενοί τε καὶ παυόμενοι γεραίρουσι θεὸν ὡς χορηγὸν τῆς ζωῆς. ἔπειθʼ ὡς ἱερὰς καταθέμενοι τὰς ἐσθῆτας πάλιν ἐπʼ ἔργα μέχρι δείλης τρέπονται."},{"number":132,"text":"δειπνοῦσι δʼ ὁμοίως ὑποστρέψαντες συγκαθεζομένων τῶν ξένων, εἰ τύχοιεν αὐτοῖς παρόντες. οὔτε δὲ κραυγή ποτε τὸν οἶκον οὔτε θόρυβος μιαίνει, τὰς δὲ λαλιὰς ἐν τάξει παραχωροῦσιν ἀλλήλοις."},{"number":133,"text":"καὶ τοῖς ἔξωθεν ὡς μυστήριόν τι φρικτὸν ἡ τῶν ἔνδον σιωπὴ καταφαίνεται, τούτου δʼ αἴτιον ἡ διηνεκὴς νῆψις καὶ τὸ μετρεῖσθαι παρʼ αὐτοῖς τροφὴν καὶ ποτὸν μέχρι κόρου."},{"number":134,"text":"Τῶν μὲν οὖν ἄλλων οὐκ ἔστιν ὅ τι μὴ τῶν ἐπιμελητῶν προσταξάντων ἐνεργοῦσι, δύο δὲ ταῦτα παρʼ αὐτοῖς αὐτεξούσια, ἐπικουρία καὶ ἔλεος· βοηθεῖν τε γὰρ τοῖς ἀξίοις, ὁπόταν δέωνται, καὶ καθʼ ἑαυτοὺς ἐφίεται καὶ τροφὰς ἀπορουμένοις ὀρέγειν. τὰς δὲ εἰς τοὺς συγγενεῖς μεταδόσεις οὐκ ἔξεστι ποιεῖσθαι δίχα τῶν ἐπιτρόπων."},{"number":135,"text":"ὀργῆς ταμίαι δίκαιοι, θυμοῦ καθεκτικοί, πίστεως προστάται, εἰρήνης ὑπουργοί. καὶ πᾶν μὲν τὸ ῥηθὲν ὑπʼ αὐτῶν ἰσχυρότερον ὅρκου, τὸ δὲ ὀμνύειν αὐτοῖς περιίσταται χεῖρον τῆς ἐπιορκίας ὑπολαμβάνοντες· ἤδη γὰρ κατεγνῶσθαί φασιν τὸν ἀπιστούμενον δίχα θεοῦ."},{"number":136,"text":"σπουδάζουσι δʼ ἐκτόπως περὶ τὰ τῶν παλαιῶν συντάγματα μάλιστα τὰ πρὸς ὠφέλειαν ψυχῆς καὶ σώματος ἐκλέγοντες· ἔνθεν αὐτοῖς πρὸς θεραπείαν παθῶν ῥίζαι τε ἀλεξητήριον καὶ λίθων ἰδιότητες ἀνερευνῶνται."},{"number":137,"text":"Τοῖς δὲ ζηλοῦσιν τὴν αἵρεσιν αὐτῶν οὐκ εὐθὺς ἡ πάροδος, ἀλλʼ ἐπὶ ἐνιαυτὸν ἔξω μένοντι τὴν αὐτὴν ὑποτίθενται δίαιταν ἀξινάριόν τε καὶ τὸ προειρημένον περίζωμα καὶ λευκὴν ἐσθῆτα δόντες."},{"number":138,"text":"ἐπειδὰν δὲ τούτῳ τῷ χρόνῳ πεῖραν ἐγκρατείας δῷ, πρόσεισιν μὲν ἔγγιον τῇ διαίτῃ καὶ καθαρωτέρων τῶν πρὸς ἁγνείαν ὑδάτων μεταλαμβάνει, παραλαμβάνεται δὲ εἰς τὰς συμβιώσεις οὐδέπω. μετὰ γὰρ τὴν τῆς καρτερίας ἐπίδειξιν δυσὶν ἄλλοις ἔτεσιν τὸ ἦθος δοκιμάζεται καὶ φανεὶς ἄξιος οὕτως εἰς τὸν ὅμιλον ἐγκρίνεται."},{"number":139,"text":"πρὶν δὲ τῆς κοινῆς ἅψασθαι τροφῆς ὅρκους αὐτοῖς ὄμνυσι φρικώδεις, πρῶτον μὲν εὐσεβήσειν τὸ θεῖον, ἔπειτα τὰ πρὸς ἀνθρώπους δίκαια φυλάξειν καὶ μήτε κατὰ γνώμην βλάψειν τινὰ μήτε ἐξ ἐπιτάγματος, μισήσειν δʼ ἀεὶ τοὺς ἀδίκους καὶ συναγωνιεῖσθαι τοῖς δικαίοις·"},{"number":140,"text":"τὸ πιστὸν ἀεὶ πᾶσιν παρέξειν, μάλιστα δὲ τοῖς κρατοῦσιν· οὐ γὰρ δίχα θεοῦ περιγενέσθαι τινὶ τὸ ἄρχειν· κἂν αὐτὸς ἄρχῃ, μηδέποτε ἐξυβρίσειν εἰς τὴν ἐξουσίαν μηδʼ ἐσθῆτί τινι ἢ πλείονι κόσμῳ τοὺς ὑποτεταγμένους ὑπερλαμπρύνεσθαι."},{"number":141,"text":"τὴν ἀλήθειαν ἀγαπᾶν ἀεὶ καὶ τοὺς ψευδομένους προβάλλεσθαι· χεῖρας κλοπῆς καὶ ψυχὴν ἀνοσίου κέρδους καθαρὰν φυλάξειν καὶ μήτε κρύψειν τι τοὺς αἱρετιστὰς μήθʼ ἑτέροις αὐτῶν τι μηνύσειν, κἂν μέχρι θανάτου τις βιάζηται."},{"number":142,"text":"πρὸς τούτοις ὄμνυσιν μηδενὶ μὲν μεταδοῦναι τῶν δογμάτων ἑτέρως ἢ ὡς αὐτὸς μετέλαβεν, ἀφέξεσθαι δὲ λῃστείας καὶ συντηρήσειν ὁμοίως τά τε τῆς αἱρέσεως αὐτῶν βιβλία καὶ τὰ τῶν ἀγγέλων ὀνόματα. τοιούτοις μὲν ὅρκοις τοὺς προσιόντας ἐξασφαλίζονται."},{"number":143,"text":"Τοὺς δʼ ἐπʼ ἀξιοχρέοις ἁμαρτήμασιν ἁλόντας ἐκβάλλουσι τοῦ τάγματος. ὁ δʼ ἐκκριθεὶς οἰκτίστῳ πολλάκις μόρῳ διαφθείρεται· τοῖς γὰρ ὅρκοις καὶ τοῖς ἔθεσιν ἐνδεδεμένος οὐδὲ τῆς παρὰ τοῖς ἄλλοις τροφῆς δύναται μεταλαμβάνειν, ποηφαγῶν δὲ καὶ λιμῷ τὸ σῶμα τηκόμενος διαφθείρεται."},{"number":144,"text":"διὸ δὴ πολλοὺς ἐλεήσαντες ἐν ταῖς ἐσχάταις ἀναπνοαῖς ἀνέλαβον, ἱκανὴν ἐπὶ τοῖς ἁμαρτήμασιν αὐτῶν τὴν μέχρι θανάτου βάσανον ἡγούμενοι."},{"number":145,"text":"Περὶ δὲ τὰς κρίσεις ἀκριβέστατοι καὶ δίκαιοι, καὶ δικάζουσι μὲν οὐκ ἐλάττους τῶν ἑκατὸν συνελθόντες, τὸ δʼ ὁρισθὲν ὑπʼ αὐτῶν ἀκίνητον. σέβας δὲ μέγα παρʼ αὐτοῖς μετὰ τὸν θεὸν τοὔνομα τοῦ νομοθέτου, κἂν βλασφημήσῃ τις εἰς τοῦτον κολάζεται θανάτῳ."},{"number":146,"text":"τοῖς δὲ πρεσβυτέροις ὑπακούουσιν καὶ τοῖς πλείοσιν ἐν καλῷ· δέκα γοῦν συγκαθεζομένων οὐκ ἂν λαλήσειέν τις ἀκόντων τῶν ἐννέα."},{"number":147,"text":"καὶ τὸ πτύσαι δὲ εἰς μέσους ἢ τὸ δεξιὸν μέρος φυλάσσονται καὶ ταῖς ἑβδομάσιν ἔργων ἐφάπτεσθαι διαφορώτατα Ἰουδαίων ἁπάντων· οὐ μόνον γὰρ τροφὰς ἑαυτοῖς πρὸ μιᾶς ἡμέρας παρασκευάζουσιν, ὡς μὴ πῦρ ἐναύοιεν ἐκείνην τὴν ἡμέραν, ἀλλʼ οὐδὲ σκεῦός τι μετακινῆσαι θαρροῦσιν οὐδὲ ἀποπατεῖν."},{"number":148,"text":"ταῖς δʼ ἄλλαις ἡμέραις βόθρον ὀρύσσοντες βάθος ποδιαῖον τῇ σκαλίδι, τοιοῦτον γάρ ἐστιν τὸ διδόμενον ὑπʼ αὐτῶν ἀξινίδιον τοῖς νεοσυστάτοις, καὶ περικαλύψαντες θοιμάτιον, ὡς μὴ τὰς αὐγὰς ὑβρίζοιεν τοῦ θεοῦ, θακεύουσιν εἰς αὐτόν."},{"number":149,"text":"ἔπειτα τὴν ἀνορυχθεῖσαν γῆν ἐφέλκουσιν εἰς τὸν βόθρον· καὶ τοῦτο ποιοῦσι τοὺς ἐρημοτέρους τόπους ἐκλεγόμενοι. καίπερ δὴ φυσικῆς οὔσης τῆς τῶν λυμάτων ἐκκρίσεως ἀπολούεσθαι μετʼ αὐτὴν καθάπερ μεμιασμένοις ἔθιμον."},{"number":150,"text":"Διῄρηνται δὲ κατὰ χρόνον τῆς ἀσκήσεως εἰς μοίρας τέσσαρας, καὶ τοσοῦτον οἱ μεταγενέστεροι τῶν προγενεστέρων ἐλαττοῦνται, ὥστʼ εἰ ψαύσειαν αὐτῶν, ἐκείνους ἀπολούεσθαι καθάπερ ἀλλοφύλῳ συμφυρέντας."},{"number":151,"text":"καὶ μακρόβιοι μέν, ὡς τοὺς πολλοὺς ὑπὲρ ἑκατὸν παρατείνειν ἔτη, διὰ τὴν ἁπλότητα τῆς διαίτης ἔμοιγε δοκεῖν καὶ τὴν εὐταξίαν, καταφρονηταὶ δὲ τῶν δεινῶν, καὶ τὰς μὲν ἀλγηδόνας νικῶντες τοῖς φρονήμασιν, τὸν δὲ θάνατον, εἰ μετʼ εὐκλείας πρόσεισι, νομίζοντες ἀθανασίας ἀμείνονα."},{"number":152,"text":"διήλεγξεν δὲ αὐτῶν ἐν ἅπασιν τὰς ψυχὰς ὁ πρὸς Ῥωμαίους πόλεμος, ἐν ᾧ στρεβλούμενοί τε καὶ λυγιζόμενοι καιόμενοί τε καὶ κλώμενοι καὶ διὰ πάντων ὁδεύοντες τῶν βασανιστηρίων ὀργάνων, ἵνʼ ἢ βλασφημήσωσιν τὸν νομοθέτην ἢ φάγωσίν τι τῶν ἀσυνήθων, οὐδέτερον ὑπέμειναν παθεῖν, ἀλλʼ οὐδὲ κολακεῦσαί ποτε τοὺς αἰκιζομένους ἢ δακρῦσαι."},{"number":153,"text":"μειδιῶντες δὲ ἐν ταῖς ἀλγηδόσιν καὶ κατειρωνευόμενοι τῶν τὰς βασάνους προσφερόντων εὔθυμοι τὰς ψυχὰς ἠφίεσαν ὡς πάλιν κομιούμενοι."},{"number":154,"text":"Καὶ γὰρ ἔρρωται παρʼ αὐτοῖς ἥδε ἡ δόξα, φθαρτὰ μὲν εἶναι τὰ σώματα καὶ τὴν ὕλην οὐ μόνιμον αὐτῶν, τὰς δὲ ψυχὰς ἀθανάτους ἀεὶ διαμένειν, καὶ συμπλέκεσθαι μὲν ἐκ τοῦ λεπτοτάτου φοιτώσας αἰθέρος ὥσπερ εἱρκταῖς τοῖς σώμασιν ἴυγγί τινι φυσικῇ κατασπωμένας,"},{"number":155,"text":"ἐπειδὰν δὲ ἀνεθῶσι τῶν κατὰ σάρκα δεσμῶν, οἷα δὴ μακρᾶς δουλείας ἀπηλλαγμένας τότε χαίρειν καὶ μετεώρους φέρεσθαι. καὶ ταῖς μὲν ἀγαθαῖς ὁμοδοξοῦντες παισὶν Ἑλλήνων ἀποφαίνονται τὴν ὑπὲρ ὠκεανὸν δίαιταν ἀποκεῖσθαι καὶ χῶρον οὔτε ὄμβροις οὔτε νιφετοῖς οὔτε καύμασι βαρυνόμενον, ἀλλʼ ὃν ἐξ ὠκεανοῦ πραῢς ἀεὶ ζέφυρος ἐπιπνέων ἀναψύχει· ταῖς δὲ φαύλαις ζοφώδη καὶ χειμέριον ἀφορίζονται μυχὸν γέμοντα τιμωριῶν ἀδιαλείπτων."},{"number":156,"text":"δοκοῦσι δέ μοι κατὰ τὴν αὐτὴν ἔννοιαν Ἕλληνες τοῖς τε ἀνδρείοις αὐτῶν, οὓς ἥρωας καὶ ἡμιθέους καλοῦσιν, τὰς μακάρων νήσους ἀνατεθεικέναι, ταῖς δὲ τῶν πονηρῶν ψυχαῖς καθʼ ᾅδου τὸν ἀσεβῶν χῶρον, ἔνθα καὶ κολαζομένους τινὰς μυθολογοῦσιν, Σισύφους καὶ Ταντάλους Ἰξίονάς τε καὶ Τιτυούς, πρῶτον μὲν ἀιδίους ὑφιστάμενοι τὰς ψυχάς, ἔπειτα εἰς προτροπὴν ἀρετῆς καὶ κακίας ἀποτροπήν."},{"number":157,"text":"τούς τε γὰρ ἀγαθοὺς γίνεσθαι κατὰ τὸν βίον ἀμείνους ἐλπίδι τιμῆς καὶ μετὰ τὴν τελευτήν, τῶν τε κακῶν ἐμποδίζεσθαι τὰς ὁρμὰς δέει προσδοκώντων, εἰ καὶ λάθοιεν ἐν τῷ ζῆν, μετὰ τὴν διάλυσιν ἀθάνατον τιμωρίαν ὑφέξειν."},{"number":158,"text":"ταῦτα μὲν οὖν Ἐσσηνοὶ περὶ ψυχῆς θεολογοῦσιν ἄφυκτον δέλεαρ τοῖς ἅπαξ γευσαμένοις τῆς σοφίας αὐτῶν καθιέντες."},{"number":159,"text":"Εἰσὶν δʼ ἐν αὐτοῖς οἳ καὶ τὰ μέλλοντα προγινώσκειν ὑπισχνοῦνται, βίβλοις ἱεραῖς καὶ διαφόροις ἁγνείαις καὶ προφητῶν ἀποφθέγμασιν ἐμπαιδοτριβούμενοι· σπάνιον δʼ εἴ ποτε ἐν ταῖς προαγορεύσεσιν ἀστοχοῦσιν."},{"number":160,"text":"Ἔστιν δὲ καὶ ἕτερον Ἐσσηνῶν τάγμα, δίαιταν μὲν καὶ ἔθη καὶ νόμιμα τοῖς ἄλλοις ὁμοφρονοῦν, διεστὼς δὲ τῇ κατὰ γάμον δόξῃ· μέγιστον γὰρ ἀποκόπτειν οἴονται τοῦ βίου μέρος, τὴν διαδοχήν, τοὺς μὴ γαμοῦντας, μᾶλλον δέ, εἰ πάντες τὸ αὐτὸ φρονήσειαν, ἐκλιπεῖν ἂν τὸ γένος τάχιστα."},{"number":161,"text":"δοκιμάζοντες μέντοι τριετίᾳ τὰς γαμετάς, ἐπειδὰν τρὶς καθαρθῶσιν εἰς πεῖραν τοῦ δύνασθαι τίκτειν, οὕτως ἄγονται. ταῖς δʼ ἐγκύμοσιν οὐχ ὁμιλοῦσιν, ἐνδεικνύμενοι τὸ μὴ διʼ ἡδονὴν ἀλλὰ τέκνων χρείαν γαμεῖν. λουτρὰ δὲ ταῖς γυναιξὶν ἀμπεχομέναις ἐνδύματα, καθάπερ τοῖς ἀνδράσιν ἐν περιζώματι. τοιαῦτα μὲν ἔθη τοῦδε τοῦ τάγματος."},{"number":162,"text":"Δύο δὲ τῶν προτέρων Φαρισαῖοι μὲν οἱ μετὰ ἀκριβείας δοκοῦντες ἐξηγεῖσθαι τὰ νόμιμα καὶ τὴν πρώτην ἀπάγοντες αἵρεσιν εἱμαρμένῃ τε καὶ θεῷ προσάπτουσι πάντα,"},{"number":163,"text":"καὶ τὸ μὲν πράττειν τὰ δίκαια καὶ μὴ κατὰ τὸ πλεῖστον ἐπὶ τοῖς ἀνθρώποις κεῖσθαι, βοηθεῖν δὲ εἰς ἕκαστον καὶ τὴν εἱμαρμένην· ψυχήν τε πᾶσαν μὲν ἄφθαρτον, μεταβαίνειν δὲ εἰς ἕτερον σῶμα τὴν τῶν ἀγαθῶν μόνην, τὰς δὲ τῶν φαύλων ἀιδίῳ τιμωρίᾳ κολάζεσθαι."},{"number":164,"text":"Σαδδουκαῖοι δέ, τὸ δεύτερον τάγμα, τὴν μὲν εἱμαρμένην παντάπασιν ἀναιροῦσιν καὶ τὸν θεὸν ἔξω τοῦ δρᾶν τι κακὸν ἢ ἐφορᾶν τίθενται·"},{"number":165,"text":"φασὶν δʼ ἐπʼ ἀνθρώπων ἐκλογῇ τό τε καλὸν καὶ τὸ κακὸν προκεῖσθαι καὶ κατὰ γνώμην ἑκάστου τούτων ἑκατέρῳ προσιέναι. ψυχῆς τε τὴν διαμονὴν καὶ τὰς καθʼ ᾅδου τιμωρίας καὶ τιμὰς ἀναιροῦσιν."},{"number":166,"text":"καὶ Φαρισαῖοι μὲν φιλάλληλοί τε καὶ τὴν εἰς τὸ κοινὸν ὁμόνοιαν ἀσκοῦντες, Σαδδουκαίων δὲ καὶ πρὸς ἀλλήλους τὸ ἦθος ἀγριώτερον αἵ τε ἐπιμιξίαι πρὸς τοὺς ὁμοίους ἀπηνεῖς ὡς πρὸς ἀλλοτρίους. τοιαῦτα μὲν περὶ τῶν ἐν Ἰουδαίοις φιλοσοφούντων εἶχον εἰπεῖν."}],"9":[{"number":167,"text":"Τῆς Ἀρχελάου δʼ ἐθναρχίας μεταπεσούσης εἰς ἐπαρχίαν οἱ λοιποί, Φίλιππος καὶ Ἡρώδης ὁ κληθεὶς Ἀντίπας, διῴκουν τὰς ἑαυτῶν τετραρχίας· Σαλώμη γὰρ τελευτῶσα Ἰουλίᾳ τῇ τοῦ Σεβαστοῦ γυναικὶ τήν τε αὐτῆς τοπαρχίαν καὶ Ἰάμνειαν καὶ τοὺς ἐν Φασαηλίδι φοινικῶνας κατέλιπεν."},{"number":168,"text":"μεταβάσης δὲ εἰς Τιβέριον τὸν Ἰουλίας υἱὸν τῆς Ῥωμαίων ἡγεμονίας μετὰ τὴν Αὐγούστου τελευτήν, ἀφηγησαμένου τῶν πραγμάτων ἔτεσιν ἑπτὰ καὶ πεντήκοντα πρὸς δὲ μησὶν ἓξ καὶ ἡμέραις δύο, διαμείναντες ἐν ταῖς τετραρχίαις ὅ τε Ἡρώδης καὶ ὁ Φίλιππος, ὁ μὲν πρὸς ταῖς τοῦ Ἰορδάνου πηγαῖς ἐν Πανεάδι πόλιν κτίζει Καισάρειαν κἀν τῇ κάτω Γαυλανιτικῇ Ἰουλιάδα, Ἡρώδης δʼ ἐν μὲν τῇ Γαλιλαίᾳ Τιβεριάδα, ἐν δὲ τῇ Περαίᾳ φερώνυμον Ἰουλίας."},{"number":169,"text":"Πεμφθεὶς δὲ εἰς Ἰουδαίαν ἐπίτροπος ὑπὸ Τιβερίου Πιλᾶτος νύκτωρ κεκαλυμμένας εἰς Ἱεροσόλυμα εἰσκομίζει τὰς Καίσαρος εἰκόνας, αἳ σημαῖαι καλοῦνται."},{"number":170,"text":"τοῦτο μεθʼ ἡμέραν μεγίστην ταραχὴν ἤγειρεν Ἰουδαίοις· οἵ τε γὰρ ἐγγὺς πρὸς τὴν ὄψιν ἐξεπλάγησαν ὡς πεπατημένων αὐτοῖς τῶν νόμων, οὐδὲν γὰρ ἀξιοῦσιν ἐν τῇ πόλει δείκηλον τίθεσθαι, καὶ πρὸς τὴν ἀγανάκτησιν τῶν κατὰ τὴν πόλιν ἄθρους ὁ ἐκ τῆς χώρας λαὸς συνέρρευσεν."},{"number":171,"text":"ὁρμήσαντες δὲ πρὸς Πιλᾶτον εἰς Καισάρειαν ἱκέτευον ἐξενεγκεῖν ἐξ Ἱεροσολύμων τὰς σημαίας καὶ τηρεῖν αὐτοῖς τὰ πάτρια. Πιλάτου δὲ ἀρνουμένου περὶ τὴν οἰκίαν πρηνεῖς καταπεσόντες ἐπὶ πέντε ἡμέρας καὶ νύκτας ἴσας ἀκίνητοι διεκαρτέρουν."},{"number":172,"text":"Τῇ δʼ ἑξῆς ὁ Πιλᾶτος καθίσας ἐπὶ βήματος ἐν τῷ μεγάλῳ σταδίῳ καὶ προσκαλεσάμενος τὸ πλῆθος ὡς ἀποκρίνασθαι δῆθεν αὐτοῖς θέλων, δίδωσιν τοῖς στρατιώταις σημεῖον ἐκ συντάγματος κυκλώσασθαι τοὺς Ἰουδαίους ἐν τοῖς ὅπλοις."},{"number":173,"text":"περιστάσης δὲ τριστιχεὶ τῆς φάλαγγος Ἰουδαῖοι μὲν ἀχανεῖς ἦσαν πρὸς τὸ ἀδόκητον τῆς ὄψεως, Πιλᾶτος δὲ κατακόψειν εἰπὼν αὐτούς, εἰ μὴ προσδέξαιντο τὰς Καίσαρος εἰκόνας, γυμνοῦν τὰ ξίφη τοῖς στρατιώταις ἔνευσεν."},{"number":174,"text":"οἱ δὲ Ἰουδαῖοι καθάπερ ἐκ συνθήματος ἀθρόοι καταπεσόντες καὶ τοὺς αὐχένας παρακλίναντες ἑτοίμους ἀναιρεῖν σφᾶς ἐβόων μᾶλλον ἢ τὸν νόμον παραβῆναι. ὑπερθαυμάσας δὲ ὁ Πιλᾶτος τὸ τῆς δεισιδαιμονίας ἄκρατον ἐκκομίσαι μὲν αὐτίκα τὰς σημαίας Ἱεροσολύμων κελεύει."},{"number":175,"text":"Μετὰ δὲ ταῦτα ταραχὴν ἑτέραν ἐκίνει τὸν ἱερὸν θησαυρόν, καλεῖται δὲ κορβωνᾶς, εἰς καταγωγὴν ὑδάτων ἐξαναλίσκων· κατῆγεν δὲ ἀπὸ τετρακοσίων σταδίων. πρὸς τοῦτο τοῦ πλήθους ἀγανάκτησις ἦν, καὶ τοῦ Πιλάτου παρόντος εἰς Ἱεροσόλυμα περιστάντες τὸ βῆμα κατεβόων."},{"number":176,"text":"ὁ δέ, προῄδει γὰρ αὐτῶν τὴν ταραχήν, τῷ πλήθει τοὺς στρατιώτας ἐνόπλους ἐσθῆσιν ἰδιωτικαῖς κεκαλυμμένους ἐγκαταμίξας καὶ ξίφει μὲν χρήσασθαι κωλύσας, ξύλοις δὲ παίειν τοὺς κεκραγότας ἐγκελευσάμενος σύνθημα δίδωσιν ἀπὸ τοῦ βήματος."},{"number":177,"text":"τυπτόμενοι δὲ οἱ Ἰουδαῖοι πολλοὶ μὲν ὑπὸ τῶν πληγῶν, πολλοὶ δὲ ὑπὸ σφῶν αὐτῶν ἐν τῇ φυγῇ καταπατηθέντες ἀπώλοντο. πρὸς δὲ τὴν συμφορὰν τῶν ἀνῃρημένων καταπλαγὲν τὸ πλῆθος ἐσιώπησεν."},{"number":178,"text":"Κἀν τούτῳ κατήγορος Ἡρώδου τοῦ τετραρχοῦντος Ἀγρίππας υἱὸς Ἀριστοβούλου, ὃν ὁ πατὴρ Ἡρώδης ἀπέκτεινεν, παραγίνεται πρὸς Τιβέριον. τοῦ δὲ μὴ προσδεξαμένου τὴν κατηγορίαν μένων ἐπὶ Ῥώμης τούς τε ἄλλους τῶν γνωρίμων ἐθεράπευεν καὶ μάλιστα τὸν Γερμανικοῦ παῖδα Γάιον ἰδιώτην ἔτι ὄντα."},{"number":179,"text":"καὶ δή ποτε ἑστιῶν αὐτὸν τά τε ἄλλα ποικίλως ἐφιλοφρονεῖτο καὶ τελευταῖον τὰς χεῖρας ἀνατείνας φανερῶς ηὔξατο θᾶττον αὐτὸν θεάσασθαι τῶν ὅλων δεσπότην ἀποθανόντος Τιβερίου."},{"number":180,"text":"τοῦτό τις τῶν οἰκετῶν αὐτοῦ διαγγέλλει τῷ Τιβερίῳ, καὶ ὃς ἀγανακτήσας εἵργνυσιν τὸν Ἀγρίππαν καὶ μετʼ αἰκίας εἶχεν αὐτὸν ἐπὶ μῆνας ἓξ ἐν δεσμωτηρίῳ, μέχρις αὐτὸς ἐτελεύτησεν ἡγεμονεύσας ἔτη δύο πρὸς τοῖς εἴκοσι καὶ τρεῖς ἡμέρας ἐπὶ μησὶν ἕξ."},{"number":181,"text":"Ἀποδειχθεὶς δὲ Γάιος Καῖσαρ ἀνίησίν τε τῶν δεσμῶν τὸν Ἀγρίππαν καὶ τῆς Φιλίππου τετραρχίας, θνήσκει γὰρ οὗτος, καθίστησι βασιλέα. παραγενόμενος δὲ εἰς τὴν ἀρχὴν Ἀγρίππας φθόνῳ τὰς Ἡρώδου τοῦ τετράρχου διήγειρεν ἐπιθυμίας."},{"number":182,"text":"ἐνῆγε δὲ μάλιστα τοῦτον εἰς ἐλπίδα βασιλείας Ἡρωδιὰς ἡ γυνὴ κατονειδίζουσα τὴν ἀργίαν καὶ φαμένη παρὰ τὸ μὴ βούλεσθαι πλεῖν ἐπὶ Καίσαρα στερίσκεσθαι μείζονος ἀρχῆς· ὅπου μὲν γὰρ Ἀγρίππαν ἐξ ἰδιώτου βασιλέα πεποίηκεν, ἦπου γʼ ἂν ἐκεῖνον διστάσειεν ἐκ τετράρχου; τούτοις ἀναπεισθεὶς Ἡρώδης ἧκεν πρὸς Γάιον,"},{"number":183,"text":"ὑφʼ οὗ τῆς πλεονεξίας ἐπιτιμᾶται φυγῇ εἰς Γαλλίαν· ἠκολούθησεν γὰρ αὐτῷ κατήγορος Ἀγρίππας, ᾧ καὶ τὴν τετραρχίαν τὴν ἐκείνου προσέθηκεν Γάιος. καὶ Ἡρώδης μὲν ἐν Γαλλίᾳ συμφυγούσης αὐτῷ καὶ τῆς γυναικὸς τελευτᾷ."}],"10":[{"number":184,"text":"Γάιος δὲ Καῖσαρ ἐπὶ τοσοῦτον ἐξύβρισεν εἰς τὴν τύχην, ὥστε θεὸν ἑαυτὸν καὶ δοκεῖν βούλεσθαι καὶ καλεῖσθαι τῶν τε εὐγενεστάτων ἀνδρῶν ἀκροτομῆσαι τὴν πατρίδα, ἐκτεῖναι δὲ τὴν ἀσέβειαν καὶ ἐπὶ Ἰουδαίαν."},{"number":185,"text":"Πετρώνιον μὲν οὖν μετὰ στρατιᾶς ἐπὶ Ἱεροσολύμων ἔπεμψεν ἐγκαθιδρύσοντα τῷ ναῷ τοὺς ἀνδριάντας αὐτοῦ, προστάξας, εἰ μὴ δέχοιντο Ἰουδαῖοι, τούς τε κωλύοντας ἀνελεῖν καὶ πᾶν τὸ λοιπὸν ἔθνος ἐξανδραποδίσασθαι."},{"number":186,"text":"θεῷ δʼ ἄρα τῶν προσταγμάτων ἔμελεν. καὶ Πετρώνιος μὲν σὺν τρισὶ τάγμασι καὶ πολλοῖς ἐκ τῆς Συρίας συμμάχοις εἰς τὴν Ἰουδαίαν ἤλαυνεν ἐκ τῆς Ἀντιοχείας,"},{"number":187,"text":"Ἰουδαίων δὲ οἱ μὲν ἠπίστουν ἐπὶ ταῖς τοῦ πολέμου φήμαις, οἱ δὲ πιστεύοντες ἦσαν ἐν ἀμηχάνῳ πρὸς τὴν ἄμυναν· ταχὺ δʼ ἐχώρει διὰ πάντων τὸ δέος ἤδη παρούσης εἰς Πτολεμαΐδα τῆς στρατιᾶς."},{"number":188,"text":"Πόλις δʼ ἐστὶν αὕτη τῆς Γαλιλαίας παράλιος κατὰ τὸ μέγα πεδίον ἐκτισμένη, περιέχεται δὲ ὄρεσιν ἐκ μὲν τοῦ πρὸς ἀνατολὴν κλίματος ἀπὸ σταδίων ἑξήκοντα τῷ τῆς Γαλιλαίας, ἀπὸ δὲ τοῦ μεσημβρινοῦ τῷ Καρμήλῳ διέχοντι σταδίους ἑκατὸν εἴκοσι, τῷ δʼ ὑψηλοτάτῳ κατʼ ἄρκτον, ὃ καλοῦσιν κλίμακα Τυρίων οἱ ἐπιχώριοι·"},{"number":189,"text":"καὶ τοῦτο δὲ σταδίους ἀφέστηκεν ἑκατόν. τοῦ δʼ ἄστεος ὅσον ἀπὸ δύο σταδίων ὁ καλούμενος Βήλεος ποταμὸς παραρρεῖ παντάπασιν ὀλίγος, παρʼ ᾧ τὸ Μέμνονος μνημεῖόν ἐστιν ἔχον ἐγγὺς αὐτοῦ τόπον ἑκατονταπήχη θαύματος ἄξιον·"},{"number":190,"text":"κυκλοτερὴς μὲν γάρ ἐστιν καὶ κοῖλος, ἀναδίδωσιν δὲ τὴν ὑελίνην ψάμμον, ἣν ὅταν ἐκκενώσῃ πολλὰ πλοῖα προσσχόντα, πάλιν ἀντιπληροῦται τὸ χωρίον, κατασυρόντων μὲν ὥσπερ ἐπίτηδες τότε τῶν ἀνέμων εἰς αὐτὸ τὴν ἔξωθεν ἀργὴν ψάμμον, τοῦ δὲ μετάλλου πᾶσαν εὐθέως μεταβάλλοντος εἰς ὕελον."},{"number":191,"text":"θαυμασιώτερον δὲ τούτου μοι δοκεῖ τὸ τὴν ὑπερχυθεῖσαν ὕελον ἐκ τοῦ τόπου πάλιν ψάμμον γίνεσθαι εἰκαίαν. τὸ μὲν οὖν χωρίον τοῦτο τοιαύτην εἴληχεν φύσιν."},{"number":192,"text":"Ἰουδαῖοι δὲ μετὰ γυναικῶν καὶ τέκνων ἀθροισθέντες εἰς τὸ πεδίον τὸ πρὸς Πτολεμαΐδι καθικέτευον τὸν Πετρώνιον ὑπὲρ τῶν πατρίων νόμων πρῶτον, ἔπειτα ὑπὲρ αὑτῶν. ὁ δὲ πρός τε τὸ πλῆθος καὶ τὰς δεήσεις ἐνδοὺς τοὺς μὲν ἀνδριάντας καὶ τὰς στρατιὰς ἐν Πτολεμαΐδι λείπει,"},{"number":193,"text":"προελθὼν δὲ εἰς τὴν Γαλιλαίαν καὶ συγκαλέσας τό τε πλῆθος καὶ τοὺς γνωρίμους πάντας εἰς Τιβεριάδα τήν τε Ῥωμαίων διεξῄει δύναμιν καὶ τὰς Καίσαρος ἀπειλάς, ἔτι δὲ τὴν ἀξίωσιν ἀπέφαινεν ἀγνώμονα·"},{"number":194,"text":"πάντων γὰρ τῶν ὑποτεταγμένων ἐθνῶν κατὰ πόλιν συγκαθιδρυκότων τοῖς ἄλλοις θεοῖς καὶ τὰς Καίσαρος εἰκόνας τὸ μόνους ἐκείνους ἀντιτάσσεσθαι πρὸς τοῦτο σχεδὸν ἀφισταμένων εἶναι καὶ μεθʼ ὕβρεως."},{"number":195,"text":"Τῶν δὲ τὸν νόμον καὶ τὸ πάτριον ἔθος προτεινομένων καὶ ὡς οὐδὲ θεοῦ τι δείκηλον, οὐχ ὅπως ἀνδρός, οὐ κατὰ τὸν ναὸν μόνον ἀλλʼ οὐδὲ ἐν εἰκαίῳ τινὶ τόπῳ τῆς χώρας θέσθαι θεμιτὸν εἴη, ὑπολαβὼν ὁ Πετρώνιος ἀλλὰ μὴν καὶ ἐμοὶ φυλακτέος ὁ τοὐμοῦ δεσπότου νόμος, ἔφη· παραβὰς γὰρ αὐτὸν καὶ φεισάμενος ὑμῶν ἀπολοῦμαι δικαίως. πολεμήσει δʼ ὑμᾶς ὁ πέμψας με καὶ οὐκ ἐγώ· καὶ γὰρ αὐτός, ὥσπερ ὑμεῖς, ἐπιτάσσομαι."},{"number":196,"text":"πρὸς ταῦτα τὸ πλῆθος πάντʼ ἐβόα πρὸ τοῦ νόμου πάσχειν ἑτοίμως ἔχειν. καταστείλας δʼ αὐτῶν ὁ Πετρώνιος τὴν βοήν, πολεμήσετε, εἶπεν, ἄρα Καίσαρι;"},{"number":197,"text":"καὶ Ἰουδαῖοι περὶ μὲν Καίσαρος καὶ τοῦ δήμου τῶν Ῥωμαίων δὶς τῆς ἡμέρας θύειν ἔφασαν, εἰ δὲ βούλεται τὰς εἰκόνας ἐγκαθιδρύειν, πρότερον αὐτὸν δεῖν ἅπαν τὸ Ἰουδαίων ἔθνος προθύσασθαι· παρέχειν δὲ σφᾶς αὐτοὺς ἑτοίμους εἰς τὴν σφαγὴν ἅμα τέκνοις καὶ γυναιξίν."},{"number":198,"text":"ἐπὶ τούτοις θαῦμα καὶ οἶκτος εἰσῄει τὸν Πετρώνιον τῆς τε ἀνυπερβλήτου θρησκείας τῶν ἀνδρῶν καὶ τοῦ πρὸς θάνατον ἑτοίμου παραστήματος. καὶ τότε μὲν ἄπρακτοι διελύθησαν."},{"number":199,"text":"Ταῖς δʼ ἑξῆς ἀθρόους τε τοὺς δυνατοὺς κατʼ ἰδίαν καὶ τὸ πλῆθος ἐν κοινῷ συλλέγων ποτὲ μὲν παρεκάλει, ποτὲ δὲ συνεβούλευεν, τὸ πλέον μέντοι διηπείλει τήν τε Ῥωμαίων ἐπανατεινόμενος ἰσχὺν καὶ τοὺς Γαΐου θυμοὺς τήν τε ἰδίαν πρὸς τούτοις ἀνάγκην."},{"number":200,"text":"πρὸς δὲ μηδεμίαν πεῖραν ἐνδιδόντων ὡς ἑώρα καὶ τὴν χώραν κινδυνεύουσαν ἄσπορον μεῖναι, κατὰ γὰρ ὥραν σπόρου πεντήκοντα ἡμέρας ἀργὰ προσδιέτριβεν αὐτῷ τὰ πλήθη, τελευταῖον ἀθροίσας αὐτοὺς καὶ"},{"number":201,"text":"παρακινδυνευτέον ἐμοὶ μᾶλλον, εἰπών, ἢ γὰρ τοῦ θεοῦ συνεργοῦντος πείσας Καίσαρα σωθήσομαι μεθʼ ὑμῶν ἡδέως ἢ παροξυνθέντος ὑπὲρ τοσούτων ἑτοίμως ἐπιδώσω τὴν ἐμαυτοῦ ψυχήν, διαφῆκεν τὸ πλῆθος πολλὰ κατευχομένων αὐτῷ, καὶ παραλαβὼν τὴν στρατιὰν ἐκ τῆς Πτολεμαΐδος ὑπέστρεψεν εἰς τὴν Ἀντιόχειαν."},{"number":202,"text":"ἔνθεν εὐθέως ἐπέστελλεν Καίσαρι τήν τε ἐμβολὴν τὴν εἰς Ἰουδαίαν ἑαυτοῦ καὶ τὰς ἱκεσίας τοῦ ἔθνους, ὅτι τε, εἰ μὴ βούλεται πρὸς τοῖς ἀνδράσιν καὶ τὴν χώραν ἀπολέσαι, δέοι φυλάττειν τε αὐτοὺς τὸν νόμον καὶ παριέναι τὸ πρόσταγμα."},{"number":203,"text":"ταύταις ταῖς ἐπιστολαῖς οὐ σφόδρα μετρίως ἀντέγραψεν ὁ Γάιος, ἀπειλῶν Πετρωνίῳ θάνατον, ὅτι τῶν προσταγμάτων αὐτοῦ βραδὺς ὑπηρέτης ἐγίνετο. ἀλλὰ τοὺς μὲν τούτων γραμματοφόρους συνέβη χειμασθῆναι τρεῖς μῆνας ἐν τῇ θαλάσσῃ, τὸν δὲ Γαΐου θάνατον ἄλλοι καταγγέλλοντες εὐπλόουν. ἔφθη γοῦν τὰς περὶ τούτων Πετρώνιος λαβὼν ἐπιστολὰς ἑπτὰ καὶ εἴκοσιν ἡμέραις ἢ τὰς καθʼ ἑαυτοῦ."}],"11":[{"number":204,"text":"Γαΐου δὲ ἡγεμονεύσαντος ἔτη τρία καὶ μῆνας ὀκτὼ καὶ δολοφονηθέντος ἁρπάζεται μὲν ὑπὸ τῶν ἐν Ῥώμῃ στρατευμάτων [εἰς τὴν ἀρχὴν] Κλαύδιος,"},{"number":205,"text":"ἡ δὲ σύγκλητος ἐξηγουμένων τῶν ὑπάτων Σεντίου Σατορνίνου καὶ Πομπωνίου Σεκούνδου τρισὶν ταῖς συμμενούσαις σπείραις ἐπιτρέψασα φυλάττειν τὴν πόλιν εἰς τὸ Καπετώλιον ἠθροίσθη καὶ διὰ τὴν ὠμότητα τὴν Γαΐου Κλαυδίῳ πολεμεῖν ἐψηφίζετο· καταστήσεσθαι γὰρ διʼ ἀριστοκρατίας, ὥσπερ οὖν πάλαι διῳκεῖτο, τὴν ἀρχὴν ἢ κρινεῖν ψήφῳ τὸν ἄξιον τῆς ἡγεμονίας."},{"number":206,"text":"Συνέβη τηνικαῦτα πρὸς ἐπιδημοῦντα τὸν Ἀγρίππαν τήν τε σύγκλητον καλοῦσαν εἰς συμβουλίαν πέμψαι καὶ Κλαύδιον ἐκ τῆς παρεμβολῆς, ὅπως πρὸς ἃ δέοι χρήσιμος αὐτοῖς γένοιτο. κἀκεῖνος συνιδὼν τὸν ἤδη τῇ δυνάμει Καίσαρα πρὸς Κλαύδιον ἄπεισιν."},{"number":207,"text":"ὁ δʼ αὐτὸν πρεσβευτὴν πρὸς τὴν σύγκλητον ἀναπέμπει δηλοῦντα τὴν ἑαυτοῦ προαίρεσιν, ὅτι πρῶτον μὲν ἄκων ὑπὸ τῶν στρατιωτῶν ἁρπαγείη, καὶ οὔτε τὴν ἐκείνων σπουδὴν ἐγκαταλιπεῖν δίκαιον οὔτε ἀσφαλὲς τὴν ἑαυτοῦ τύχην κρίνοι· καὶ γὰρ τὸ τυχεῖν τῆς ἡγεμονικῆς κλήσεως ἐπικίνδυνον εἶναι·"},{"number":208,"text":"ἔπειθʼ ὅτι διοικήσει τὴν ἀρχὴν ὥσπερ ἀγαθὸς προστάτης, οὐχ ὡς τύραννος· ἀρκεῖσθαι γὰρ τῇ τιμῇ τῆς προσηγορίας, τὴν δʼ ἐφʼ ἑκάστῳ τῶν πραγμάτων βουλὴν πᾶσιν ἀποδώσειν. καὶ γὰρ εἰ μὴ φύσει μέτριος ἦν, ἱκανὸν ὑπόδειγμα σωφροσύνης αὐτῷ προκεῖσθαι τὸν Γαΐου θάνατον."},{"number":209,"text":"Ταῦτʼ ἀπήγγειλεν Ἀγρίππας. ἡ δὲ βουλὴ ἀπεκρίνατο καὶ στρατῷ καὶ γνώμαις ἀγαθαῖς πεποιθυῖα δουλείαν ἑκούσιον οὐχ ὑπομενεῖν. καὶ Κλαύδιος ὡς ἤκουσεν τὰ παρὰ τῆς βουλῆς, πάλιν ἔπεμψεν τὸν Ἀγρίππαν ἀπαγγελοῦντα αὐτοῖς ὅτι προδοῦναι μὲν τοὺς εἰς αὐτὸν ὁμονοήσαντας οὐχ ὑπομένοι, πολεμήσειν δʼ ἄκων πρὸς οὓς ἥκιστα βούλοιτο."},{"number":210,"text":"δεῖν μέντοι προαποδειχθῆναι τῷ πολέμῳ χωρίον ἔξω τῆς πόλεως· οὐ γὰρ ὅσιον διὰ τὴν αὐτῶν κακοβουλίαν ὁμοφύλῳ φόνῳ μιαίνεσθαι τὰ τεμένη τῆς πατρίδος. ὁ μὲν οὖν ἀκούσας ταῦτα τοῖς βουλευταῖς ἀπήγγειλεν."},{"number":211,"text":"Μεταξὺ δὲ τῶν μετὰ τῆς συγκλήτου στρατιωτῶν τις σπασάμενος τὸ ξίφος ἄνδρες, ἐβόησεν, συστρατιῶται, τί παθόντες ἀδελφοκτονεῖν βουλόμεθα καὶ κατὰ τῶν μετὰ Κλαυδίου συγγενῶν ὁρμᾶν, ἔχοντες μὲν αὐτοκράτορα μηδὲν μεμφθῆναι δυνάμενον, τοσαῦτα δὲ τὰ δίκαια πρὸς οὓς μετὰ τῶν ὅπλων χωρεῖν μέλλομεν;"},{"number":212,"text":"ταῦτα εἰπὼν διὰ μέσης ὥρμησεν τῆς βουλῆς πάντας τοὺς συστρατιώτας ἐφελκόμενος. οἱ δʼ εὐπατρίδαι παραχρῆμα μὲν πρὸς τὴν ἀπόλειψιν περιδεῶς ἔσχον, αὖθις δʼ ὡς ἀποστροφὴ σωτήριος οὐ κατεφαίνετο, τὴν τῶν στρατιωτῶν ὁδὸν ἠπείγοντο πρὸς Κλαύδιον."},{"number":213,"text":"ὑπήντων δʼ αὐτοῖς πρὸ τοῦ τείχους γυμνοῖς τοῖς ξίφεσιν οἱ σφοδρότερον κολακεύοντες τὴν τύχην· κἂν συνέβη κινδυνεῦσαι τοὺς προάγοντας πρὶν γνῶναι τὴν ὁρμὴν τῶν στρατιωτῶν Κλαύδιον, εἰ μὴ προσδραμὼν Ἀγρίππας αὐτῷ τὸ κινδύνευμα τῆς πράξεως ἐδήλωσεν, ὅτι τε εἰ μὴ κατάσχοι τὴν ὁρμὴν τῶν ἐπὶ τοὺς εὐπατρίδας λελυσσηκότων, ἀπολέσας διʼ οὓς τὸ κρατεῖν ἐστι περίοπτον ἐρημίας ἔσοιτο βασιλεύς."},{"number":214,"text":"Ταῦτʼ ἀκούσας Κλαύδιος κατέσχεν τὰς ὁρμὰς τοῦ στρατιωτικοῦ προσδέχεταί τε τὴν σύγκλητον εἰς τὸ στρατόπεδον καὶ φιλοφρονησάμενος ἐξῄει σὺν αὐτοῖς αὐτίκα θύσων τῷ θεῷ τὰ περὶ τῆς ἡγεμονίας χαριστήρια."},{"number":215,"text":"καὶ τὸν Ἀγρίππαν εὐθέως ἐδωρεῖτο τῇ πατρῴᾳ βασιλείᾳ πάσῃ προστιθεὶς ἔξωθεν καὶ τὰς ὑπʼ Αὐγούστου δοθείσας Ἡρώδῃ Τραχωνῖτιν καὶ Αὐρανῖτιν, χωρὶς δὲ τούτων ἑτέραν βασιλείαν τὴν Λυσανίου καλουμένην."},{"number":216,"text":"καὶ τῷ μὲν δήμῳ διατάγματι τὴν δωρεὰν ἐδήλου, τοῖς ἄρχουσιν δὲ προσέταξεν ἐγχαράξαντας δέλτοις χαλκαῖς τὴν δόσιν εἰς τὸ Καπετώλιον ἀναθεῖναι·"},{"number":217,"text":"δωρεῖται δʼ αὐτοῦ καὶ τὸν ἀδελφὸν Ἡρώδην, ὁ δʼ αὐτὸς καὶ γαμβρὸς ἦν Βερνίκῃ συνοικῶν, βασιλείᾳ τῇ Χαλκίδι."},{"number":218,"text":"Ταχέως δʼ ὡς ἂν ἐκ τοσαύτης ἀρχῆς πλοῦτος Ἀγρίππᾳ προσέρρει, καὶ τοῖς χρήμασιν αὐτὸς οὐκ εἰς μακρὰν κατεχρήσατο· τηλικοῦτον γὰρ τοῖς Ἱεροσολύμοις περιβαλεῖν ἤρξατο τεῖχος, ἡλίκον ἂν τελεσθὲν ἀνήνυτον Ῥωμαίοις ἐποίησεν τὴν πολιορκίαν."},{"number":219,"text":"ἀλλʼ ἔφθη πρὶν ὑψῶσαι τὸ ἔργον τελευτήσας ἐν Καισαρείᾳ, βεβασιλευκὼς μὲν ἔτη τρία, πρότερον δὲ τῶν τετραρχιῶν τρισὶν ἑτέροις ἔτεσιν ἀφηγησάμενος."},{"number":220,"text":"καταλείπει δὲ τρεῖς μὲν θυγατέρας ἐκ Κύπρου γεγενημένας, Βερνίκην καὶ Μαριάμμην καὶ Δρουσίλλαν, υἱὸν δὲ ἐκ τῆς αὐτῆς Ἀγρίππαν. οὗ παντάπασιν ὄντος νηπίου πάλιν τὰς βασιλείας Κλαύδιος ἐπαρχίαν ποιήσας ἐπίτροπον πέμπει Κούσπιον Φᾶδον, ἔπειτα Τιβέριον Ἀλέξανδρον, οἳ μηδὲν παρακινοῦντες τῶν ἐπιχωρίων ἐθῶν ἐν εἰρήνῃ τὸ ἔθνος διεφύλαξαν."},{"number":221,"text":"μετὰ ταῦτα καὶ ὁ βασιλεύων τῆς Χαλκίδος Ἡρώδης τελευτᾷ, καταλιπὼν ἐκ μὲν τῆς ἀδελφιδῆς Βερνίκης δύο παῖδας Βερνικιανόν τε καὶ Ὑρκανόν, ἐκ δὲ τῆς προτέρας Μαριάμμης Ἀριστόβουλον. τεθνήκει δʼ αὐτῷ καὶ ἕτερος ἀδελφὸς Ἀριστόβουλος ἰδιώτης καταλιπὼν Ἰωτάπην θυγατέρα."},{"number":222,"text":"οὗτοι μὲν οὖν ἦσαν, ὡς προεῖπον, Ἀριστοβούλου τοῦ Ἡρώδου παῖδες, Ἀριστόβουλος δὲ καὶ Ἀλέξανδρος ἐκ Μαριάμμης Ἡρώδῃ γεγόνεισαν υἱεῖς, οὓς ὁ πατὴρ ἀνεῖλεν· ἡ δὲ Ἀλεξάνδρου γενεὰ τῆς μεγάλης Ἀρμενίας ἐβασίλευσεν."}],"12":[{"number":223,"text":"Μετὰ δὲ τὴν Ἡρώδου τελευτήν, ὃς ἦρχε τῆς Χαλκίδος, καθίστησιν Κλαύδιος εἰς τὴν βασιλείαν τοῦ θείου τὸν Ἀγρίππαν υἱὸν Ἀγρίππα· τῆς δʼ ἄλλης ἐπαρχίας διαδέχεται τὴν ἐπιτροπὴν ἀπὸ Ἀλεξάνδρου Κουμανός, ἐφʼ οὗ θόρυβοί τε ἤρξαντο καὶ φθορὰ πάλιν Ἰουδαίων ἐγένετο."},{"number":224,"text":"συνεληλυθότος γὰρ τοῦ πλήθους ἐπὶ τὴν ἑορτὴν τῶν ἀζύμων εἰς Ἱεροσόλυμα καὶ τῆς Ῥωμαϊκῆς σπείρας ὑπὲρ τὴν τοῦ ἱεροῦ στοὰν ἐφεστώσης, ἔνοπλοι δʼ ἀεὶ τὰς ἑορτὰς παραφυλάττουσιν, ὡς μή τι νεωτερίζοι τὸ πλῆθος ἠθροισμένον, εἷς τις τῶν στρατιωτῶν ἀνασυράμενος τὴν ἐσθῆτα καὶ κατακύψας ἀσχημόνως προσαπέστρεψεν τοῖς Ἰουδαίοις τὴν ἕδραν καὶ τῷ σχήματι φωνὴν ὁμοίαν ἐπεφθέγξατο."},{"number":225,"text":"πρὸς τοῦτο ἅπαν μὲν τὸ πλῆθος ἠγανάκτησεν, καὶ κατεβόων τοῦ Κουμανοῦ κολάζειν τὸν στρατιώτην, οἱ δὲ ἧττον νήφοντες τῶν νέων καὶ τὸ φύσει στασιῶδες ἐκ τοῦ ἔθνους ἐχώρουν ἐπὶ μάχην λίθους τε ἁρπάσαντες ἐπὶ τοὺς στρατιώτας ἔβαλλον."},{"number":226,"text":"καὶ Κουμανὸς δείσας μὴ τοῦ λαοῦ παντὸς ἐπʼ αὐτὸν ὁρμὴ γένοιτο, πλείους ὁπλίτας μεταπέμπεται. τῶν δὲ ταῖς στοαῖς ἐπιχεομένων φόβος ἐμπίπτει τοῖς Ἰουδαίοις ἀκατάσχετος, καὶ τραπέντες ἐκ τοῦ ἱεροῦ διέφευγον εἰς τὴν πόλιν."},{"number":227,"text":"τοσαύτη δὲ περὶ τὰς ἐξόδους βία συνωθουμένων ἐγένετο, ὥστε πατηθέντας ὑπʼ ἀλλήλων καὶ συντριβέντας ὑπὲρ τρισμυρίους ἀποθανεῖν, γενέσθαι δὲ τὴν ἑορτὴν πένθος μὲν ὅλῳ τῷ ἔθνει θρῆνον δὲ καθʼ ἑκάστην οἰκίαν."},{"number":228,"text":"Μετελάμβανεν δὲ ταύτην τὴν συμφορὰν ἄλλος λῃστρικὸς θόρυβος. κατὰ γὰρ τὴν Βαιθωρὼ δημοσίαν ὁδὸν Στεφάνου τινὸς δούλου Καίσαρος ἀποσκευὴν κομιζομένην διήρπασαν λῃσταὶ προσπεσόντες."},{"number":229,"text":"Κουμανὸς δὲ περιπέμψας τοὺς ἐκ τῶν πλησίον κωμῶν δεσμώτας ἐκέλευσεν ἀνάγεσθαι πρὸς αὐτόν, ἐπικαλῶν ὅτι μὴ διώξαντες τοὺς λῃστὰς συλλάβοιεν. ἔνθα τῶν στρατιωτῶν τις εὑρὼν ἔν τινι κώμῃ τὸν ἱερὸν νόμον διέρρηξέν τε τὸ βιβλίον καὶ εἰς πῦρ κατέβαλεν."},{"number":230,"text":"Ἰουδαῖοι δὲ ὡς ὅλης αὐτοῖς τῆς χώρας καταφλεγείσης συνεχύθησαν, καὶ καθάπερ ὀργάνῳ τινὶ τῇ δεισιδαιμονίᾳ συνελκόμενοι πρὸς ἓν κήρυγμα πάντες εἰς Καισάρειαν ἐπὶ Κουμανὸν συνέδραμον ἱκετεύοντες τὸν οὕτως εἰς τὸν θεὸν καὶ τὸν νόμον αὐτῶν ἐξυβρίσαντα μὴ περιιδεῖν ἀτιμώρητον."},{"number":231,"text":"ὁ δέ, οὐ γὰρ ἠρέμει τὸ πλῆθος, εἰ μὴ τύχοι παραμυθίας, ἠξίου τε προάγειν τὸν στρατιώτην καὶ διὰ μέσων τῶν αἰτιωμένων ἀπαχθῆναι τὴν ἐπὶ θανάτῳ κελεύει. καὶ Ἰουδαῖοι μὲν ἀνεχώρουν."},{"number":232,"text":"Αὖθις δὲ Γαλιλαίων καὶ Σαμαρέων γίνεται συμβολή. κατὰ γὰρ Γήμαν καλουμένην κώμην, ἥτις ἐν τῷ μεγάλῳ πεδίῳ κεῖται τῆς Σαμαρείτιδος, πολλῶν ἀναβαινόντων Ἰουδαίων ἐπὶ τὴν ἑορτὴν ἀναιρεῖταί τις Γαλιλαῖος."},{"number":233,"text":"πρὸς τοῦτο πλεῖστοι μὲν ἐκ τῆς Γαλιλαίας συνέδραμον ὡς πολεμήσοντες τοῖς Σαμαρεῦσιν, οἱ γνώριμοι δʼ αὐτῶν ἐλθόντες πρὸς Κουμανὸν ἠντιβόλουν πρὶν ἀνηκέστου πάθους εἰς τὴν Γαλιλαίαν διαβάντα τιμωρήσασθαι τοὺς αἰτίους τοῦ φόνου· μόνως γὰρ ἂν οὕτως διαλυθῆναι πρὸ πολέμου τὸ πλῆθος. Κουμανὸς μὲν οὖν ἐν δευτέρῳ τὰς ἐκείνων ἱκεσίας τῶν ἐν χειρὶ πραγμάτων θέμενος ἀπράκτους ἀπέπεμψεν τοὺς ἱκέτας."},{"number":234,"text":"Ἀγγελθὲν δὲ εἰς Ἱεροσόλυμα τὸ πάθος τοῦ πεφονευμένου τὰ πλήθη συνετάραξεν καὶ τῆς ἑορτῆς ἀφέμενοι πρὸς τὴν Σαμάρειαν ἐξώρμων ἀστρατήγητοι καὶ μηδενὶ τῶν ἀρχόντων κατέχοντι πειθόμενοι."},{"number":235,"text":"τοῦ λῃστρικοῦ δʼ αὐτῶν καὶ στασιώδους Δειναίου τις υἱὸς Ἐλεάζαρος καὶ Ἀλέξανδρος ἐξῆρχον, οἳ τοῖς ὁμόροις τῆς Ἀκραβατηνῆς τοπαρχίας προσπεσόντες αὐτούς τε ἀνῄρουν μηδεμιᾶς ἡλικίας φειδὼ ποιούμενοι καὶ τὰς κώμας ἐνεπίμπρασαν."},{"number":236,"text":"Κουμανὸς δὲ ἀναλαβὼν ἀπὸ τῆς Καισαρείας μίαν ἴλην ἱππέων καλουμένην Σεβαστηνῶν ἐξεβοήθει τοῖς πορθουμένοις καὶ τῶν περὶ τὸν Ἐλεάζαρον πολλοὺς μὲν συνέλαβεν, πλείστους δʼ ἀπέκτεινεν."},{"number":237,"text":"πρὸς δὲ τὸ λοιπὸν πλῆθος τῶν πολεμεῖν τοῖς Σαμαρεῦσιν ὡρμημένων οἱ ἄρχοντες τῶν Ἱεροσολύμων ἐκδραμόντες σάκκους ἀμπεχόμενοι καὶ τέφραν τῶν κεφαλῶν καταχέοντες ἱκέτευον ἀναχωρεῖν καὶ μὴ διὰ τὴν εἰς Σαμαρεῖς ἄμυναν ἐπὶ Ἱεροσόλυμα Ῥωμαίους παροξύνειν, ἐλεῆσαί τε τὴν πατρίδα καὶ τὸν ναὸν τέκνα τε καὶ γυναῖκας ἰδίας, ἃ πάντα κινδυνεύειν διʼ ἑνὸς ἐκδικίαν Γαλιλαίου παραπολέσθαι."},{"number":238,"text":"τούτοις πεισθέντες Ἰουδαῖοι διελύθησαν. ἐτράποντο δὲ πολλοὶ πρὸς λῃστείαν διὰ τὴν ἄδειαν, καὶ κατὰ πᾶσαν τὴν χώραν ἁρπαγαί τε ἦσαν καὶ τῶν θρασυτέρων ἐπαναστάσεις."},{"number":239,"text":"καὶ τῶν Σαμαρέων οἱ δυνατοὶ πρὸς Οὐμμίδιον Κουαδρᾶτον, ὃς ἦν ἡγεμὼν τῆς Συρίας, εἰς Τύρον παραγενόμενοι δίκην τινὰ παρὰ τῶν πορθησάντων τὴν χώραν ἠξίουν λαβεῖν."},{"number":240,"text":"παρόντες δὲ καὶ οἱ γνώριμοι τῶν Ἰουδαίων καὶ ὁ ἀρχιερεὺς Ἰωνάθης υἱὸς Ἀνάνου κατάρξαι μὲν ἔλεγον τῆς ταραχῆς Σαμαρέας διὰ τὸν φόνον, αἴτιον δὲ τῶν ἀποβεβηκότων Κουμανὸν γεγονέναι μὴ θελήσαντα τοὺς αὐθέντας τοῦ σφαγέντος ἐπεξελθεῖν."},{"number":241,"text":"Κουαδρᾶτος δὲ τότε μὲν ἑκατέρους ὑπερτίθεται φήσας, ἐπειδὰν εἰς τοὺς τόπους παραγένηται, διερευνήσειν ἕκαστα, αὖθις δὲ παρελθὼν εἰς Καισάρειαν τοὺς ὑπὸ Κουμανοῦ ζωγρηθέντας ἀνεσταύρωσεν πάντας."},{"number":242,"text":"ἐκεῖθεν εἰς Λύδδα παραγενόμενος πάλιν διήκουσεν τῶν Σαμαρέων, καὶ μεταπεμψάμενος ὀκτωκαίδεκα τῶν Ἰουδαίων, οὓς ἐπέπυστο μετεσχηκέναι τῆς μάχης, πελέκει διεχειρίσατο·"},{"number":243,"text":"δύο δʼ ἑτέρους τῶν δυνατωτάτων καὶ τοὺς ἀρχιερεῖς Ἰωνάθην καὶ Ἀνανίαν τόν τε τούτου παῖδα Ἄνανον καί τινας ἄλλους Ἰουδαίων γνωρίμους ἀνέπεμψεν ἐπὶ Καίσαρα, ὁμοίως δὲ καὶ Σαμαρέων τοὺς ἐπιφανεστάτους."},{"number":244,"text":"παρήγγειλεν δὲ καὶ Κουμανῷ καὶ Κέλερι τῷ χιλιάρχῳ πλεῖν ἐπὶ Ῥώμης δώσοντας Κλαυδίῳ λόγον ὑπὲρ τῶν γεγενημένων. ταῦτα διαπραξάμενος ἀπὸ Λύδδων ἀνέβαινεν εἰς Ἱεροσόλυμα, καὶ καταλαβὼν τὸ πλῆθος ἄγον τὴν τῶν ἀζύμων ἑορτὴν ἀθορύβως εἰς Ἀντιόχειαν ἐπανῄει."},{"number":245,"text":"Κατὰ δὲ τὴν Ῥώμην Καῖσαρ ἀκούσας Κουμανοῦ καὶ Σαμαρέων, παρῆν δὲ καὶ Ἀγρίππας ἐκθύμως ὑπεραγωνιζόμενος Ἰουδαίων ἐπειδὴ καὶ Κουμανῷ πολλοὶ τῶν δυνατῶν παρίσταντο, Σαμαρέων μὲν καταγνοὺς τρεῖς ἀνελεῖν προσέταξεν τοὺς δυνατωτάτους, Κουμανὸν δὲ ἐφυγάδευσεν."},{"number":246,"text":"Κέλερα δὲ δεσμώτην ἀναπέμψας εἰς Ἱεροσόλυμα παραδοθῆναι Ἰουδαίοις πρὸς αἰκίαν ἐκέλευσεν καὶ περισυρέντα τὴν πόλιν οὕτω τὴν κεφαλὴν ἀποκοπῆναι."},{"number":247,"text":"Μετὰ ταῦτα Ἰουδαίας μὲν ἐπίτροπον Φήλικα τὸν Πάλλαντος ἀδελφὸν ἐκπέμπει τῆς τε Σαμαρείας καὶ Γαλιλαίας καὶ Περαίας, ἐκ δὲ τῆς Χαλκίδος Ἀγρίππαν εἰς μείζονα βασιλείαν μετατίθησιν, δοὺς αὐτῷ τήν τε Φιλίππου γενομένην ἐπαρχίαν, αὕτη δʼ ἦν Τραχωνῖτις καὶ Βατανέα καὶ Γαυλανῖτις, προσέθηκεν δὲ τήν τε Λυσανίου βασιλείαν καὶ τὴν Οὐάρου γενομένην τετραρχίαν."},{"number":248,"text":"αὐτὸς δὲ διοικήσας τὴν ἡγεμονίαν ἔτεσι τρισκαίδεκα, πρὸς δὲ μησὶν ὀκτὼ καὶ εἴκοσιν ἡμέραις τελευτᾷ καταλιπὼν Νέρωνα τῆς ἀρχῆς διάδοχον,"},{"number":249,"text":"ὃν ταῖς Ἀγριππίνης τῆς γυναικὸς ἀπάταις ἐπὶ κληρονομίᾳ τῆς ἀρχῆς εἰσεποιήσατο καίπερ υἱὸν ἔχων γνήσιον Βρεττανικὸν ἐκ Μεσσαλίνης τῆς προτέρας γυναικὸς καὶ Ὀκταουίαν θυγατέρα τὴν ὑπʼ αὐτοῦ ζευχθεῖσαν Νέρωνι· γεγόνει δʼ αὐτῷ καὶ ἐκ Παιτίνης Ἀντωνία."}],"13":[{"number":250,"text":"Ὅσα μὲν οὖν Νέρων διʼ ὑπερβολὴν εὐδαιμονίας τε καὶ πλούτου παραφρονήσας ἐξύβρισεν εἰς τὴν τύχην, ἢ τίνα τρόπον τόν τε ἀδελφὸν καὶ τὴν γυναῖκα καὶ τὴν μητέρα διεξῆλθεν, ἀφʼ ὧν ἐπὶ τοὺς εὐγενεστάτους μετήνεγκεν τὴν ὠμότητα,"},{"number":251,"text":"καὶ ὡς τελευταῖον ὑπὸ φρενοβλαβείας ἐξώκειλεν εἰς σκηνὴν καὶ θέατρον, ἐπειδὴ διʼ ὄχλου πᾶσίν ἐστιν, παραλείψω, τρέψομαι δὲ ἐπὶ τὰ Ἰουδαίοις κατʼ αὐτὸν γενόμενα."},{"number":252,"text":"Τὴν μὲν οὖν μικρὰν Ἀρμενίαν δίδωσιν βασιλεύειν Ἀριστοβούλῳ τῷ Ἡρώδου, τῇ δʼ Ἀγρίππα βασιλείᾳ τέσσαρας πόλεις προστίθησιν σὺν ταῖς τοπαρχίαις, Ἄβελα μὲν καὶ Ἰουλιάδα κατὰ τὴν Περαίαν, Ταριχέας δὲ καὶ Τιβεριάδα τῆς Γαλιλαίας, εἰς δὲ τὴν λοιπὴν Ἰουδαίαν Φήλικα κατέστησεν ἐπίτροπον."},{"number":253,"text":"οὗτος τόν τε ἀρχιλῃστὴν Ἐλεάζαρον ἔτεσιν εἴκοσι τὴν χώραν λῃσάμενον καὶ πολλοὺς τῶν σὺν αὐτῷ ζωγρήσας ἀνέπεμψεν εἰς Ῥώμην· τῶν δʼ ἀνασταυρωθέντων ὑπʼ αὐτοῦ λῃστῶν καὶ τῶν ἐπὶ κοινωνίᾳ φωραθέντων δημοτῶν οὓς ἐκόλασεν, ἄπειρόν τι πλῆθος ἦν."},{"number":254,"text":"Καθαρθείσης δὲ τῆς χώρας ἕτερον εἶδος λῃστῶν ἐν Ἱεροσολύμοις ἐπεφύετο, οἱ καλούμενοι σικάριοι, μεθʼ ἡμέραν καὶ ἐν μέσῃ τῇ πόλει φονεύοντες ἀνθρώπους,"},{"number":255,"text":"μάλιστα [δὲ] ἐν ταῖς ἑορταῖς μισγόμενοι τῷ πλήθει καὶ ταῖς ἐσθῆσιν ὑποκρύπτοντες μικρὰ ξιφίδια, τούτοις ἔνυττον τοὺς διαφόρους, ἔπειτα πεσόντων μέρος ἐγίνοντο τῶν ἐπαγανακτούντων οἱ πεφονευκότες, διὸ καὶ παντάπασιν ὑπὸ ἀξιοπιστίας ἦσαν ἀνεύρετοι."},{"number":256,"text":"πρῶτος μὲν οὖν ὑπʼ αὐτῶν Ἰωνάθης ὁ ἀρχιερεὺς ἀποσφάττεται, μετὰ δʼ αὐτὸν καθʼ ἡμέραν ἀνῃροῦντο πολλοί· καὶ τῶν συμφορῶν ὁ φόβος ἦν χαλεπώτερος, ἑκάστου καθάπερ ἐν πολέμῳ καθʼ ὥραν τὸν θάνατον προσδεχομένου."},{"number":257,"text":"προεσκοποῦντο δὲ πόρρωθεν τοὺς διαφόρους, καὶ οὐδὲ τοῖς φίλοις προσιοῦσιν πίστις ἦν, ἐν μέσαις δὲ ταῖς ὑπονοίαις καὶ ταῖς φυλακαῖς ἀνῃροῦντο· τοσοῦτον τῶν ἐπιβουλευόντων τὸ τάχος ἦν καὶ τοῦ λαθεῖν ἡ τέχνη."},{"number":258,"text":"Συνέστη δὲ πρὸς τούτοις στῖφος ἕτερον πονηρῶν χειρὶ μὲν καθαρώτερον, ταῖς γνώμαις δὲ ἀσεβέστερον, ὅπερ οὐδὲν ἧττον τῶν σφαγέων τὴν εὐδαιμονίαν τῆς πόλεως ἐλυμήνατο."},{"number":259,"text":"πλάνοι γὰρ ἄνθρωποι καὶ ἀπατεῶνες προσχήματι θειασμοῦ νεωτερισμοὺς καὶ μεταβολὰς πραγματευόμενοι δαιμονᾶν τὸ πλῆθος ἔπειθον καὶ προῆγον εἰς τὴν ἐρημίαν ὡς ἐκεῖ τοῦ θεοῦ δείξοντος αὐτοῖς σημεῖα ἐλευθερίας."},{"number":260,"text":"ἐπὶ τούτοις Φῆλιξ, ἐδόκει γὰρ ἀποστάσεως εἶναι καταβολή, πέμψας ἱππεῖς καὶ πεζοὺς ὁπλίτας πολὺ πλῆθος διέφθειρεν."},{"number":261,"text":"Μείζονι δὲ τούτου πληγῇ Ἰουδαίους ἐκάκωσεν ὁ Αἰγύπτιος ψευδοπροφήτης· παραγενόμενος γὰρ εἰς τὴν χώραν ἄνθρωπος γόης καὶ προφήτου πίστιν ἐπιθεὶς ἑαυτῷ περὶ τρισμυρίους μὲν ἀθροίζει τῶν ἠπατημένων,"},{"number":262,"text":"περιαγαγὼν δὲ αὐτοὺς ἐκ τῆς ἐρημίας εἰς τὸ ἐλαιῶν καλούμενον ὄρος ἐκεῖθεν οἷός τε ἦν εἰς Ἱεροσόλυμα παρελθεῖν βιάζεσθαι καὶ κρατήσας τῆς τε Ῥωμαϊκῆς φρουρᾶς καὶ τοῦ δήμου τυραννεῖν χρώμενος τοῖς συνεισπεσοῦσιν δορυφόροις."},{"number":263,"text":"φθάνει δʼ αὐτοῦ τὴν ὁρμὴν Φῆλιξ ὑπαντήσας μετὰ τῶν Ῥωμαϊκῶν ὁπλιτῶν, καὶ πᾶς ὁ δῆμος συνεφήψατο τῆς ἀμύνης, ὥστε συμβολῆς γενομένης τὸν μὲν Αἰγύπτιον φυγεῖν μετʼ ὀλίγων, διαφθαρῆναι δὲ καὶ ζωγρηθῆναι πλείστους τῶν σὺν αὐτῷ, τὸ δὲ λοιπὸν πλῆθος σκεδασθὲν ἐπὶ τὴν ἑαυτῶν ἕκαστον διαλαθεῖν."},{"number":264,"text":"Κατεσταλμένων δὲ καὶ τούτων ὥσπερ ἐν νοσοῦντι σώματι πάλιν ἕτερον μέρος ἐφλέγμαινεν. οἱ γὰρ γόητες καὶ λῃστρικοὶ συναχθέντες πολλοὺς εἰς ἀπόστασιν ἐνῆγον καὶ πρὸς ἐλευθερίαν παρεκρότουν θάνατον ἐπιτιμῶντες τοῖς πειθαρχοῦσιν τῇ Ῥωμαίων ἡγεμονίᾳ καὶ πρὸς βίαν ἀφαιρήσεσθαι λέγοντες τοὺς ἑκουσίως δουλεύειν προαιρουμένους."},{"number":265,"text":"μεριζόμενοι δὲ εἰς τὴν χώραν κατὰ λόχους διήρπαζόν τε τὰς τῶν δυνατῶν οἰκίας καὶ αὐτοὺς ἀνῄρουν καὶ τὰς κώμας ἐνεπίμπρασαν, ὥστε τῆς ἀπονοίας αὐτῶν πᾶσαν τὴν Ἰουδαίαν ἀναπίμπλασθαι. καὶ οὗτος μὲν ὁ πόλεμος καθʼ ἡμέραν ἀνερριπίζετο."},{"number":266,"text":"Ἑτέρα δὲ ταραχὴ συνίσταται περὶ Καισάρειαν τῶν ἀναμεμιγμένων Ἰουδαίων πρὸς τοὺς ἐν αὐτῇ Σύρους στασιασάντων. οἱ μὲν γὰρ ἠξίουν σφετέραν εἶναι τὴν πόλιν Ἰουδαῖον γεγονέναι τὸν κτίστην αὐτῆς λέγοντες· ἦν δὲ Ἡρώδης ὁ βασιλεύς· οἱ δὲ ἕτεροι τὸν οἰκιστὴν μὲν προσωμολόγουν Ἰουδαῖον, αὐτὴν μέντοι γε τὴν πόλιν Ἑλλήνων ἔφασαν· οὐ γὰρ ἂν ἀνδριάντας καὶ ναοὺς ἐγκαθιδρῦσαι Ἰουδαίοις αὐτὴν ἀνατιθέντα."},{"number":267,"text":"διὰ ταῦτα δὲ ἠμφισβήτουν ἑκάτεροι· προῄει δʼ αὐτοῖς τὸ φιλόνεικον εἰς ὅπλα καὶ καθʼ ἡμέραν οἱ θρασύτεροι παρʼ ἀμφοῖν προεπήδων ἐπὶ μάχην· οὔτε γὰρ Ἰουδαίων οἱ γεραιοὶ τοὺς ἰδίους στασιαστὰς κατέχειν οἷοί τε ἦσαν καὶ τοῖς Ἕλλησιν αἶσχος ἐδόκει Ἰουδαίων ἐλαττοῦσθαι."},{"number":268,"text":"προεῖχον δʼ οἱ μὲν πλούτῳ καὶ σωμάτων ἀλκῇ, τὸ δὲ Ἑλληνικὸν τῇ παρὰ τῶν στρατιωτῶν ἀμύνῃ· τὸ γὰρ πλέον Ῥωμαίοις τῆς ἐκεῖ δυνάμεως ἐκ Συρίας ἦν κατειλεγμένον καὶ καθάπερ συγγενεῖς ἦσαν πρὸς τὰς βοηθείας ἕτοιμοι."},{"number":269,"text":"τοῖς γε μὴν ἐπάρχοις φροντὶς ἦν ἀναστέλλειν τὴν ταραχὴν καὶ τοὺς μαχιμωτέρους ἀεὶ συλλαμβάνοντες ἐκόλαζον μάστιξι καὶ δεσμοῖς. οὐ μὴν τὰ πάθη τῶν συλλαμβανομένων ἐνεποίει τοῖς καταλειπομένοις ἀνακοπὴν ἢ δέος, ἀλλʼ ἔτι μᾶλλον παρωξύνοντο πρὸς τὴν στάσιν."},{"number":270,"text":"νικῶντας δέ ποτε τοὺς Ἰουδαίους προελθὼν εἰς τὴν ἀγορὰν ὁ Φῆλιξ μετʼ ἀπειλῆς ἐκέλευσεν ἀναχωρεῖν. τῶν δὲ μὴ πειθομένων ἐπιπέμψας τοὺς στρατιώτας ἀναιρεῖ συχνούς, ὧν διαρπαγῆναι συνέβη καὶ τὰς οὐσίας. μενούσης δὲ τῆς στάσεως ἐπιλέξας ἑκατέρωθεν τοὺς γνωρίμους ἔπεμψεν πρέσβεις ἐπὶ Νέρωνα διαλεξομένους περὶ τῶν δικαίων."}],"14":[{"number":271,"text":"Διαδεξάμενος δὲ παρὰ τούτου τὴν ἐπιτροπὴν ὁ Φῆστος τὸ μάλιστα λυμαινόμενον τὴν χώραν ἐπεξῄει· τῶν γοῦν λῃστῶν συνέλαβέν τε πλείστους καὶ διέφθειρεν οὐκ ὀλίγους."},{"number":272,"text":"ἀλλʼ οὐχ ὁ μετὰ Φῆστον Ἀλβῖνος τὸν αὐτὸν τρόπον ἐξηγήσατο τῶν πραγμάτων, οὐκ ἔστιν δὲ ἥντινα κακουργίας ἰδέαν παρέλειπεν."},{"number":273,"text":"οὐ μόνον γοῦν ἐν τοῖς πολιτικοῖς πράγμασιν ἔκλεπτεν καὶ διήρπαζεν τὰς ἑκάστων οὐσίας, οὐδὲ τὸ πᾶν ἔθνος ἐβάρει ταῖς εἰσφοραῖς, ἀλλὰ καὶ τοὺς ἐπὶ λῃστείᾳ δεδεμένους ὑπὸ τῆς παρʼ ἑκάστοις βουλῆς ἢ τῶν προτέρων ἐπιτρόπων ἀπελύτρου τοῖς συγγενέσιν, καὶ μόνος ὁ μὴ δοὺς τοῖς δεσμωτηρίοις ὡς πονηρὸς ἐγκατελείπετο."},{"number":274,"text":"τηνικαῦτα καὶ τῶν νεωτερίζειν βουλομένων ἐν Ἱεροσολύμοις ἐθάρσησαν αἱ τόλμαι, καὶ χρήμασιν μὲν οἱ δυνατοὶ τὸν Ἀλβῖνον προσελάμβανον ὥστε τοῦ στασιάζειν αὐτοῖς παρέχειν ἄδειαν, τοῦ δημοτικοῦ δὲ τὸ μὴ χαῖρον ἡσυχίᾳ πρὸς τοὺς Ἀλβίνου κοινωνοὺς ἀπέκλινεν."},{"number":275,"text":"ἕκαστος δὲ τῶν πονηρῶν ἴδιον στῖφος ὑπεζωσμένος αὐτὸς μὲν ὥσπερ ἀρχιλῃστὴς ἢ τύραννος προανεῖχεν ἐκ τοῦ λόχου, τοῖς δορυφοροῦσι δὲ πρὸς ἁρπαγὰς τῶν μετρίων κατεχρῆτο."},{"number":276,"text":"συνέβαινεν δὲ τοὺς μὲν ἀφῃρημένους ὑπὲρ ὧν ἀγανακτεῖν ἐχρῆν σιωπᾶν, τοὺς ἄπληγας δὲ δέει τοῦ μὴ τὰ αὐτὰ παθεῖν καὶ κολακεύειν τὸν ἄξιον κολάσεως. καθόλου δὲ ἡ μὲν παρρησία πάντων περικέκοπτο, τυραννὶς δʼ ἦν διὰ πλειόνων, καὶ τὰ σπέρματα τῆς μελλούσης ἁλώσεως ἔκτοτε τῇ πόλει κατεβάλλετο."},{"number":277,"text":"Τοιοῦτον δʼ ὄντα τὸν Ἀλβῖνον ἀπέδειξεν ὁ μετʼ αὐτὸν ἐλθὼν Γέσσιος Φλῶρος ἀγαθώτατον κατὰ σύγκρισιν. ὁ μέν γε λάθρα τὰ πολλὰ καὶ μεθʼ ὑποστολῆς ἐκακούργησεν, Γέσσιος δὲ τὰς εἰς τὸ ἔθνος παρανομίας ἐπόμπευσεν καὶ ὥσπερ ἐπὶ τιμωρίᾳ κατακρίτων πεμφθεὶς δήμιος οὔτε ἁρπαγῆς τινα τρόπον οὔτε αἰκίας παρέλιπεν."},{"number":278,"text":"ἦν δὲ ἐν μὲν τοῖς ἐλεεινοῖς ὠμότατος, ἐν δὲ τοῖς αἰσχροῖς ἀναιδέστατος. οὔτε δὲ πλείω τις ἀπιστίαν τῆς ἀληθείας κατέχεεν οὔτε ἐν τῷ πανουργεῖν δολιωτέρας ὁδοὺς ἐπενόησεν. ᾧ τὸ μὲν κατʼ ἄνδρα κερδαίνειν μικρὸν ἐδόκει, πόλεις δʼ ὅλας ἐξεδίδυσκε καὶ δήμους ἀθρόους ἐλυμαίνετο καὶ μόνον οὐκ ἐκήρυξεν ἀνὰ τὴν χώραν πᾶσιν ἐξεῖναι λῃστεύειν ἐφʼ ᾧ μέρος αὐτὸς λήψεται τῶν λαφύρων."},{"number":279,"text":"διὰ γοῦν τὴν ἐκείνου πλεονεξίαν πάσας ἐρημωθῆναι συνέβη τὰς πόλεις καὶ πολλοὺς τῶν πατρίων ἠθῶν ἐξαναστάντας φυγεῖν εἰς τὰς ἀλλοφύλους ἐπαρχίας."},{"number":280,"text":"Μέχρι μὲν οὖν ἐν Συρίᾳ Κέστιος Γάλλος ἦν διέπων τὴν ἐπαρχίαν, οὐδὲ πρεσβεύσασθαί τις πρὸς αὐτὸν ἐτόλμησεν κατὰ τοῦ Φλώρου· παραγενόμενον δὲ εἰς Ἱεροσόλυμα τῆς τῶν ἀζύμων ἑορτῆς ἐνεστώσης περιστὰς ὁ δῆμος οὐκ ἐλάττους τριακοσίων μυριάδων ἱκέτευον ἐλεῆσαι τὰς τοῦ ἔθνους συμφορὰς καὶ τὸν λυμεῶνα τῆς χώρας Φλῶρον ἐκεκράγεσαν·"},{"number":281,"text":"ὁ δὲ παρὼν καὶ τῷ Κεστίῳ παρεστὼς διεχλεύαζεν τὰς φωνάς. ὅ γε μὴν Κέστιος τὴν ὁρμὴν τοῦ πλήθους καταστείλας καὶ δοὺς ἔμφασιν ὡς πρὸς τὸ μέλλον αὐτοῖς τὸν Φλῶρον κατασκευάσειεν μετριώτερον, ὑπέστρεφεν εἰς Ἀντιόχειαν."},{"number":282,"text":"προέπεμπε δὲ αὐτὸν μέχρι Καισαρείας Φλῶρος ἐξαπατῶν καὶ πόλεμον ἤδη τῷ ἔθνει σκοπούμενος, ᾧ μόνῳ συγκρύψειν τὰς ἑαυτοῦ παρανομίας ὑπελάμβανεν·"},{"number":283,"text":"εἰρήνης μὲν γὰρ οὔσης κατηγόρους ἕξειν ἐπὶ Καίσαρος Ἰουδαίους προσεδόκα, πραγματευσάμενος δὲ ἀπόστασιν αὐτῶν τῷ μείζονι κακῷ περισπάσειν τὸν ἔλεγχον ἀπὸ τῶν μετριωτέρων. ὁ μὲν οὖν, ὡς ἂν ἀπορραγείη τὸ ἔθνος, καθʼ ἡμέραν ἐπέτεινεν αὐτοῖς τὰς συμφοράς."},{"number":284,"text":"Ἐν δὲ τούτῳ καὶ οἱ Καισαρέων Ἕλληνες νικήσαντες παρὰ Νέρωνι τῆς πόλεως ἄρχειν τὰ τῆς κρίσεως ἐκόμισαν γράμματα, καὶ προσελάμβανεν τὴν ἀρχὴν ὁ πόλεμος δωδεκάτῳ μὲν ἔτει τῆς Νέρωνος ἡγεμονίας, ἑπτακαιδεκάτῳ δὲ τῆς Ἀγρίππα βασιλείας, Ἀρτεμισίου μηνός."},{"number":285,"text":"πρὸς δὲ τὸ μέγεθος τῶν ἐξ αὐτοῦ συμφορῶν οὐκ ἀξίαν ἔσχεν πρόφασιν· οἱ γὰρ ἐν Καισαρείᾳ Ἰουδαῖοι, συναγωγὴν ἔχοντες παρὰ χωρίον, οὗ δεσπότης ἦν τις Ἕλλην Καισαρεύς, πολλάκις μὲν κτήσασθαι τὸν τόπον ἐσπούδασαν τιμὴν πολλαπλασίονα τῆς ἀξίας διδόντες·"},{"number":286,"text":"ὡς δʼ ὑπερορῶν τὰς δεήσεις πρὸς ἐπήρειαν ἔτι καὶ παρῳκοδόμει τὸ χωρίον ἐκεῖνος ἐργαστήρια κατασκευαζόμενος στενήν τε καὶ παντάπασιν βιαίαν πάροδον ἀπέλειπεν αὐτοῖς, τὸ μὲν πρῶτον οἱ θερμότεροι τῶν νέων προπηδῶντες οἰκοδομεῖν ἐκώλυον."},{"number":287,"text":"ὡς δὲ τούτους εἶργεν τῆς βίας Φλῶρος, ἀμηχανοῦντες οἱ δυνατοὶ τῶν Ἰουδαίων, σὺν οἷς Ἰωάννης ὁ τελώνης. πείθουσι τὸν Φλῶρον ἀργυρίου ταλάντοις ὀκτὼ διακωλῦσαι τὸ ἔργον."},{"number":288,"text":"ὁ δὲ πρὸς μόνον τὸ λαβεῖν ὑποσχόμενος πάντα συμπράξειν, λαβὼν ἔξεισιν τῆς Καισαρείας εἰς Σεβαστὴν καὶ καταλείπει τὴν στάσιν αὐτεξούσιον, ὥσπερ ἄδειαν πεπρακὼς Ἰουδαίοις τοῦ μάχεσθαι."},{"number":289,"text":"Τῆς δʼ ἐπιούσης ἡμέρας ἑβδομάδος οὔσης τῶν Ἰουδαίων εἰς τὴν συναγωγὴν συναθροισθέντων στασιαστής τις Καισαρεὺς γάστραν καταστρέψας καὶ παρὰ τὴν εἴσοδον αὐτῶν θέμενος ἐπέθυεν ὄρνεις. τοῦτο τοὺς Ἰουδαίους ἀνηκέστως παρώξυνεν ὡς ὑβρισμένων μὲν αὐτοῖς τῶν νόμων, μεμιασμένου δὲ τοῦ χωρίου."},{"number":290,"text":"τὸ μὲν οὖν εὐσταθὲς καὶ πρᾷον ἐπὶ τοὺς ἡγεμόνας ἀναφεύγειν ᾤετο χρῆναι, τὸ στασιῶδες δὲ καὶ ἐν νεότητι φλεγμαῖνον ἐξεκαίετο πρὸς μάχην. παρεσκευασμένοι δὲ εἱστήκεσαν οἱ τῶν Καισαρέων στασιασταί, τὸν γὰρ ἐπιθύσοντα προπεπόμφεσαν ἐκ συντάγματος, καὶ ταχέως ἐγένετο συμβολή."},{"number":291,"text":"προσελθὼν δὲ Ἰούκουνδος ὁ διακωλύειν τεταγμένος ἱππάρχης τήν τε γάστραν αἴρει καὶ καταπαύειν ἐπειρᾶτο τὴν στάσιν. ἡττωμένου δʼ αὐτοῦ τῆς τῶν Καισαρέων βίας Ἰουδαῖοι τοὺς νόμους ἁρπάσαντες ἀνεχώρησαν εἰς Νάρβατα· χώρα τις αὐτῶν οὕτω καλεῖται σταδίους ἑξήκοντα διέχουσα τῆς Καισαρείας·"},{"number":292,"text":"οἱ δὲ περὶ τὸν Ἰωάννην δυνατοὶ δώδεκα πρὸς Φλῶρον ἐλθόντες εἰς Σεβαστὴν ἀπωδύροντο περὶ τῶν πεπραγμένων καὶ βοηθεῖν ἱκέτευον, αἰδημόνως ὑπομιμνήσκοντες τῶν ὀκτὼ ταλάντων. ὁ δὲ καὶ συλλαβὼν ἔδησεν τοὺς ἄνδρας αἰτιώμενος ὑπὲρ τοῦ τοὺς νόμους ἐξενεγκεῖν τῆς Καισαρείας."},{"number":293,"text":"Πρὸς τοῦτο τῶν ἐν Ἱεροσολύμοις ἀγανάκτησις ἦν, ἔτι μέντοι τοὺς θυμοὺς κατεῖχον. ὁ δὲ Φλῶρος ὥσπερ ἠργολαβηκὼς ἐκριπίζειν τὸν πόλεμον, πέμψας εἰς τὸν ἱερὸν θησαυρὸν ἐξαιρεῖ δεκαεπτὰ τάλαντα σκηψάμενος εἰς τὰς Καίσαρος χρείας."},{"number":294,"text":"σύγχυσις δʼ εὐθέως εἶχεν τὸν δῆμον, καὶ συνδραμόντες εἰς τὸ ἱερὸν βοαῖς διαπρυσίοις τὸ Καίσαρος ἀνεκάλουν ὄνομα καὶ τῆς Φλώρου τυραννίδος ἐλευθεροῦν σφᾶς ἱκέτευον."},{"number":295,"text":"ἔνιοι δὲ τῶν στασιαστῶν λοιδορίας αἰσχίστους εἰς τὸν Φλῶρον ἐκεκράγεσαν καὶ κανοῦν περιφέροντες ἀπῄτουν αὐτῷ κέρματα καθάπερ ἀκλήρῳ καὶ ταλαιπώρῳ. τούτοις οὐκ ἀνετράπη τὴν φιλαργυρίαν, ἀλλʼ ἐπὶ τὸ μᾶλλον χρηματίσασθαι παρωργίσθη."},{"number":296,"text":"δέον γοῦν εἰς Καισάρειαν ἐλθόντα σβέσαι τὸ τοῦ πολέμου πῦρ ἐκεῖθεν ἀρχόμενον καὶ τῆς ταραχῆς ἀνελεῖν τὰς αἰτίας, ἐφʼ ᾧ καὶ μισθὸν ἔλαβεν, ὁ δὲ μετὰ στρατιᾶς ἱππικῆς τε καὶ πεζικῆς ἐπὶ Ἱεροσολύμων ὥρμησεν, ἵνα τοῖς Ῥωμαίων ὅπλοις ἐργάσηται καὶ τῷ δέει καὶ ταῖς ἀπειλαῖς περιδύσῃ τὴν πόλιν."},{"number":297,"text":"Ὁ δὲ δῆμος προδυσωπῆσαι τὴν ὁρμὴν αὐτοῦ βουλόμενος ὑπαντᾷ τοῖς στρατιώταις μετʼ εὐφημίας καὶ τὸν Φλῶρον θεραπευτικῶς ἐκδέχεσθαι παρεσκευάσατο."},{"number":298,"text":"κἀκεῖνος προπέμψας σὺν ἱππεῦσιν πεντήκοντα Καπίτωνα ἑκατοντάρχην ἀναχωρεῖν αὐτοὺς ἐκέλευσεν καὶ μὴ πρὸς ὃν οὕτως ἐλοιδόρησαν αἰσχρῶς εἰρωνεύεσθαι τὰς νῦν φιλοφρονήσεις·"},{"number":299,"text":"δεῖν γὰρ αὐτούς, εἴπερ γενναῖοί εἰσιν καὶ παρρησιασταί, σκώπτειν μὲν αὐτὸν καὶ παρόντα, φαίνεσθαι δὲ μὴ μόνον ἐν τοῖς λόγοις, ἀλλὰ κἀν τοῖς ὅπλοις φιλελευθέρους."},{"number":300,"text":"τούτοις καταπλαγὲν τὸ πλῆθος, ἅμα καὶ τῶν περὶ Καπίτωνα ἱππέων εἰς μέσον φερομένων, διεσκεδάσθη πρὶν ἀσπάσασθαι τὸν Φλῶρον ἢ τοῖς στρατιώταις φανερὸν ποιῆσαι τὸ πειθήνιον. ἀναχωρήσαντες δὲ εἰς τὰς οἰκίας μετὰ δέους καὶ ταπεινότητος ἐνυκτέρευσαν."},{"number":301,"text":"Φλῶρος δὲ τότε μὲν ἐν τοῖς βασιλείοις αὐλίζεται, τῇ δʼ ὑστεραίᾳ βῆμα πρὸ αὐτῶν θέμενος καθέζεται, καὶ προσελθόντες οἵ τε ἀρχιερεῖς καὶ δυνατοὶ τό τε γνωριμώτατον τῆς πόλεως παρέστησαν τῷ βήματι."},{"number":302,"text":"τούτοις ὁ Φλῶρος ἐκέλευσεν τοὺς λοιδορήσαντας αὐτὸν ἐκδοῦναι, φάμενος αὐτοὺς ἀπολαύσειν τῆς ἀμύνης, εἰ μὴ προάγοιεν τοὺς αἰτίους. οἱ δὲ τὸν μὲν δῆμον ἀπέφηναν εἰρηνικὰ φρονοῦντα, τοῖς δὲ παραφθεγξαμένοις ᾐτοῦντο συγγνώμην·"},{"number":303,"text":"ἐν γὰρ τοσούτῳ πλήθει θαυμαστὸν μὲν οὐδὲν εἶναί τινας θρασυτέρους καὶ διʼ ἡλικίαν ἄφρονας, ἀμήχανον δὲ τῶν ἡμαρτηκότων τὴν διάκρισιν ἑκάστου μετανοοῦντος καὶ διʼ ἃ δέδρακεν ἀρνουμένου."},{"number":304,"text":"δεῖν μέντοι γε ἐκεῖνον, εἰ προνοεῖ τῆς κατὰ τὸ ἔθνος εἰρήνης καὶ βούλεται Ῥωμαίοις περισώζειν τὴν πόλιν, μᾶλλον διὰ τοὺς πολλοὺς ἀκαταιτιάτους συγγνῶναι καὶ τοῖς ὀλίγοις πλημμελήσασιν ἢ διʼ ὀλίγους πονηροὺς ταράξαι δῆμον ἀγαθὸν τοσοῦτον."},{"number":305,"text":"Πρὸς ταῦτα μᾶλλον παροξυνθεὶς ἐμβοᾷ τοῖς στρατιώταις διαρπάζειν τὴν ἄνω καλουμένην ἀγορὰν καὶ κτείνειν τοὺς ἐντυγχάνοντας. οἱ δʼ ἐπιθυμίᾳ κέρδους προσλαβόντες ἡγεμονικὴν παρακέλευσιν οὐ μόνον ἐφʼ ὃν ἐπέμφθησαν τόπον ἥρπαζον, ἀλλʼ εἰς πάσας ἐμπηδῶντες τὰς οἰκίας ἔσφαζον τοὺς οἰκήτορας."},{"number":306,"text":"φυγὴ δʼ ἦν ἐκ τῶν στενωπῶν καὶ φόνος τῶν καταλαμβανομένων, τρόπος τε ἁρπαγῆς οὐδεὶς παρελείπετο, καὶ πολλοὺς τῶν μετρίων συλλαβόντες ἐπὶ τὸν Φλῶρον ἀνῆγον· οὓς μάστιξιν προαικισάμενος ἀνεσταύρωσεν."},{"number":307,"text":"ὁ δὲ σύμπας τῶν ἐκείνης ἀπολομένων τῆς ἡμέρας ἀριθμὸς σὺν γυναιξὶν καὶ τέκνοις, οὐδὲ γὰρ νηπίων ἀπέσχοντο, περὶ τριάκοντα καὶ ἑξακοσίους συνήχθη."},{"number":308,"text":"βαρυτέραν τε ἐποίει τὴν συμφορὰν τὸ καινὸν τῆς Ῥωμαίων ὠμότητος· ὃ γὰρ μηδεὶς πρότερον τότε Φλῶρος ἐτόλμησεν, ἄνδρας ἱππικοῦ τάγματος μαστιγῶσαί τε πρὸ τοῦ βήματος καὶ σταυρῷ προσηλῶσαι, ὧν εἰ καὶ τὸ γένος Ἰουδαίων ἀλλὰ γοῦν τὸ ἀξίωμα Ῥωμαϊκὸν ἦν."}],"15":[{"number":309,"text":"Κατὰ τοῦτον τὸν καιρὸν ὁ μὲν βασιλεὺς Ἀγρίππας ἔτυχεν εἰς τὴν Ἀλεξάνδρειαν πεπορευμένος, ὅπως Ἀλεξάνδρῳ συνησθείη πεπιστευμένῳ τὴν Αἴγυπτον ὑπὸ Νέρωνος καὶ πεμφθέντι διέπειν."},{"number":310,"text":"τὴν ἀδελφὴν δὲ αὐτοῦ Βερνίκην παροῦσαν ἐν Ἱεροσολύμοις καὶ τὴν παρανομίαν τῶν στρατιωτῶν θεωμένην δεινὸν εἰσῄει πάθος, καὶ πολλάκις τούς τε ἱππάρχους ἑαυτῆς καὶ σωματοφύλακας πέμπουσα πρὸς Φλῶρον ἐδέετο παύσασθαι τοῦ φόνου."},{"number":311,"text":"καὶ ὁ μὲν οὔτε εἰς τὸ πλῆθος τῶν ἀναιρουμένων οὔτε εἰς τὴν εὐγένειαν τῆς παρακαλούσης, ἀλλʼ εἰς μόνον τὸ λυσιτελὲς τὸ ἐκ τῶν ἁρπαγῶν ἀποβλέπων παρήκουσεν."},{"number":312,"text":"ἡ δʼ ὁρμὴ τῶν στρατιωτῶν ἐλύσσησεν καὶ κατὰ τῆς βασιλίδος· οὐ μόνον γοῦν ἐν ὄμμασιν αὐτῆς ᾐκίζοντο τοὺς ἁλισκομένους καὶ διέφθειρον, ἀλλὰ κἂν αὐτὴν ἀνεῖλον, εἰ μὴ καταφυγεῖν εἰς τὴν βασιλικὴν αὐλὴν ἔφθη, κἀκεῖ διενυκτέρευσεν μετὰ φυλακῆς δεδοικυῖα τὴν τῶν στρατιωτῶν ἔφοδον."},{"number":313,"text":"ἐπεδήμει δʼ ἐν τοῖς Ἱεροσολύμοις εὐχὴν ἐκτελοῦσα τῷ θεῷ· τοὺς γὰρ ἢ νόσῳ καταπονουμένους ἤ τισιν ἄλλαις ἀνάγκαις ἔθος εὔχεσθαι πρὸ τριάκοντα ἡμερῶν ἧς ἀποδώσειν μέλλοιεν θυσίας οἴνου τε ἀφέξεσθαι καὶ ξυρήσεσθαι τὰς κόμας."},{"number":314,"text":"ἃ δὴ καὶ τότε τελοῦσα Βερνίκη γυμνόπους τε πρὸ τοῦ βήματος ἱκέτευε τὸν Φλῶρον καὶ πρὸς τῷ μὴ τυχεῖν αἰδοῦς αὐτὴν τὸν περὶ τοῦ ζῆν κίνδυνον ἐπείρασεν."},{"number":315,"text":"Ταῦτα μὲν οὖν ἑξκαιδεκάτῃ μηνὸς Ἀρτεμισίου συνηνέχθη, τῇ δʼ ἐπιούσῃ τὸ μὲν πλῆθος ὑπερπαθῆσαν εἰς τὴν ἄνω συνέρρευσεν ἀγορὰν καὶ βοαῖς ἐξαισίοις περὶ τῶν ἀπολωλότων ἀνωδύρετο· τὸ πλέον δὲ ἦσαν εἰς τὸν Φλῶρον ἐπίφθονοι φωναί."},{"number":316,"text":"πρὸς ὃ δείσαντες οἱ δυνατοὶ σὺν τοῖς ἀρχιερεῦσιν τὰς ἐσθῆτας περιερρήξαντο καὶ προσπίπτοντες ἕκαστος ἐδέοντο παύσασθαι καὶ μὴ πρὸς οἷς πεπόνθασιν εἰς ἀνήκεστόν τι τὸν Φλῶρον ἐρεθίζειν."},{"number":317,"text":"ἐπείσθη δὲ τὸ πλῆθος ταχέως αἰδοῖ τε τῶν παρακαλούντων καὶ κατʼ ἐλπίδα τοῦ μηδὲν ἔτι τὸν Φλῶρον εἰς αὐτοὺς παρανομήσειν."},{"number":318,"text":"Ὁ δὲ σβεσθείσης τῆς ταραχῆς ἤχθετο καὶ πάλιν αὐτὴν ἀνάψαι πραγματευόμενος τούς τε ἀρχιερεῖς σὺν τοῖς γνωρίμοις μεταπέμπεται καὶ μόνον ἔφη τεκμήριον ἔσεσθαι τοῦ μηδὲν ἔτι τὸν δῆμον νεωτερίσειν, εἰ προελθόντες ὑπαντήσουσιν τοῖς ἀπὸ Καισαρείας ἀνιοῦσιν στρατιώταις· παρεγίνοντο δὲ δύο σπεῖραι."},{"number":319,"text":"τῶν δʼ ἔτι συγκαλούντων τὸ πλῆθος προπέμψας διεδήλου τοῖς τῶν σπειρῶν ἑκατοντάρχοις, ὅπως παραγγείλωσιν τοῖς ὑφʼ ἑαυτοὺς μήτε ἀντασπάσασθαι τοὺς Ἰουδαίους κἄν τι κατʼ αὐτοῦ φθέγξωνται, χρήσασθαι τοῖς ὅπλοις."},{"number":320,"text":"οἱ δʼ ἀρχιερεῖς εἰς τὸ ἱερὸν τὴν πληθὺν συναγαγόντες ὑπαντᾶν τοῖς Ῥωμαίοις παρεκάλουν καὶ πρὸ ἀνηκέστου πάθους τὰς σπείρας δεξιοῦσθαι. τούτοις τὸ στασιῶδες ἠπείθει, καὶ διὰ τοὺς ἀπολωλότας τὸ πλῆθος ἔρρεπεν πρὸς τοὺς θρασυτέρους."},{"number":321,"text":"Ἔνθα δὴ πᾶς μὲν ἱερεὺς πᾶς δʼ ὑπηρέτης τοῦ θεοῦ τὰ ἅγια σκεύη προκομίσαντες καὶ τὸν κόσμον, ἐν ᾧ λειτουργεῖν ἔθος ἦν αὐτοῖς, ἀναλαβόντες κιθαρισταί τε καὶ ὑμνῳδοὶ μετὰ τῶν ὀργάνων προσέπιπτον καὶ κατηντιβόλουν φυλάξαι τὸν ἱερὸν κόσμον αὐτοῖς καὶ μὴ πρὸς ἁρπαγὴν τῶν θείων κειμηλίων Ῥωμαίους ἐρεθίσαι."},{"number":322,"text":"τοὺς δʼ ἀρχιερεῖς αὐτοὺς ἦν ἰδεῖν καταμωμένους μὲν τὴν κεφαλὴν κόνει, γυμνοὺς δὲ τὰ στέρνα τῶν ἐσθήτων διερρηγμένων. ὀνομαστὶ δʼ ἕκαστον τῶν γνωρίμων καὶ κοινῇ τὸ πλῆθος ἱκέτευον μὴ διʼ ἐλαχίστης πλημμελείας προδοῦναι τὴν πατρίδα τοῖς ἐπιθυμοῦσιν πορθῆσαι·"},{"number":323,"text":"τίνα γὰρ ἢ τοῖς στρατιώταις φέρειν ὠφέλειαν τὸν ἀπὸ Ἰουδαίων ἀσπασμὸν ἢ διόρθωσιν αὐτοῖς τῶν συμβεβηκότων τὸ μὴ νῦν προελθεῖν;"},{"number":324,"text":"εἰ δὲ δὴ δεξιώσαιντο τοὺς προσιόντας ὡς ἔθος, Φλώρῳ μὲν ἀποκοπήσεσθαι τὴν ἀφορμὴν τοῦ πολέμου, κερδήσειν δʼ αὐτοὺς τὴν πατρίδα καὶ τὸ μηδὲν παθεῖν πλέον. ἄλλως τε καὶ τὸ πείθεσθαι στασιάζουσιν ὀλίγοις, δέον αὐτοὺς δῆμον ὄντας τοσοῦτον συναναγκάζειν κἀκείνους συνευγνωμονεῖν, δεινῆς ἀκρασίας εἶναι."},{"number":325,"text":"Τούτοις μειλισσόμενοι τὸ πλῆθος ἅμα καὶ τῶν στασιαστῶν οὓς μὲν ἀπειλαῖς οὓς δὲ αἰδοῖ κατέστειλαν. ἔπειτα ἐξηγούμενοι μεθʼ ἡσυχίας τε καὶ κόσμου τοῖς στρατιώταις ὑπήντων καὶ πλησίον γενομένους ἠσπάσαντο· τῶν δὲ μηδὲν ἀποκριναμένων οἱ στασιασταὶ Φλώρου κατεβόων."},{"number":326,"text":"τοῦτο ἦν σύνθημα κατʼ αὐτῶν δεδομένον· αὐτίκα γοῦν οἱ στρατιῶται περισχόντες αὐτοὺς ἔπαιον ξύλοις, καὶ φεύγοντας οἱ ἱππεῖς καταδιώκοντες συνεπάτουν. ἔπιπτον δὲ πολλοὶ μὲν ὑπὸ Ῥωμαίων τυπτόμενοι, πλείους δʼ ὑπʼ ἀλλήλων βιαζόμενοι."},{"number":327,"text":"δεινὸς δὲ περὶ τὰς πύλας ὠθισμὸς ἦν, καὶ φθάνειν ἑκάστου σπεύδοντος βραδυτέρα μὲν ἡ φυγὴ πᾶσιν ἐγίνετο, τῶν δὲ σφαλέντων ἀπώλεια δεινή· πνιγόμενοι γὰρ καὶ κλώμενοι πλήθει τῶν ἐπιβαινόντων ἠφανίζοντο, καὶ οὐδὲ πρὸς ταφήν τις γνώριμος τοῖς ἰδίοις κατελείπετο."},{"number":328,"text":"συνέπιπτον δὲ καὶ στρατιῶται παίοντες ἀνέδην τοὺς καταλαμβανομένους καὶ διὰ τῆς Βεθεζὰ καλουμένης ἀνεώθουν τὸ πλῆθος βιαζόμενοι παρελθεῖν καὶ κρατῆσαι τοῦ τε ἱεροῦ καὶ τῆς Ἀντωνίας· ὧν καὶ Φλῶρος ἐφιέμενος ἐξῆγε τῆς βασιλικῆς αὐλῆς τοὺς σὺν αὐτῷ καὶ πρὸς τὸ φρούριον ἐλθεῖν ἠγωνίζετο."},{"number":329,"text":"διήμαρτέν γε μὴν τῆς ἐπιβολῆς· ὁ γὰρ δῆμος ἄντικρυς ἐπιστραφεὶς εἶργεν τῆς ὁρμῆς, καὶ διαστάντες ἐπὶ τῶν τεγῶν τοὺς Ῥωμαίους ἔβαλλον. καταπονούμενοι δὲ τοῖς ὕπερθεν βέλεσιν καὶ διακόψαι τὸ τοὺς στενωποὺς ἐμφράξαν πλῆθος ἀσθενήσαντες ἀνεχώρουν εἰς τὸ πρὸς τοῖς βασιλείοις στρατόπεδον."},{"number":330,"text":"Οἱ δὲ στασιασταὶ δείσαντες μὴ πάλιν ἐπελθὼν ὁ Φλῶρος κρατήσῃ τοῦ ἱεροῦ διὰ τῆς Ἀντωνίας, ἀναβάντες εὐθέως τὰς συνεχεῖς στοὰς τοῦ ἱεροῦ πρὸς τὴν Ἀντωνίαν διέκοψαν."},{"number":331,"text":"τοῦτʼ ἔψυξεν τὴν Φλώρου πλεονεξίαν· τῶν γὰρ τοῦ θεοῦ θησαυρῶν ἐφιέμενος καὶ διὰ τοῦτο παρελθεῖν ἐπιθυμῶν εἰς τὴν Ἀντωνίαν, ὡς ἀπερράγησαν αἱ στοαί, τὴν ὁρμὴν ἀνετράπη, καὶ μεταπεμψάμενος τούς τε ἀρχιερεῖς καὶ τὴν βουλὴν αὐτὸς μὲν ἐξιέναι τῆς πόλεως ἔφη, φρουρὰν δʼ ἐγκαταλείψειν αὐτοῖς ὅσην ἂν ἀξιώσωσιν."},{"number":332,"text":"τῶν δὲ πάντα περὶ ἀσφαλείας καὶ τοῦ μηδὲν νεωτερίσειν ὑποσχομένων, εἰ μίαν αὐτοῖς καταλείποι σπεῖραν, μὴ μέντοι τὴν μαχεσαμένην· πρὸς γὰρ ταύτην ἀπεχθῶς διʼ ἃ πέπονθεν ἔχειν τὸ πλῆθος· ἀλλάξας τὴν σπεῖραν, ὡς ἠξίουν, μετὰ τῆς λοιπῆς δυνάμεως ὑπέστρεψεν εἰς Καισάρειαν."}],"16":[{"number":333,"text":"Ἑτέραν δὲ ἐπιβολὴν τῷ πολέμῳ ποριζόμενος ἐπέστελλεν Κεστίῳ Ἰουδαίων ἀπόστασιν καταψευδόμενος τήν τε ἀρχὴν τῆς μάχης περιθεὶς αὐτοῖς καὶ δρᾶσαι λέγων ἐκείνους ἃ πεπόνθεσαν. οὐ μὴν οὐδʼ οἱ τῶν Ἱεροσολύμων ἄρχοντες ἐσίγησαν, ἀλλʼ αὐτοί τε καὶ Βερνίκη τῷ Κεστίῳ περὶ ὧν Φλῶρος εἰς τὴν πόλιν παρηνόμησεν ἔγραφον."},{"number":334,"text":"ὁ δὲ τὰ παρʼ ἀμφοῖν ἀναγνοὺς μετὰ τῶν ἡγεμόνων ἐβουλεύετο. τοῖς μὲν οὖν αὐτὸν ἐδόκει Κέστιον μετὰ στρατιᾶς ἀναβαίνειν ἢ τιμωρησόμενον τὴν ἀπόστασιν, εἰ γέγονεν, ἢ βεβαιοτέρους καταστήσοντα Ἰουδαίους καὶ συμμένοντας, αὐτῷ δὲ προπέμψαι τῶν ἑταίρων τὸν κατασκεψόμενον τὰ πράγματα καὶ τὰ φρονήματα τῶν Ἰουδαίων πιστῶς ἀναγγελοῦντα."},{"number":335,"text":"πέμπει δή τινα τῶν χιλιάρχων Νεαπολιτανόν, ὃς ἀπὸ τῆς Ἀλεξανδρείας ὑποστρέφοντι περιτυχὼν Ἀγρίππᾳ τῷ βασιλεῖ κατὰ Ἰάμνειαν τόν τε πέμψαντα καὶ τὰς αἰτίας ἐδήλωσεν."},{"number":336,"text":"Ἔνθα καὶ Ἰουδαίων οἵ τε ἀρχιερεῖς ἅμα τοῖς δυνατοῖς καὶ ἡ βουλὴ παρῆν δεξιουμένη τὸν βασιλέα. μετὰ δὲ τὴν εἰς ἐκεῖνον θεραπείαν ἀπωδύροντο τὰς ἑαυτῶν συμφορὰς καὶ τὴν Φλώρου διεξῄεσαν ὠμότητα."},{"number":337,"text":"πρὸς ἣν ἠγανάκτει μὲν Ἀγρίππας, στρατηγικῶς δὲ τὴν ὀργὴν εἰς οὓς ἠλέει Ἰουδαίους μετέφερεν, ταπεινοῦν αὐτῶν βουλόμενος τὰ φρονήματα καὶ τῷ μὴ δοκεῖν ἀδίκως τι παθεῖν τῆς ἀμύνης ἀποτρέπων."},{"number":338,"text":"οἱ μὲν οὖν, ὡς ἂν ὄντες ἔκκριτοι καὶ διὰ τὰς ἑαυτῶν κτήσεις ἐπιθυμοῦντες εἰρήνης, συνίεσαν εὐνοϊκὴν τὴν ἐπίπληξιν τοῦ βασιλέως· ὁ δὲ δῆμος ἐκ τῶν Ἱεροσολύμων ἐπὶ ἑξήκοντα προελθὼν σταδίους ἐδεξιοῦτο τὸν Ἀγρίππαν καὶ τὸν Νεαπολιτανόν."},{"number":339,"text":"ἐκώκυον δὲ καὶ τῶν ἀπεσφαγμένων αἱ γυναῖκες προεκθέουσαι, καὶ πρὸς τὴν τούτων οἰμωγὴν ὁ δῆμος εἰς ὀλοφυρμοὺς τραπόμενος ἐπικουρεῖν τὸν Ἀγρίππαν ἱκέτευεν, τοῦ τε Νεαπολιτανοῦ κατεβόων ὅσα πάθοιεν ὑπὸ Φλώρου καὶ παρελθοῦσιν εἰς τὴν πόλιν τήν τε ἀγορὰν ἠρημωμένην ἐπεδείκνυσαν καὶ πεπορθημένας τὰς οἰκίας."},{"number":340,"text":"ἔπειτα διʼ Ἀγρίππα πείθουσι τὸν Νεαπολιτανὸν σὺν ἑνὶ θεράποντι περιελθεῖν μέχρι τοῦ Σιλωᾶ τὴν πόλιν, ἵνα γνῷ Ἰουδαίους τοῖς μὲν ἄλλοις Ῥωμαίοις ἅπασιν εἴκοντας, μόνῳ δʼ ἀπεχθανομένους Φλώρῳ διʼ ὑπερβολὴν τῆς εἰς αὐτοὺς ὠμότητος. ὁ δὲ ὡς διοδεύσας πεῖραν ἱκανὴν ἔλαβεν τῆς πραότητος αὐτῶν, εἰς τὸ ἱερὸν ἀναβαίνει."},{"number":341,"text":"ἔνθα συγκαλέσας τὸ πλῆθος, καὶ πολλὰ μὲν εἰς πίστιν αὐτοὺς τὴν πρὸς Ῥωμαίους ἐπαινέσας, πολλὰ δὲ εἰς τὸ τηρεῖν τὴν εἰρήνην προτρεψάμενος καὶ τοῦ θεοῦ προσκυνήσας ὅθεν ἐξῆν τὰ ἅγια πρὸς Κέστιον ἐπανῄει."},{"number":342,"text":"Τὸ δὲ πλῆθος τῶν Ἰουδαίων ἐπί τε τὸν βασιλέα καὶ τοὺς ἀρχιερεῖς τραπόμενον πέμπειν κατὰ Φλώρου πρέσβεις ἠξίου πρὸς Νέρωνα καὶ μὴ σιωπῶντας ἐπὶ τοσούτῳ φόνῳ καταλιπεῖν ἑαυτοῖς ὑπόνοιαν ἀποστάσεως· δόξειν γὰρ αὐτοὶ κατάρξαι τῶν ὅπλων, εἰ μὴ φθάσαντες ἐνδείξαιντο τὸν κατάρξαντα·"},{"number":343,"text":"φανεροὶ δʼ ἦσαν οὐκ ἠρεμήσοντες, εἰ τὴν πρεσβείαν τις ἀποκωλύει. Ἀγρίππᾳ δὲ τὸ μὲν χειροτονεῖν Φλώρου κατηγόρους ἐπίφθονον, τὸ περιιδεῖν δὲ Ἰουδαίους εἰς πόλεμον ἐκριπισθέντας οὐδὲ αὐτῷ λυσιτελὲς κατεφαίνετο."},{"number":344,"text":"προσκαλεσάμενος δὲ εἰς τὸν ξυστὸν τὸ πλῆθος καὶ παραστησάμενος ἐν περιόπτῳ τὴν ἀδελφὴν Βερνίκην ἐπὶ τῆς Ἀσαμωναίων οἰκίας, αὕτη γὰρ ἦν ἐπάνω τοῦ ξυστοῦ πρὸς τὸ πέραν τῆς ἄνω πόλεως, καὶ γέφυρα τῷ ξυστῷ τὸ ἱερὸν συνῆπτεν, Ἀγρίππας ἔλεξεν τοιάδε."},{"number":345,"text":"Εἰ μὲν ἑώρων πάντας ὑμᾶς πολεμεῖν Ῥωμαίοις ὡρμημένους καὶ μὴ τοῦ δήμου τὸ καθαρώτατον καὶ εἰλικρινέστατον εἰρήνην ἄγειν προῃρημένους, οὔτʼ ἂν παρῆλθον εἰς ὑμᾶς οὔτε συμβουλεύειν ἐθάρρησα· περισσὸς γὰρ ὑπὲρ τοῦ τὰ δέοντα ποιεῖν πᾶς λόγος, ὅταν ᾖ τῶν ἀκουόντων πάντων [ἡ] πρὸς τὸ χεῖρον ὁμόνοια."},{"number":346,"text":"ἐπεὶ δὲ τινὰς μὲν ἡλικία τῶν ἐν πολέμῳ κακῶν ἄπειρος, τινὰς δὲ ἐλπὶς ἀλόγιστος ἐλευθερίας, ἐνίους δὲ πλεονεξία τις παροξύνει καὶ τὸ παρὰ τῶν ἀσθενεστέρων, ἐὰν τὰ πράγματα συγχυθῇ, κέρδος, ὅπως αὐτοί τε σωφρονισθέντες μεταβάλωνται καὶ μὴ τῆς ἐνίων κακοβουλίας οἱ ἀγαθοὶ παραπολαύσωσιν, ᾠήθην δεῖν ἐπὶ τὸ αὐτὸ πάντας ὑμᾶς συναγαγὼν εἰπεῖν ἃ νομίζω συμφέρειν."},{"number":347,"text":"θορυβήσῃ δέ μοι μηδείς, ἐὰν μὴ τὰ πρὸς ἡδονὴν ἀκούῃ· τοῖς μὲν γὰρ ἀνηκέστως ἐπὶ τὴν ἀπόστασιν ὡρμημένοις ἔνεστι καὶ μετὰ τὴν ἐμὴν παραίνεσιν ταῦτα φρονεῖν, ἐμοὶ δὲ διαπίπτει καὶ πρὸς τοὺς ἀκούειν ἐθέλοντας ὁ λόγος, ἐὰν μὴ παρὰ πάντων ἡσυχία γένηται."},{"number":348,"text":"οἶδα μὲν οὖν ὅτι πολλοὶ τὰς ἐκ τῶν ἐπιτρόπων ὕβρεις καὶ τὰ τῆς ἐλευθερίας ἐγκώμια τραγῳδοῦσιν, ἐγὼ δὲ πρὶν ἐξετάζειν τίνες ὄντες καὶ τίσιν ἐπιχειρεῖτε πολεμεῖν, πρῶτον διαζεύξω τὴν συμπλοκὴν τῶν προφάσεων."},{"number":349,"text":"εἰ μὲν γὰρ ἀμύνεσθε τοὺς ἀδικοῦντας, τί σεμνύνετε τὴν ἐλευθερίαν; εἰ δὲ τὸ δουλεύειν ἀφόρητον ἡγεῖσθε, περισσὴ πρὸς τοὺς ἡγεμόνας ἡ μέμψις· καὶ γὰρ ἐκείνων μετριαζόντων αἰσχρὸν ὁμοίως τὸ δουλεύειν."},{"number":350,"text":"σκοπεῖτε δὲ καὶ καθʼ ἕκαστον τούτων ὡς ἔστιν μικρὰ τοῦ πολεμεῖν ἡ ὑπόθεσις, καὶ πρῶτά γε τὰ τῶν ἐπιτρόπων ἐγκλήματα· θεραπεύειν γάρ, οὐκ ἐρεθίζειν χρὴ τὰς ἐξουσίας·"},{"number":351,"text":"ὅταν δὲ τῶν μικρῶν ἁμαρτημάτων τοὺς ἐξονειδισμοὺς ποιῆσθε μεγάλους, καθʼ ἑαυτῶν τοὺς ὀνειδιζομένους ἀπελέγχετε, καὶ παρέντες τὸ λάθρα καὶ μετʼ αἰδοῦς ὑμᾶς βλάπτειν πορθοῦσι φανερῶς. οὐδὲν δὲ οὕτως τὰς πληγὰς ὡς τὸ φέρειν ἀναστέλλει, καὶ τὸ τῶν ἀδικουμένων ἡσύχιον τοῖς ἀδικοῦσι γίνεται διατροπή."},{"number":352,"text":"φέρε δʼ εἶναι τοὺς Ῥωμαίων ὑπηρέτας ἀνηκέστως χαλεπούς· οὔπω Ῥωμαῖοι πάντες ἀδικοῦσιν ὑμᾶς οὐδὲ Καῖσαρ, πρὸς οὓς αἱρεῖσθε τὸν πόλεμον· οὐδὲ γὰρ ἐξ ἐντολῆς ἥκει τις πονηρὸς ἀπʼ ἐκείνων, οὐδέ γε τοὺς ὑπὸ τὴν ἀνατολὴν οἱ ἀφʼ ἑσπέρας ἐπιβλέπουσιν· ἀλλʼ οὐδὲ ἀκούειν ταχέως τὰ ἐντεῦθεν ἐκεῖ ῥᾴδιον."},{"number":353,"text":"ἄτοπον δὲ καὶ διʼ ἕνα πολλοῖς καὶ διὰ μικρὰς αἰτίας τηλικούτοις καὶ μηδὲ γινώσκουσιν ἃ μεμφόμεθα πολεμεῖν."},{"number":354,"text":"καὶ τῶν μὲν ἡμετέρων ἐγκλημάτων ταχεῖα γένοιτʼ ἂν διόρθωσις· οὔτε γὰρ ὁ αὐτὸς ἐπίτροπος μένει διὰ παντός, καὶ τοὺς διαδεξομένους εἰκὸς ἐλεύσεσθαι μετριωτέρους· κινηθέντα δʼ ἅπαξ τὸν πόλεμον οὔτε ἀποθέσθαι ῥᾴδιον δίχα συμφορῶν οὔτε βαστάζειν."},{"number":355,"text":"ἀλλὰ μὴν τό γε νῦν ἐλευθερίας ἐπιθυμεῖν ἄωρον, δέον ὑπὲρ τοῦ μηδὲ ἀποβαλεῖν αὐτὴν ἀγωνίζεσθαι πρότερον· ἡ γὰρ πεῖρα τῆς δουλείας χαλεπή, καὶ περὶ τοῦ μηδʼ ἄρξασθαι ταύτης ὁ ἀγὼν δίκαιος."},{"number":356,"text":"ὁ δʼ ἅπαξ χειρωθείς, ἔπειτα ἀφιστάμενος, αὐθάδης δοῦλός ἐστιν, οὐ φιλελεύθερος. τότε τοιγαροῦν ἐχρῆν πάνθʼ ὑπὲρ τοῦ μὴ δέξασθαι Ῥωμαίους ποιεῖν, ὅτε ἐπέβαινεν τῆς χώρας Πομπήιος."},{"number":357,"text":"ἀλλʼ οἱ μὲν ἡμέτεροι πρόγονοι καὶ οἱ βασιλεῖς αὐτῶν καὶ χρήμασιν καὶ σώμασιν καὶ ψυχαῖς ἄμεινον ὑμῶν πολλῷ διακείμενοι πρὸς μοῖραν ὀλίγην τῆς Ῥωμαίων δυνάμεως οὐκ ἀντέσχον· ὑμεῖς δὲ οἱ τὸ μὲν ὑπακούειν ἐκ διαδοχῆς παρειληφότες, τοῖς πράγμασιν δὲ τῶν πρώτων ὑπακουσάντων τοσοῦτον ἐλαττούμενοι, πρὸς ὅλην ἀνθίστασθε τὴν Ῥωμαίων ἡγεμονίαν;"},{"number":358,"text":"καὶ Ἀθηναῖοι μὲν οἱ περὶ τῆς τῶν Ἑλλήνων ἐλευθερίας παραδόντες ποτὲ καὶ πυρὶ τὴν πόλιν, οἱ τὸν ὑπερήφανον Ξέρξην διὰ γῆς πλεύσαντα καὶ διὰ θαλάσσης ὁδεύσαντα καὶ μὴ χωρούμενον μὲν τοῖς πελάγεσιν, πλατυτέραν δὲ τῆς Εὐρώπης τὴν στρατιὰν ἄγοντα, οἷα δραπέτην ἐπὶ μιᾶς νηὸς διώξαντες, περὶ δὲ τῇ μικρᾷ Σαλαμῖνι τὴν τοσαύτην Ἀσίαν κλάσαντες νῦν δουλεύουσιν Ῥωμαίοις, καὶ τὴν ἡγεμονίδα τῆς Ἑλλάδος πόλιν διοικεῖ τὰ ἀπὸ τῆς Ἰταλίας προστάγματα."},{"number":359,"text":"Λακεδαιμόνιοι δὲ μετὰ Θερμοπύλας καὶ Πλαταιὰς καὶ τὸν ἐρευνήσαντα τὴν Ἀσίαν Ἀγησίλαον ἀγαπῶσιν τοὺς αὐτοὺς δεσπότας,"},{"number":360,"text":"καὶ Μακεδόνες ἔτι φανταζόμενοι Φίλιππον καὶ τὴν σὺν Ἀλεξάνδρῳ παρασπείρουσαν αὐτοῖς τὴν τῆς οἰκουμένης ἡγεμονίαν ὁρῶντες, φέρουσιν τὴν τοσαύτην μεταβολὴν καὶ πρὸς οὓς μεταβέβηκεν ἡ τύχη προσκυνοῦσιν."},{"number":361,"text":"ἄλλα τε ἔθνη μυρία πλείονος γέμοντα πρὸς ἐλευθερίαν παρρησίας εἴκει· μόνοι δʼ ὑμεῖς ἀδοξεῖτε δουλεύειν οἷς ὑποτέτακται τὰ πάντα. ποίᾳ στρατιᾷ ποίοις πεποιθότες ὅπλοις; ποῦ μὲν ὁ στόλος ὑμῖν διαληψόμενος τὰς Ῥωμαίων θαλάσσας; ποῦ δʼ οἱ ταῖς ἐπιβολαῖς ἐξαρκέσοντες θησαυροί;"},{"number":362,"text":"πρὸς Αἰγυπτίους ἄρα καὶ πρὸς Ἄραβας οἴεσθε κινεῖν τὸν πόλεμον; οὐ περισκέψεσθε τὴν Ῥωμαίων ἡγεμονίαν; οὐ μετρήσετε τὴν ἑαυτῶν ἀσθένειαν; οὐ τὰ μὲν ἡμέτερα καὶ τῶν προσοίκων ἐθνῶν ἡττήθη πολλάκις, ἡ δὲ ἐκείνων ἰσχὺς διὰ τῆς οἰκουμένης ἀνίκητος;"},{"number":363,"text":"μᾶλλον δὲ καὶ ταύτης ἐζήτησάν τι πλέον· οὐ γὰρ ἐξήρκεσεν αὐτοῖς ὅλος Εὐφράτης ὑπὸ τὴν ἀνατολὴν οὐδὲ τῶν προσαρκτίων ὁ Ἴστρος ἥ τε μεσημβρινὴ μέχρι τῶν ἀοικήτων ἐρευνηθεῖσα Λιβύη καὶ Γάδειρα πρὸς ἑσπέραν, ἀλλʼ ὑπὲρ ὠκεανὸν ἑτέραν ἐζήτησαν οἰκουμένην καὶ μέχρι τῶν ἀνιστορήτων πρότερον Βρεττανῶν διήνεγκαν τὰ ὅπλα."},{"number":364,"text":"τί οὖν; ὑμεῖς πλουσιώτεροι Γαλατῶν, ἰσχυρότεροι Γερμανῶν, Ἑλλήνων συνετώτεροι, πλείους τῶν κατὰ τὴν οἰκουμένην ἐστὲ πάντων; τί τὸ πεποιθὸς ὑμᾶς κατὰ Ῥωμαίων ἐπαίρει; χαλεπὸν τὸ δουλεύειν, ἐρεῖ τις."},{"number":365,"text":"πόσῳ μᾶλλον Ἕλλησιν, οἳ τῶν ὑφʼ ἡλίῳ πάντων προύχοντες εὐγενείᾳ καὶ τοσαύτην νεμόμενοι χώραν ἓξ Ῥωμαίων ὑπείκουσιν ῥάβδοις, τοσαύταις δὲ καὶ Μακεδόνες οἱ δικαιότερον ὑμῶν ὀφείλοντες ἐλευθερίας ἀντιποιεῖσθαι."},{"number":366,"text":"τί δʼ αἱ πεντακόσιαι τῆς Ἀσίας πόλεις; οὐ δίχα φρουρᾶς ἕνα προσκυνοῦσιν ἡγεμόνα καὶ τὰς ὑπατικὰς ῥάβδους; τί χρὴ λέγειν Ἡνιόχους τε καὶ Κόλχους καὶ τὸ τῶν Ταύρων φῦλον, Βοσπορανούς τε καὶ τὰ περίοικα τοῦ Πόντου καὶ τῆς Μαιώτιδος ἔθνη;"},{"number":367,"text":"παρʼ οἷς πρὶν μὲν οὐδʼ οἰκεῖος ἐγιγνώσκετο δεσπότης, νῦν δὲ τρισχιλίοις ὁπλίταις ὑποτάσσεται, καὶ τεσσαράκοντα ναῦς μακραὶ τὴν πρὶν ἄπλωτον καὶ ἀγρίαν εἰρηνεύουσι θάλασσαν."},{"number":368,"text":"πόσα Βιθυνία καὶ Καππαδοκία καὶ τὸ Παμφύλιον ἔθνος Λύκιοί τε καὶ Κίλικες ὑπὲρ ἐλευθερίας ἔχοντες εἰπεῖν χωρὶς ὅπλων φορολογοῦνται; τί δαί; Θρᾷκες οἱ πέντε μὲν εὖρος ἑπτὰ δὲ μῆκος ἡμερῶν χώραν διειληφότες, τραχυτέραν τε καὶ πολλῷ τῆς ὑμετέρας ὀχυρωτέραν καὶ βαθεῖ κρυμῷ τοὺς ἐπιστρατεύσοντας ἀνακόπτουσαν, οὐχὶ δισχιλίοις Ῥωμαίων ὑπακούουσιν φρουροῖς;"},{"number":369,"text":"οἱ δʼ ἀπὸ τούτων Ἰλλυριοὶ τὴν μέχρι Δαλματίας ἀποτεμνομένην Ἴστρῳ κατοικοῦντες, οὐ δυσὶν μόνοις τάγμασιν ὑπείκουσιν, μεθʼ ὧν αὐτοὶ τὰς Δακῶν ἀνακόπτουσιν ὁρμάς;"},{"number":370,"text":"οἱ δὲ τοσαυτάκις πρὸς ἐλευθερίαν ἀναχαιτίσαντες Δαλμάται καὶ πρὸς τὸ μόνον ἀεὶ χειρωθέντες τότε συλλεξάμενοι τὴν ἰσχὺν πάλιν ἀποστῆναι, νῦν οὐχ ὑφʼ ἑνὶ τάγματι Ῥωμαίων ἡσυχίαν ἄγουσιν;"},{"number":371,"text":"ἀλλὰ μὴν εἴ γέ τινας εἰς ἀπόστασιν ὤφειλον ἀφορμαὶ μεγάλαι παροξύνειν, μάλιστα Γαλάτας ἐχρῆν τοὺς οὕτως ὑπὸ τῆς φύσεως τετειχισμένους, ἐξ ἀνατολῆς μὲν ταῖς Ἄλπεσιν πρὸς ἄρκτῳ δὲ Ῥήνῳ ποταμῷ, μεσημβρινοῖς δὲ τοῖς Πυρηναίοις ὄρεσιν, ὠκεανῷ δὲ πρὸς δυσμῶν."},{"number":372,"text":"ἀλλὰ καίτοι τηλικαῦτα μὲν ἕρκη περιβεβλημένοι, πέντε δὲ καὶ τριακοσίοις πληθύοντες ἔθνεσιν, τὰς δὲ πηγάς, ὡς ἄν τις εἴποι, τῆς εὐδαιμονίας ἐπιχωρίους ἔχοντες καὶ τοῖς ἀγαθοῖς σχεδὸν ὅλην ἐπικλύζοντες τὴν οἰκουμένην, ἀνέχονται Ῥωμαίων πρόσοδος ὄντες καὶ ταμιευόμενοι παρʼ αὐτῶν τὴν οἰκείαν εὐδαιμονίαν."},{"number":373,"text":"καὶ τοῦθʼ ὑπομένουσιν οὐ διὰ φρονημάτων μαλακίαν οὐδὲ διʼ ἀγένειαν, οἵ γε διήνεγκαν ὀγδοήκοντα ἔτη πόλεμον ὑπὲρ τῆς ἐλευθερίας, ἀλλὰ μετὰ τῆς δυνάμεως Ῥωμαίων καὶ τὴν τύχην καταπλαγέντες, ἥτις αὐτοῖς κατορθοῖ πλείονα τῶν ὅπλων. τοιγαροῦν ὑπὸ χιλίοις καὶ διακοσίοις στρατιώταις δουλεύουσιν, ὧν ὀλίγου δεῖν πλείους ἔχουσι πόλεις."},{"number":374,"text":"οὐδὲ Ἴβηρσιν ὁ γεωργούμενος χρυσὸς εἰς τὸν ὑπὲρ τῆς ἐλευθερίας ἐξήρκεσεν πόλεμον οὐδὲ τὸ τοσοῦτον ἀπὸ Ῥωμαίων γῆς καὶ θαλάσσης διάστημα φῦλά τε Λουσιτανῶν καὶ Καντάβρων ἀρειμάνια οὐδὲ γείτων ὠκεανὸς φοβερὰν καὶ τοῖς ἐπιχωρίοις ἄμπωτιν ἐπάγων,"},{"number":375,"text":"ἀλλʼ ὑπὲρ τὰς Ἡρακλείους στήλας ἐκτείναντες τὰ ὅπλα καὶ διὰ νεφῶν ὁδεύσαντες τὰ Πυρηναῖα ὄρη καὶ τούτους ἐδουλώσαντο Ῥωμαῖοι· φρουρὰ δʼ ἤρκεσεν τῶν οὕτως δυσμάχων καὶ τοσοῦτον ἀπῳκισμένων ἓν τάγμα."},{"number":376,"text":"τίς ὑμῶν οὐκ ἀκοῇ παρείληφεν τὸ Γερμανῶν πλῆθος; ἀλκὴν μὲν γὰρ καὶ μεγέθη σωμάτων εἴδετε δήπου πολλάκις, ἐπεὶ πανταχοῦ Ῥωμαῖοι τοὺς τούτων αἰχμαλώτους ἔχουσιν."},{"number":377,"text":"ἀλλʼ οὗτοι γῆν μὲν ἄπειρον νεμόμενοι, μείζω δὲ τῶν σωμάτων ἔχοντες τὰ φρονήματα καὶ τὴν μὲν ψυχὴν θανάτου καταφρονοῦσαν, τοὺς δὲ θυμοὺς τῶν ἀγριωτάτων θηρίων σφοδροτέρους, Ῥῆνον τῆς ὁρμῆς ὅρον ἔχουσιν καὶ Ῥωμαίων ὀκτὼ τάγμασιν δαμαζόμενοι δουλεύουσιν μὲν ἁλόντες, τὸ δʼ ὅλον αὐτῶν ἔθνος φυγῇ διασώζεται."},{"number":378,"text":"σκέψασθε δὲ καὶ τὸ Βρεττανῶν τεῖχος οἱ τοῖς Ἱεροσολύμων τείχεσιν πεποιθότες· καὶ γὰρ ἐκείνους περιβεβλημένους ὠκεανὸν καὶ τῆς καθʼ ἡμᾶς οἰκουμένης οὐκ ἐλάσσονα νῆσον οἰκοῦντας πλεύσαντες ἐδουλώσαντο Ῥωμαῖοι, τέσσαρα δὲ τάγματα τὴν τοσαύτην νῆσον φυλάσσει."},{"number":379,"text":"καὶ τί δεῖ πολλὰ λέγειν, ὅπου καὶ Πάρθοι, τὸ πολεμικώτατον φῦλον, τοσούτων ἄρχοντες ἐθνῶν καὶ τηλικαύτην περιβεβλημένοι δύναμιν ὁμήρους πέμπουσιν Ῥωμαίοις, καὶ ἔστιν ἐπὶ τῆς Ἰταλίας ἰδεῖν ἐν εἰρήνης προφάσει δουλεύουσαν τὴν ἀπὸ τῆς ἀνατολῆς εὐγένειαν."},{"number":380,"text":"πάντων δὴ σχεδὸν τῶν ὑφʼ ἡλίῳ τὰ Ῥωμαίων ὅπλα προσκυνούντων ὑμεῖς μόνοι πολεμήσετε μηδὲ τὸ Καρχηδονίων τέλος σκοποῦντες, οἳ τὸν μέγαν αὐχοῦντες Ἀννίβαν καὶ τὴν ἀπὸ Φοινίκων εὐγένειαν ὑπὸ τὴν Σκιπίωνος δεξιὰν ἔπεσον;"},{"number":381,"text":"οὔτε δὲ Κυρηναῖοι, τὸ Λακώνων γένος, οὔτε Μαρμαρίδαι, τὸ μέχρι τῆς διψάδος ἐκτεταμένον φῦλον, οὔθʼ αἱ φοβεραὶ καὶ τοῖς ἀκούουσιν Σύρτεις Νασαμῶνές τε καὶ Μαῦροι καὶ τὸ Νομάδων ἄπειρον πλῆθος τὰς Ῥωμαίων ἀνέκοψαν ἀρετάς."},{"number":382,"text":"τὴν δὲ τρίτην τῆς οἰκουμένης μοῖραν, ἧς οὐδὲ ἐξαριθμήσασθαι τὰ ἔθνη ῥᾴδιον, ὁριζομένην Ἀτλαντικῷ τε πελάγει καὶ στήλαις Ἡρακλείοις καὶ μέχρι τῆς Ἐρυθρᾶς θαλάσσης τοὺς ἀπείρους νέμουσαν Αἰθίοπας ἐχειρώσαντο μὲν ὅλην,"},{"number":383,"text":"χωρὶς δὲ τῶν ἐτησίων καρπῶν, οἳ μησὶν ὀκτὼ τὸ κατὰ τὴν Ῥώμην πλῆθος τρέφουσιν, καὶ ἔξωθεν παντοίως φορολογοῦνται καὶ ταῖς χρείαις τῆς ἡγεμονίας παρέχουσιν ἑτοίμους τὰς εἰσφοράς, οὐδὲν τῶν ἐπιταγμάτων ὥσπερ ὑμεῖς ὕβριν ἡγούμενοι καίπερ ἑνὸς τάγματος αὐτοῖς παραμένοντος."},{"number":384,"text":"καὶ τί δεῖ πόρρωθεν ὑμῖν τὴν Ῥωμαίων ὑποδεικνύναι δύναμιν παρὸν ἐξ Αἰγύπτου τῆς γειτνιώσης,"},{"number":385,"text":"ἥτις ἐκτεινομένη μέχρις Αἰθιόπων καὶ τῆς εὐδαίμονος Ἀραβίας ὅρμος τε οὖσα τῆς Ἰνδικῆς, πεντήκοντα πρὸς ταῖς ἑπτακοσίαις ἔχουσα μυριάδας ἀνθρώπων δίχα τῶν Ἀλεξάνδρειαν κατοικούντων, ὡς ἔνεστιν ἐκ τῆς καθʼ ἑκάστην κεφαλὴν εἰσφορᾶς τεκμήρασθαι, τὴν Ῥωμαίων ἡγεμονίαν οὐκ ἀδοξεῖ, καίτοι πηλίκον ἀποστάσεως κέντρον ἔχουσα τὴν Ἀλεξάνδρειαν πλήθους τε ἀνδρῶν ἕνεκα καὶ πλούτου πρὸς δὲ μεγέθους·"},{"number":386,"text":"μῆκος μέν γε αὐτῆς τριάκοντα σταδίων, εὖρος δʼ οὐκ ἔλαττον δέκα, τοῦ δὲ ἐνιαυσιαίου παρʼ ὑμῶν φόρου καθʼ ἕνα μῆνα πλέον Ῥωμαίοις παρέχει καὶ τῶν χρημάτων ἔξωθεν τῇ Ῥώμῃ σῖτον μηνῶν τεσσάρων· τετείχισται δὲ πάντοθεν ἢ δυσβάτοις ἐρημίαις ἢ θαλάσσαις ἀλιμένοις ἢ ποταμοῖς ἢ ἕλεσιν."},{"number":387,"text":"ἀλλʼ οὐδὲν τούτων ἰσχυρότερον εὑρέθη τῆς Ῥωμαίων τύχης, δύο δʼ ἐγκαθήμενα τῇ πόλει τάγματα τὴν βαθεῖαν Αἴγυπτον ἅμα τῇ Μακεδόνων εὐγενείᾳ χαλινοῖ."},{"number":388,"text":"τίνας οὖν ἐπὶ τὸν πόλεμον ἐκ τῆς ἀοικήτου παραλήψεσθε συμμάχους; οἱ μὲν γὰρ ἐπὶ τῆς οἰκουμένης πάντες εἰσὶν Ῥωμαῖοι, εἰ μή τις ὑπὲρ Εὐφράτην ἐκτείνει τὰς ἐλπίδας καὶ τοὺς ἐκ τῆς Ἀδιαβηνῆς ὁμοφύλους οἴεται προσαμυνεῖν,"},{"number":389,"text":"οἱ δʼ οὔτε διʼ αἰτίαν ἄλογον τηλικούτῳ πολέμῳ συνεμπλέξουσιν ἑαυτούς, οὔτε βουλευσαμένοις κακῶς ὁ Πάρθος ἐπιτρέψει· πρόνοια γὰρ αὐτῷ τῆς πρὸς Ῥωμαίους ἐκεχειρίας, καὶ παραβαίνειν οἰήσεται τὰς σπονδάς, ἄν τις τῶν ὑπʼ αὐτὸν ἐπὶ Ῥωμαίους ἴῃ."},{"number":390,"text":"λοιπὸν οὖν ἐπὶ τὴν τοῦ θεοῦ συμμαχίαν καταφευκτέον. ἀλλὰ καὶ τοῦτο παρὰ Ῥωμαίοις τέτακται· δίχα γὰρ θεοῦ συστῆναι τηλικαύτην ἡγεμονίαν ἀδύνατον."},{"number":391,"text":"σκέψασθε δʼ ὡς ὑμῖν τὸ τῆς θρησκείας ἄκρατον, εἰ καὶ πρὸς εὐχειρώτους πολεμοίητε, δυσδιοίκητον, καὶ διʼ ἃ μᾶλλον τὸν θεὸν ἐλπίζετε σύμμαχον, ταῦτʼ ἀναγκαζόμενοι παραβαίνειν ἀποστρέψετε."},{"number":392,"text":"τηροῦντές γε μὴν τὰ τῶν ἑβδομάδων ἔθη καὶ πρὸς μηδεμίαν πρᾶξιν κινούμενοι ῥᾳδίως ἁλώσεσθε, καθάπερ οἱ πρόγονοι Πομπηίῳ ταύτας μάλιστα τὰς ἡμέρας ἐνεργοὺς ποιησαμένῳ τῆς πολιορκίας, ἐν αἷς ἤργουν οἱ πολιορκούμενοι·"},{"number":393,"text":"παραβαίνοντες δὲ ἐν τῷ πολέμῳ τὸν πάτριον νόμον οὐκ οἶδʼ ὑπὲρ ὅτου λοιπὸν ποιήσεσθε τὸν ἀγῶνα· σπουδὴ γὰρ ὑμῖν μία τὸ μὴ τῶν πατρίων τι καταλῦσαι."},{"number":394,"text":"πῶς δὲ ἐπικαλέσεσθε τὸ θεῖον πρὸς τὴν ἄμυναν οἱ παραβάντες ἑκουσίως τὴν εἰς αὐτὸ θεραπείαν; ἐπαναιροῦνται δὲ ἕκαστοι πόλεμον ἢ θείᾳ πεποιθότες ἢ ἀνθρωπίνῃ βοηθείᾳ· ὅταν δὲ τὴν παρʼ ἀμφοῖν τὸ εἰκὸς ἀποκόπτῃ, φανερὰν ἅλωσιν οἱ πολεμοῦντες αἱροῦνται."},{"number":395,"text":"τί δὴ κωλύει ταῖς ἑαυτῶν χερσὶν διαχρήσασθαι τέκνα καὶ γυναῖκας καὶ τὴν περικαλλεστάτην πατρίδα ταύτην καταφλέξαι; μανέντες γὰρ οὕτως τό γε τῆς ἥττης ὄνειδος κερδήσετε. καλόν,"},{"number":396,"text":"ὦ φίλοι, καλόν, ἕως ἔτι ἐν ὅρμῳ τὸ σκάφος προσκέπτεσθαι τὸν μέλλοντα χειμῶνα μηδʼ εἰς μέσας τὰς θυέλλας ἀπολουμένους ἀναχθῆναι· τοῖς μὲν γὰρ ἐξ ἀδήλων ἐπιπεσοῦσιν δεινοῖς τὸ γοῦν ἐλεεῖσθαι περίεστιν, ὁ δʼ εἰς πρόδηλον ἀπώλειαν ὁρμήσας καὶ προσονειδίζεται."},{"number":397,"text":"πλὴν εἰ μή τις ὑπολαμβάνει κατὰ συνθήκας πολεμήσειν καὶ Ῥωμαίους κρατήσαντας ὑμῶν μετριάσειν, ἀλλʼ οὐκ εἰς ὑπόδειγμα τῶν ἄλλων ἐθνῶν καταφλέξειν μὲν τὴν ἱερὰν πόλιν, ἀναιρήσειν δὲ πᾶν ὑμῶν τὸ φῦλον· οὐδὲ γὰρ περιλειφθέντες φυγῆς εὑρήσετε τόπον ἁπάντων ἐχόντων Ῥωμαίους δεσπότας ἢ δεδοικότων σχεῖν."},{"number":398,"text":"ὁ δὲ κίνδυνος οὐ τῶν ἐνθάδε μόνον, ἀλλὰ καὶ τῶν κατὰ τὰς ἄλλας κατοικούντων πόλεις· οὐ γὰρ ἔστιν ἐπὶ τῆς οἰκουμένης δῆμος ὁ μὴ μοῖραν ἡμετέραν ἔχων."},{"number":399,"text":"οὓς ἅπαντας πολεμησάντων ὑμῶν κατασφάξουσιν οἱ διάφοροι, καὶ διʼ ὀλίγων ἀνδρῶν κακοβουλίαν πᾶσα πλησθήσεται πόλις Ἰουδαϊκοῦ φόνου. καὶ συγγνώμη μὲν τοῖς τοῦτο πράξασιν· ἂν δὲ μὴ πραχθῇ, λογίσασθε, πῶς πρὸς οὕτω φιλανθρώπους ὅπλα κινεῖν ἀνόσιον."},{"number":400,"text":"εἰσελθέτω δʼ οἶκτος ὑμᾶς εἰ καὶ μὴ τέκνων καὶ γυναικῶν, ἀλλὰ τῆς γε μητροπόλεως ταύτης καὶ τῶν ἱερῶν περιβόλων. φείσασθε τοῦ ἱεροῦ καὶ τὸν ναὸν ἑαυτοῖς μετὰ τῶν ἁγίων τηρήσατε· ἀφέξονται γὰρ οὐκέτι Ῥωμαῖοι τούτων κρατήσαντες, ὧν φεισάμενοι πρότερον ἠχαρίστηνται."},{"number":401,"text":"μαρτύρομαι δὲ ἐγὼ μὲν ὑμῶν τὰ ἅγια καὶ τοὺς ἱεροὺς ἀγγέλους τοῦ θεοῦ καὶ πατρίδα τὴν κοινήν, ὡς οὐδὲν τῶν σωτηρίων ὑμῖν καθυφηκάμην, ὑμεῖς δὲ βουλευσάμενοι μὲν τὰ δέοντα κοινὴν σὺν ἐμοὶ τὴν εἰρήνην ἕξετε, προαχθέντες δὲ τοῖς θυμοῖς χωρὶς ἐμοῦ κινδυνεύσετε."},{"number":402,"text":"Τοσαῦτα εἰπὼν ἐπεδάκρυσέν τε μετὰ τῆς ἀδελφῆς καὶ πολὺ τῆς ὁρμῆς αὐτῶν ἔπαυσεν τοῖς δακρύοις. ἀνεβόων δὲ οὐ Ῥωμαίοις, ἀλλὰ Φλώρῳ διʼ ἃ πεπόνθασιν πολεμεῖν."},{"number":403,"text":"πρὸς τοῦτο βασιλεὺς Ἀγρίππας ἀλλὰ τὰ ἔργα, ἔφη, Ῥωμαίοις ἤδη πολεμούντων ἐστίν· οὔτε γὰρ Καίσαρι δεδώκατε τὸν φόρον καὶ τὰς στοὰς ἀπεκόψατε τῆς Ἀντωνίας."},{"number":404,"text":"ἀποσκευάσαισθε δʼ ἂν τὴν αἰτίαν τῆς ἀποστάσεως, εἰ ταύτας τε συνάψετε πάλιν καὶ τελέσετε τὴν εἰσφοράν· οὐ γὰρ δή γε Φλώρου τὸ φρούριόν ἐστιν ἢ Φλώρῳ τὰ χρήματα δώσετε."}],"17":[{"number":405,"text":"Τούτοις ὁ δῆμος ἐπείθετο, καὶ μετὰ τοῦ βασιλέως τῆς τε Βερνίκης ἀναβάντες εἰς τὸ ἱερὸν κατήρξαντο τῆς τῶν στοῶν δομήσεως, εἰς δὲ τὰς κώμας οἵ τε ἄρχοντες καὶ βουλευταὶ μερισθέντες τοὺς φόρους συνέλεγον. ταχέως δὲ τὰ τεσσαράκοντα τάλαντα, τοσοῦτον γὰρ ἔλειπεν, ἠθροίσθη."},{"number":406,"text":"καὶ τοῦ μὲν πολέμου τότε οὕτω τὴν ἀπειλὴν κατεῖχεν Ἀγρίππας, αὖθις δὲ ἐπειρᾶτο πείθειν τὸ πλῆθος ὑπακούειν Φλώρῳ, μέχρις ἀντʼ αὐτοῦ πέμψει Καῖσαρ διάδοχον· πρὸς ὃ παροξυνθέντες ἐβλασφήμουν εἰς τὸν βασιλέα καὶ τῆς πόλεως αὐτὸν ἐξεκήρυσσον, ἐτόλμων δέ τινες τῶν στασιαστῶν καὶ λίθους ἐπʼ αὐτὸν βάλλειν."},{"number":407,"text":"ὁ δὲ βασιλεὺς ἰδὼν τὴν ὁρμὴν ἤδη τῶν νεωτεριζόντων ἀκατάσχετον καὶ χαλεπήνας ἐφʼ οἷς προπεπηλάκισται, τοὺς μὲν ἄρχοντας αὐτῶν ἅμα τοῖς δυνατοῖς ἔπεμπε πρὸς Φλῶρον εἰς Καισάρειαν, ἵνʼ ἐκεῖνος ἐξ αὐτῶν ἀποδείξῃ τοὺς τὴν χώραν φορολογήσοντας, αὐτὸς δὲ ἀνεχώρησεν εἰς τὴν βασιλείαν."},{"number":408,"text":"Κἀν τούτῳ τινὲς τῶν μάλιστα κινούντων τὸν πόλεμον συνελθόντες ὥρμησαν ἐπὶ φρούριόν τι καλούμενον Μασάδαν, καὶ καταλαβόντες αὐτὸ λάθρα τοὺς μὲν Ῥωμαίων φρουροὺς ἀπέσφαξαν, ἑτέρους δʼ ἐγκατέστησαν ἰδίους."},{"number":409,"text":"ἅμα δὲ καὶ κατὰ τὸ ἱερὸν Ἐλεάζαρος υἱὸς Ἀνανία τοῦ ἀρχιερέως, νεανίας θρασύτατος, στρατηγῶν τότε τοὺς κατὰ τὴν λατρείαν λειτουργοῦντας ἀναπείθει μηδενὸς ἀλλοτρίου δῶρον ἢ θυσίαν προσδέχεσθαι. τοῦτο δʼ ἦν τοῦ πρὸς Ῥωμαίους πολέμου καταβολή· τὴν γὰρ ὑπὲρ τούτων θυσίαν Καίσαρος ἀπέρριψαν."},{"number":410,"text":"καὶ πολλὰ τῶν τε ἀρχιερέων καὶ τῶν γνωρίμων παρακαλούντων μὴ παραλιπεῖν τὸ ὑπὲρ τῶν ἡγεμόνων ἔθος οὐκ ἐνέδοσαν, πολὺ μὲν καὶ τῷ σφετέρῳ πλήθει πεποιθότες, καὶ γὰρ τὸ ἀκμαιότατον τῶν νεωτεριζόντων συνήργει, μάλιστα δʼ ἀφορῶντες εἰς τὸν Ἐλεάζαρον στρατηγοῦντα."},{"number":411,"text":"Συνελθόντες γοῦν οἱ δυνατοὶ τοῖς ἀρχιερεῦσιν εἰς ταὐτὸ καὶ τοῖς τῶν Φαρισαίων γνωρίμοις ὡς ἐπʼ ἀνηκέστοις ἤδη συμφοραῖς ἐβουλεύοντο περὶ τῶν ὅλων· καὶ δόξαν ἀποπειραθῆναι τῶν στασιαστῶν λόγοις πρὸ τῆς χαλκῆς πύλης ἀθροίζουσι τὸν δῆμον, ἥτις ἦν τοῦ ἔνδον ἱεροῦ τετραμμένη πρὸς ἀνατολὰς ἡλίου."},{"number":412,"text":"καὶ πρῶτον αὐτῶν πολλὰ πρὸς τὴν τόλμαν τῆς ἀποστάσεως χαλεπήναντες καὶ τὸ τηλικοῦτον ἐπισείειν τῇ πατρίδι πόλεμον, ἔπειτα τὸ τῆς προφάσεως ἄλογον διήλεγχον, φάμενοι τοὺς μὲν προγόνους αὐτῶν κεκοσμηκέναι τὸν ναὸν ἐκ τῶν ἀλλοφύλων τὸ πλέον ἀεὶ προσδεχομένους τὰς ἀπὸ τῶν ἔξωθεν ἐθνῶν δωρεάς,"},{"number":413,"text":"καὶ οὐ μόνον οὐ διακεκωλυκέναι θυσίας τινῶν, τοῦτο μὲν γὰρ ἀσεβέστατον, ἀλλὰ καὶ τὰ βλεπόμενα καὶ τὰ παραμένοντα τοσοῦτον χρόνον ἀναθήματα περὶ τῷ ἱερῷ καθιδρυκέναι."},{"number":414,"text":"αὐτοὺς δὲ νῦν ἐρεθίζοντας τὰ Ῥωμαίων ὅπλα καὶ μνηστευομένους τὸν ἀπʼ ἐκείνων πόλεμον καινοτομεῖν θρησκείαν ξένην καὶ μετὰ τοῦ κινδύνου καταψηφίσασθαι τῆς πόλεως ἀσέβειαν, εἰ παρὰ μόνοις Ἰουδαίοις οὔτε θύσει τις ἀλλότριος οὔτε προσκυνήσει."},{"number":415,"text":"κἂν μὲν ἐπὶ ἰδιώτου τις ἑνὸς τοῦτον εἰσφέρῃ τὸν νόμον, ἀγανακτεῖν ὡς ὁριζομένης ἀπανθρωπίας, περιορᾶν δʼ ὅτε Ῥωμαῖοι καὶ ὁ Καῖσαρ ἔκσπονδος γίνεται."},{"number":416,"text":"δεδοικέναι μέντοι, μὴ τὰς ὑπὲρ ἐκείνων ἀπορρίψαντες θυσίας κωλυθῶσι θύειν καὶ τὰς ὑπὲρ ἑαυτῶν γένηταί τε ἔκσπονδος τῆς ἡγεμονίας ἡ πόλις, εἰ μὴ ταχέως σωφρονήσαντες ἀποδώσουσιν τὰς θυσίας καὶ πρὶν ἐξελθεῖν ἐφʼ οὓς ὑβρίκασιν τὴν φήμην διορθώσονται τὴν ὕβριν."},{"number":417,"text":"Ἅμα ταῦτα λέγοντες παρῆγον τοὺς ἐμπείρους τῶν πατρίων ἱερεῖς ἀφηγουμένους, ὅτι πάντες οἱ πρόγονοι τὰς παρὰ τῶν ἀλλογενῶν θυσίας ἀπεδέχοντο. προσεῖχεν δὲ οὐδεὶς τῶν νεωτεριζόντων, ἀλλʼ οὐδὲ προσίεσαν οἱ λῃστρικοὶ καὶ τὴν τοῦ πολέμου καταβολὴν ἐνσκευαζόμενοι."},{"number":418,"text":"συνιδόντες οὖν οἱ δυνατοὶ τήν τε στάσιν ἤδη δυσκαθαίρετον ὑπʼ αὐτῶν οὖσαν καὶ τὸν ἀπὸ Ῥωμαίων κίνδυνον ἐπὶ πρώτους αὐτοὺς ἀφιξόμενον ἀπεσκευάζοντο τὰς αἰτίας, καὶ πρέσβεις οὓς μὲν πρὸς Φλῶρον ἔπεμπον, ὧν ἦρχεν υἱὸς Ἀνανίου Σίμων, οὓς δὲ πρὸς Ἀγρίππαν, ἐν οἷς ἦσαν ἐπίσημοι Σαῦλός τε καὶ Ἀντίπας καὶ Κοστόβαρος προσήκοντες τῷ βασιλεῖ κατὰ γένος."},{"number":419,"text":"ἐδέοντο δὲ ἀμφοτέρων ἀναβῆναι μετὰ δυνάμεως εἰς τὴν πόλιν καὶ πρὶν γενέσθαι δυσκαθαίρετον ἐπικόψαι τὴν στάσιν."},{"number":420,"text":"Φλώρῳ μὲν οὖν δεινὸν εὐαγγέλιον ἦν, καὶ προῃρημένος ἐξάπτειν τὸν πόλεμον οὐδὲν ἀπεκρίνατο τοῖς πρεσβευταῖς·"},{"number":421,"text":"Ἀγρίππας δὲ κηδόμενος ἐπίσης τῶν τε ἀφισταμένων καὶ πρὸς οὓς ὁ πόλεμος ἠγείρετο, βουλόμενός τε Ῥωμαίοις μὲν Ἰουδαίους σώζεσθαι, Ἰουδαίοις δὲ τὸ ἱερὸν καὶ τὴν μητρόπολιν, ἀλλʼ οὐδʼ ἑαυτῷ λυσιτελήσειν τὴν ταραχὴν ἐπιστάμενος, ἔπεμπεν τοὺς ἐπαμυνοῦντας τῷ δήμῳ δισχιλίους ἱππεῖς, Αὐρανίτας τε καὶ Βαταναίους καὶ Τραχωνίτας, ὑπὸ Δαρείῳ μὲν ἱππάρχῃ, στρατηγῷ δὲ τῷ Ἰακίμου Φιλίππῳ."},{"number":422,"text":"Τούτοις θαρσήσαντες οἱ δυνατοὶ σὺν τοῖς ἀρχιερεῦσιν καὶ πᾶν ὅσον τοῦ πλήθους εἰρήνην ἠγάπα τὴν ἄνω καταλαμβάνονται πόλιν· τῆς κάτω γὰρ τὸ στασιάζον ἐκράτει καὶ τοῦ ἱεροῦ."},{"number":423,"text":"χερμάσιν μὲν οὖν καὶ τοῖς ἑκηβόλοις ἀδιαλείπτως ἐχρῶντο, καὶ συνεχεῖς ἦσαν βελῶν ἀφέσεις ἐξ ἑκατέρων τῶν κλιμάτων· ἔστιν δʼ ὅτε καὶ κατὰ λόχους ἐκτρέχοντες συστάδην ἐμάχοντο, τόλμαις μὲν οἱ στασιασταὶ προέχοντες, ἐμπειρίᾳ δὲ οἱ βασιλικοί."},{"number":424,"text":"καὶ τούτοις μὲν ἦν ἀγὼν τοῦ ἱεροῦ κρατῆσαι μάλιστα καὶ τοὺς μιαίνοντας τὸν ναὸν ἐξελάσαι, τοῖς δὲ περὶ τὸν Ἐλεάζαρον στασιασταῖς πρὸς οἷς ἔσχον καὶ τὴν ἄνω πόλιν προσλαβεῖν. ἑπτὰ μὲν οὖν ἡμέραις συχνὸς ἀμφοτέρων φόνος ἐγίνετο, καὶ οὐδέτεροι τοῦ καταληφθέντος μέρους εἶκον."},{"number":425,"text":"Τῇ δʼ ἑξῆς τῆς τῶν ξυλοφορίων ἑορτῆς οὔσης, ἐν ᾗ πᾶσιν ἔθος ἦν ὕλην τῷ βωμῷ προσφέρειν, ὅπως μήποτε τροφὴ τῷ πυρὶ λείποι, διαμένει γὰρ ἄσβεστον ἀεί, τοὺς μὲν διαφόρους τῆς θρησκείας ἐξέκλεισαν, τῷ δʼ ἀσθενεῖ λαῷ συνεισρυέντας πολλοὺς τῶν σικαρίων, οὕτως γὰρ ἐκάλουν τοὺς λῃστὰς ἔχοντας ὑπὸ τοῖς κόλποις ξίφη, προσλαβόντες θαρραλεώτερον ἥπτοντο τῆς ἐπιχειρήσεως."},{"number":426,"text":"ἡττῶντο δʼ οἱ βασιλικοὶ πλήθει τε καὶ τόλμῃ, καὶ βιασαμένοις εἶκον ἐκ τῆς ἄνω πόλεως. οἱ δὲ ἐπιπεσόντες τήν τε Ἀνανίου τοῦ ἀρχιερέως οἰκίαν καὶ τὰ Ἀγρίππα καὶ Βερνίκης ὑποπιμπρᾶσιν βασίλεια·"},{"number":427,"text":"μεθʼ ἃ τὸ πῦρ ἐπὶ τὰ ἀρχεῖα ἔφερον ἀφανίσαι σπεύδοντες τὰ συμβόλαια τῶν δεδανεικότων καὶ τὰς εἰσπράξεις ἀποκόψαι τῶν χρεῶν, ὅπως αὐτοί τε πλῆθος προσλάβωσιν τῶν ὠφεληθέντων καὶ μετʼ ἀδείας τοῖς εὐπόροις ἐπαναστήσωσι τοὺς ἀπόρους. φυγόντων δὲ τῶν πρὸς τῷ γραμματοφυλακείῳ τὸ πῦρ ἐνίεσαν."},{"number":428,"text":"ἐπεὶ δὲ τὰ νεῦρα τῆς πόλεως καταφλέξαντες ἐπὶ τοὺς ἐχθροὺς ἐχώρουν, ἔνθα δὴ τῶν δυνατῶν καὶ τῶν ἀρχιερέων οἱ μὲν εἰς τοὺς ὑπονόμους καταδύντες διελάνθανον,"},{"number":429,"text":"οἱ δὲ σὺν τοῖς βασιλικοῖς εἰς τὴν ἀνωτέρω καταφυγόντες αὐλὴν ταχέως ἀπέκλεισαν τὰς θύρας, σὺν οἷς Ἀνανίας ὁ ἀρχιερεὺς Ἐζεκίας τε ὁ ἀδελφὸς αὐτοῦ καὶ οἱ πρεσβεύσαντες πρὸς Ἀγρίππαν ἦσαν. τότε μὲν οὖν τῇ νίκῃ καὶ τοῖς ἐμπρησθεῖσιν ἀρκεσθέντες ἀνεπαύσαντο."},{"number":430,"text":"Τῇ δʼ ἑξῆς, πεντεκαιδεκάτη δʼ ἦν Λώου μηνός, ὥρμησαν ἐπὶ τὴν Ἀντωνίαν καὶ τοὺς ἐν αὐτῇ φρουροὺς δυσὶν ἡμέραις πολιορκήσαντες αὐτούς τε εἷλον καὶ κατέσφαξαν καὶ τὸ φρούριον ἐνέπρησαν."},{"number":431,"text":"ἔπειτα μετέβαινον εἰς τὴν αὐλήν, εἰς ἣν οἱ βασιλικοὶ κατέφυγον, καὶ διανείμαντες σφᾶς αὐτοὺς εἰς τέσσαρα μέρη τῶν τειχῶν ἐπειρῶντο. τῶν δʼ ἔνδον πρὸς ἐκδρομὴν μὲν οὐδεὶς ἐθάρρει διὰ τὸ πλῆθος τῶν ἐφεστώτων, διιστάμενοι δὲ ἐπὶ τὰ θωράκια καὶ τοὺς πύργους ἔβαλλον τοὺς προσιόντας, καὶ συχνοὶ τῶν λῃστῶν ὑπὸ τοῖς τείχεσιν ἔπιπτον."},{"number":432,"text":"οὔτε δὲ νυκτὸς οὔτε ἡμέρας διέλειπεν ἡ συμβολὴ τῶν μὲν στασιαστῶν ἀπαγορεύσειν τοὺς ἔνδον οἰομένων ἐνδείᾳ τροφῆς, τῶν δʼ ἔνδοθεν καμάτῳ τοὺς πολιορκοῦντας."},{"number":433,"text":"Κἀν τούτῳ Μανάημός τις, υἱὸς Ἰούδα τοῦ καλουμένου Γαλιλαίου, σοφιστὴς δεινότατος, ὁ καὶ ἐπὶ Κυρινίου ποτὲ Ἰουδαίους ὀνειδίσας ὅτι Ῥωμαίοις ὑπετάσσοντο μετὰ τὸν θεόν, ἀναλαβὼν τοὺς γνωρίμους ἀνεχώρησεν εἰς Μασάδαν,"},{"number":434,"text":"ἔνθα τὴν Ἡρώδου τοῦ βασιλέως ὁπλοθήκην ἀναρρήξας καὶ πρὸς τοῖς δημόταις ἑτέρους λῃστὰς καθοπλίσας τούτοις τε χρώμενος δορυφόροις, οἷα δὴ βασιλεὺς ἐπάνεισιν εἰς Ἱεροσόλυμα καὶ γενόμενος ἡγεμὼν τῆς στάσεως διέτασσεν τὴν πολιορκίαν."},{"number":435,"text":"ἀπορία δʼ ἦν ὀργάνων, καὶ φανερῶς ὑπορύττειν τὸ τεῖχος οὐχ οἷόν τε ἦν ἄνωθεν βαλλομένους· ὑπόνομον δὴ πόρρωθεν ἐφʼ ἕνα τῶν πύργων ὑπορύξαντες ἀνεκρήμνισαν αὐτόν, ἔπειτα τὴν ἀνέχουσαν ὕλην ἐμπρήσαντες ἐξῆλθον."},{"number":436,"text":"ὑποκαέντων δὲ τῶν στηριγμάτων ὁ μὲν πύργος ἐξαίφνης κατασείεται, τεῖχος δʼ ἕτερον ἔνδοθεν ἀνῳκοδομημένον διεφάνη· τὴν γὰρ ἐπιβουλὴν αὐτῶν προαισθόμενοι, τάχα καὶ τοῦ πύργου κινηθέντος ὡς ὑπωρύττετο, δεύτερον ἑαυτοῖς ἔρυμα κατεσκεύασαν."},{"number":437,"text":"πρὸς ὃ τῶν ἀδοκήτως ἰδόντων καὶ κρατεῖν ἤδη πεπεισμένων κατάπληξις ἦν. οἱ δὲ ἔνδοθεν πρός τε τὸν Μανάημον καὶ τοὺς ἐξάρχοντας τῆς στάσεως ἔπεμπον ἀξιοῦντες ἐξελθεῖν ὑπόσπονδοι, καὶ δοθὲν μόνοις τοῖς βασιλικοῖς καὶ τοῖς ἐπιχωρίοις οἱ μὲν ἐξῄεσαν."},{"number":438,"text":"ἀθυμία δὲ τοὺς Ῥωμαίους καταλειφθέντας μόνους ὑπέλαβεν· οὔτε γὰρ βιάσασθαι τοσοῦτον πλῆθος ἐδύναντο καὶ τὸ δεξιὰς αἰτεῖν ὄνειδος ὑπελάμβανον, πρὸς τῷ μηδὲ πιστεύειν εἰ διδοῖτο."},{"number":439,"text":"καταλιπόντες δὴ τὸ στρατόπεδον ὡς εὐάλωτον ἐπὶ τοὺς βασιλικοὺς ἀνέφυγον πύργους, τόν τε Ἱππικὸν καλούμενον καὶ Φασάηλον καὶ Μαριάμμην."},{"number":440,"text":"οἱ δὲ περὶ τὸν Μανάημον εἰσπεσόντες ὅθεν οἱ στρατιῶται διέφυγον ὅσους τε αὐτῶν κατελάμβανον μὴ φθάσαντας ἐκδραμεῖν διέφθειραν, καὶ τὰς ἀποσκευὰς διαρπάσαντες ἐνέπρησαν τὸ στρατόπεδον. ταῦτα μὲν οὖν ἕκτῃ Γορπιαίου μηνὸς ἐπράχθη."},{"number":441,"text":"Κατὰ δὲ τὴν ἐπιοῦσαν ὅ τε ἀρχιερεὺς Ἀνανίας περὶ τὸν τῆς βασιλικῆς αὐλῆς εὔριπον διαλανθάνων ἁλίσκεται καὶ πρὸς τῶν λῃστῶν ἀναιρεῖται σὺν Ἐζεκίᾳ τῷ ἀδελφῷ, καὶ τοὺς πύργους περισχόντες οἱ στασιασταὶ παρεφύλαττον, μή τις τῶν στρατιωτῶν διαφύγοι."},{"number":442,"text":"τὸν δὲ Μανάημον ἥ τε τῶν ὀχυρῶν καταστροφὴ χωρίων καὶ ὁ τοῦ ἀρχιερέως Ἀνανίου θάνατος ἐτύφωσεν εἰς ὠμότητα καὶ μηδένα νομίζων ἔχειν ἐπὶ τοῖς πράγμασιν ἀντίπαλον ἀφόρητος ἦν τύραννος."},{"number":443,"text":"ἐπανίστανται δὲ οἱ περὶ τὸν Ἐλεάζαρον αὐτῷ, καὶ λόγον ἀλλήλοις δόντες, ὡς οὐ χρὴ Ῥωμαίων ἀποστάντας διʼ ἐλευθερίας πόθον καταπροέσθαι ταύτην οἰκείῳ δήμῳ καὶ δεσπότην φέρειν, εἰ καὶ μηδὲν πράττοι βίαιον, ἀλλʼ οὖν ἑαυτῶν ταπεινότερον· εἰ γὰρ καὶ δέοι τινὰ τῶν ὅλων ἀφηγεῖσθαι, παντὶ μᾶλλον ἢ ἐκείνῳ προσήκειν, συντίθενται καὶ κατὰ τὸ ἱερὸν ἐπεχείρουν αὐτῷ·"},{"number":444,"text":"σοβαρὸς γὰρ ἀναβεβήκει προσκυνήσων ἐσθῆτί τε βασιλικῇ κεκοσμημένος καὶ τοὺς ζηλωτὰς ἐνόπλους ἐφελκόμενος."},{"number":445,"text":"ὡς δʼ οἱ περὶ τὸν Ἐλεάζαρον ἐπʼ αὐτὸν ὥρμησαν, ὅ τε λοιπὸς δῆμος ἐπὶ τὰς ὀργὰς λίθους ἁρπάσαντες τὸν σοφιστὴν ἔβαλλον, οἰόμενοι τούτου καταλυθέντος διατρέψειν ὅλην τὴν στάσιν,"},{"number":446,"text":"πρὸς ὀλίγον οἱ περὶ τὸν Μανάημον ἀντισχόντες ὡς εἶδον πᾶν ἐπʼ αὐτοὺς τὸ πλῆθος ὁρμῆσαν, ἔφυγον ὅπη τις ἴσχυσεν, καὶ φόνος μὲν ἦν τῶν καταληφθέντων, ἔρευνα δὲ τῶν ἀποκρυπτομένων."},{"number":447,"text":"καὶ διεσώθησαν ὀλίγοι λάθρα διαδράντες εἰς Μασάδαν, σὺν οἷς Ἐλεάζαρος υἱὸς Ἰαείρου, προσήκων τῷ Μαναήμῳ κατὰ γένος, ὃς ὕστερον ἐτυράννησεν τῆς Μασάδας."},{"number":448,"text":"αὐτόν τε τὸν Μανάημον εἰς τὸν καλούμενον Ὀφλᾶν συμφυγόντα κἀκεῖ ταπεινῶς ὑπολανθάνοντα ζωγρήσαντες εἰς τὸ φανερὸν ἐξείλκυσαν καὶ πολλαῖς αἰκισάμενοι βασάνοις ἀνεῖλον, ὁμοίως δὲ καὶ τοὺς ὑπʼ αὐτὸν ἡγεμόνας τόν τε ἐπισημότατον τῆς τυραννίδος ὑπηρέτην Ἀψάλωμον."},{"number":449,"text":"Ὁ μὲν οὖν δῆμος, ὡς ἔφην, εἰς ταῦτα συνήργησεν ἐλπίζων τινὰ τῆς ὅλης στάσεως διόρθωσιν· οἱ δʼ οὐ καταλῦσαι τὸν πόλεμον σπεύδοντες, ἀλλʼ ἀδεέστερον πολεμεῖν Μανάημον ἀνῃρήκεσαν."},{"number":450,"text":"ἀμέλει πολλὰ τοῦ δήμου τοῖς στρατιώταις ἀνεῖναι τὴν πολιορκίαν παρακαλοῦντος, οἱ δὲ προσέκειντο χαλεπώτερον, μέχρι μηκέτι ἀντέχοντες οἱ περὶ τὸν Μετίλιον, οὗτος γὰρ ἦν τῶν Ῥωμαίων ἔπαρχος, διαπέμπονται πρὸς τοὺς περὶ τὸν Ἐλεάζαρον ἐξαιτούμενοι μόνας τὰς ψυχὰς ὑποσπόνδους, τὰ δʼ ὅπλα καὶ τὴν λοιπὴν κτῆσιν παραδώσειν λέγοντες."},{"number":451,"text":"οἱ δὲ καὶ τὴν ἱκεσίαν ἁρπάσαντες ἀνέπεμψαν πρὸς αὐτοὺς Γωρίονά τε Νικομήδους υἱὸν καὶ Ἀνανίαν Σαδούκι καὶ Ἰούδαν Ἰωνάθου δεξιάν τε καὶ ὅρκους δώσοντας. ὧν γενομένων κατῆγεν τοὺς στρατιώτας ὁ Μετίλιος."},{"number":452,"text":"οἱ δὲ μέχρι μὲν ἦσαν ἐν τοῖς ὅπλοις, οὔτʼ ἐπεχείρει τις τῶν στασιαστῶν αὐτοῖς οὔτʼ ἐνέφαινεν ἐπιβουλήν· ὡς δὲ κατὰ τὰς συνθήκας ἅπαντες ἀπέθεντο τοὺς θυρεοὺς καὶ τὰ ξίφη καὶ μηδὲν ἔτι ὑποπτεύοντες ἀνεχώρουν,"},{"number":453,"text":"ὥρμησαν ἐπʼ αὐτοὺς οἱ περὶ τὸν Ἐλεάζαρον καὶ περισχόντες ἀνῄρουν οὔτε ἀμυνομένους οὔτε ἱκετεύοντας, μόνας δὲ τὰς συνθήκας καὶ τοὺς ὅρκους ἀναβοῶντας."},{"number":454,"text":"οἱ μὲν οὖν οὕτως ὠμῶς ἀπεσφάγησαν ἅπαντες πλὴν Μετιλίου, τοῦτον γὰρ ἱκετεύσαντα καὶ μέχρι περιτομῆς ἰουδαΐσειν ὑποσχόμενον διέσωσαν μόνον, τὸ δὲ πάθος Ῥωμαίοις μὲν ἦν κοῦφον, ἐκ γὰρ ἀπλέτου δυνάμεως ἀπαναλώθησαν ὀλίγοι, Ἰουδαίων δὲ προοίμιον ἁλώσεως ἔδοξεν."},{"number":455,"text":"καὶ κατιδόντες ἀνηκέστους μὲν ἤδη τὰς αἰτίας τοῦ πολέμου, τὴν δὲ πόλιν τηλικούτῳ μιάσματι πεφυρμένην, ἐξ οὗ δαιμόνιόν τι μήνιμα προσδοκᾶν εἰκὸς ἦν, εἰ καὶ μὴ τὴν ἐκ Ῥωμαίων ἄμυναν, ἐπένθουν δημοσίᾳ, καὶ πλήρης μὲν κατηφείας ἦν ἡ πόλις, ἕκαστος δὲ τῶν μετρίων ὡς αὐτὸς ὑπὲρ τῶν στασιαστῶν δίκας δώσων τετάρακτο."},{"number":456,"text":"καὶ γὰρ δὴ σαββάτῳ συνέβη πραχθῆναι τὸν φόνον, ἐν ᾧ διὰ τὴν θρησκείαν καὶ τῶν ὁσίων ἔργων ἔχουσιν ἐκεχειρίαν."}],"18":[{"number":457,"text":"Τῆς δʼ αὐτῆς ἡμέρας καὶ ὥρας ὥσπερ ἐκ δαιμονίου προνοίας ἀνῄρουν Καισαρεῖς τοὺς παρʼ ἑαυτοῖς Ἰουδαίους, ὡς ὑπὸ μίαν ὥραν ἀποσφαγῆναι μὲν ὑπὲρ δισμυρίους, κενωθῆναι δὲ πᾶσαν Ἰουδαίων τὴν Καισάρειαν· καὶ γὰρ τοὺς διαφεύγοντας ὁ Φλῶρος συλλαβὼν κατῆγεν δεσμώτας εἰς τὰ νεώρια."},{"number":458,"text":"πρὸς δὲ τὴν ἐκ τῆς Καισαρείας πληγὴν ὅλον τὸ ἔθνος ἐξαγριοῦται, καὶ διαμερισθέντες τάς τε κώμας τῶν Σύρων καὶ τὰς προσεχούσας ἐπόρθουν πόλεις, Φιλαδέλφειάν τε καὶ Ἐσεβωνῖτιν καὶ Γέρασα καὶ Πέλλαν καὶ Σκυθόπολιν."},{"number":459,"text":"ἔπειτα Γαδάροις καὶ Ἵππῳ καὶ τῇ Γαυλανίτιδι προσπεσόντες τὰ μὲν καταστρεψάμενοι, τὰ δʼ ὑποπρήσαντες ἐχώρουν ἐπὶ Κάδασα τὴν Τυρίων καὶ Πτολεμαΐδα Γάβαν τε καὶ Καισάρειαν."},{"number":460,"text":"ἀντέσχον δὲ οὔτε Σεβαστὴ ταῖς ὁρμαῖς αὐτῶν οὔτε Ἀσκάλων, ἀλλʼ ἐπὶ ταύταις πυρποληθείσαις Ἀνθηδόνα καὶ Γάζαν κατέσκαπτον. πολλαὶ δὲ καθʼ ἑκάστην τούτων τῶν πόλεων ἀνηρπάζοντο κῶμαι, καὶ τῶν ἁλισκομένων ἀνδρῶν φόνος ἦν ἄπειρος."},{"number":461,"text":"Οὐ μὴν οἱ Σύροι τῶν Ἰουδαίων ἔλαττον πλῆθος ἀνῄρουν, ἀλλὰ καὶ αὐτοὶ τοὺς ἐν ταῖς πόλεσιν λαμβανομένους ἀπέσφαττον οὐ μόνον κατὰ μῖσος, ὡς πρότερον, ἀλλʼ ἤδη καὶ τὸν ἐφʼ ἑαυτοῖς κίνδυνον φθάνοντες."},{"number":462,"text":"δεινὴ δὲ ὅλην τὴν Συρίαν ἐπεῖχεν ταραχή, καὶ πᾶσα πόλις εἰς δύο διῄρητο στρατόπεδα, σωτηρία δὲ τοῖς ἑτέροις ἦν τὸ τοὺς ἑτέρους φθάσαι."},{"number":463,"text":"καὶ τὰς μὲν ἡμέρας ἐν αἵματι διῆγον, τὰς δὲ νύκτας δέει χαλεπωτέρας· καὶ γὰρ ἀπεσκευάσθαι τοὺς Ἰουδαίους δοκοῦντες ἕκαστοι τοὺς ἰουδαΐζοντας εἶχον ἐν ὑποψίᾳ, καὶ τὸ παρʼ ἑκάστοις ἀμφίβολον οὔτε ἀνελεῖν τις προχείρως ὑπέμενεν καὶ μεμιγμένον ὡς βεβαίως ἀλλόφυλον ἐφοβεῖτο."},{"number":464,"text":"προεκαλεῖτο δὲ ἐπὶ τὰς σφαγὰς τῶν διαφόρων καὶ τοὺς πάλαι πρᾳοτάτους πάνυ δοκοῦντας ἡ πλεονεξία· τὰς γὰρ οὐσίας τῶν ἀναιρεθέντων ἀδεῶς διήρπαζον καὶ καθάπερ ἐκ παρατάξεως τὰ σκῦλα τῶν ἀνῃρημένων εἰς τοὺς σφετέρους οἴκους μετέφερον, ἔνδοξός τε ἦν ὁ πλεῖστα κερδάνας ὡς κατισχύσας πλειόνων."},{"number":465,"text":"ἦν δὲ ἰδεῖν τὰς πόλεις μεστὰς ἀτάφων σωμάτων καὶ νεκροὺς ἅμα νηπίοις γέροντας ἐρριμμένους γύναιά τε μηδὲ τῆς ἐπʼ αἰδοῖ σκέπης μετειληφότα, καὶ πᾶσαν μὲν τὴν ἐπαρχίαν μεστὴν ἀδιηγήτων συμφορῶν, μείζονα δὲ τῶν ἑκάστοτε τολμωμένων τὴν ἐπὶ τοῖς ἀπειλουμένοις ἀνάτασιν."},{"number":466,"text":"Μέχρι μὲν δὴ τούτων Ἰουδαίοις πρὸς τὸ ἀλλόφυλον ἦσαν προσβολαί, κατατρέχοντες δὲ εἰς Σκυθόπολιν τοὺς παρʼ ἐκείνοις Ἰουδαίους ἐπείρασαν πολεμίους· ταξάμενοι γὰρ μετὰ τῶν Σκυθοπολιτῶν καὶ τῆς ἑαυτῶν ἀσφαλείας ἐν δευτέρῳ θέμενοι τὴν συγγένειαν ὁμόσε τοῖς ὁμοφύλοις ἐχώρουν. ὑπωπτεύθη δʼ αὐτῶν καὶ τὸ λίαν πρόθυμον·"},{"number":467,"text":"οἱ γοῦν Σκυθοπολῖται δείσαντες μὴ νύκτωρ ἐπιχειρήσωσι τῇ πόλει καὶ μετὰ μεγάλης αὐτῶν συμφορᾶς τοῖς οἰκείοις ἀπολογήσωνται περὶ τῆς ἀποστάσεως, ἐκέλευον αὐτούς, εἰ βούλονται τὴν ὁμόνοιαν βεβαιῶσαι καὶ τὸ πρὸς τοὺς ἀλλοεθνεῖς πιστὸν ἐπιδείξασθαι, μεταβαίνειν ἅμα ταῖς γενεαῖς εἰς τὸ ἄλσος."},{"number":468,"text":"τῶν δὲ ποιησάντων τὸ προσταχθὲν χωρὶς ὑποψίας. δύο μὲν ἡμέρας ἠρέμησαν οἱ Σκυθοπολῖται τὴν πίστιν αὐτῶν δελεάζοντες, τῇ δὲ τρίτῃ νυκτὶ παρατηρήσαντες τοὺς μὲν ἀφυλάκτους οὓς δὲ κοιμωμένους ἅπαντας ἀπέσφαξαν ὄντας τὸν ἀριθμὸν ὑπὲρ μυρίους καὶ τρισχιλίους, τὰς δὲ κτήσεις διήρπασαν ἁπάντων."},{"number":469,"text":"Ἄξιον δʼ ἀφηγήσασθαι καὶ τὸ Σίμωνος πάθος, ὃς υἱὸς μὲν ἦν Σαούλου τινὸς τῶν οὐκ ἀσήμων, ῥώμῃ δὲ σώματος καὶ τόλμῃ διαφέρων ἐπὶ κακῷ τῶν ὁμοφύλων ἀμφοτέροις κατεχρήσατο·"},{"number":470,"text":"προϊὼν γοῦν ὁσημέραι πολλοὺς μὲν ἀνῄρει τῶν πρὸς τῇ Σκυθοπόλει Ἰουδαίων, τρεπόμενος δὲ πολλάκις αὐτοὺς ἅπαντας μόνος ἦν ῥοπὴ τῆς παρατάξεως."},{"number":471,"text":"περιέρχεται δʼ αὐτὸν ἀξία ποινὴ τοῦ συγγενικοῦ φόνου· ἐπεὶ γὰρ περισχόντες οἱ Σκυθοπολῖται κατηκόντιζον αὐτοὺς ἀνὰ τὸ ἄλσος, σπασάμενος τὸ ξίφος ἐπʼ οὐδένα μὲν ὥρμησεν τῶν πολεμίων, καὶ γὰρ ἑώρα τὸ πλῆθος ἀνήνυτον, ἀναβοήσας δὲ μάλα ἐκπαθῶς ἄξιά γε ὧν ἔδρασα πάσχω,"},{"number":472,"text":"Σκυθοπολῖται, καθʼ ὑμῶν, οἳ τοσούτῳ φόνῳ συγγενῶν τὴν πρὸς αὐτοὺς εὔνοιαν ἐπιστωσάμεθα. τοιγαροῦν οἷς ἄπιστον μὲν εὐλόγως εὕρηται τὸ ἀλλόφυλον, ἠσέβηται δὲ [εἰς ἔσχατα] τὸ οἰκεῖον, θνήσκωμεν ὡς ἐναγεῖς χερσὶν ἰδίαις· οὐ γὰρ πρέπον ἐν ταῖς τῶν πολεμίων."},{"number":473,"text":"τὸ αὐτὸ δʼ ἂν εἴη μοι καὶ ποινὴ τοῦ μιάσματος ἀξία καὶ πρὸς ἀνδρείαν ἔπαινος, ἵνα μηδεὶς τῶν ἐχθρῶν τὴν ἐμὴν αὐχήσῃ σφαγὴν μηδʼ ἐπαλαζονεύσηται πεσόντι."},{"number":474,"text":"ταῦτα εἰπὼν ἐλεοῦσιν ἅμα καὶ τεθυμωμένοις ὄμμασιν περισκέπτεται τὴν ἑαυτοῦ γενεάν· ἦν δʼ αὐτῷ καὶ γυνὴ καὶ τέκνα καὶ γηραιοὶ γονεῖς."},{"number":475,"text":"ὁ δὲ πρῶτον μὲν τὸν πατέρα τῆς πολιᾶς ἐπισπασάμενος διελαύνει τῷ ξίφει, μεθʼ ὃν οὐκ ἄκουσαν τὴν μητέρα κἀπὶ τούτοις τήν τε γυναῖκα καὶ τὰ τέκνα, μόνον οὐχ ὑπαπαντῶντος ἑκάστου τῷ ξίφει καὶ σπεύδοντος φθάσαι τοὺς πολεμίους."},{"number":476,"text":"ὁ δὲ διελθὼν πᾶσαν τὴν γενεὰν καὶ περίοπτος ἐπιστὰς τοῖς σώμασιν τήν τε δεξιὰν ἀνατείνας, ὡς μηδένα λαθεῖν, ὅλον εἰς τὴν ἑαυτοῦ σφαγὴν ἐβάπτισεν τὸ ξίφος, ἄξιος μὲν ἐλέους νεανίας διʼ ἀλκὴν σώματος καὶ ψυχῆς παράστημα, τῆς δὲ πρὸς ἀλλοφύλους πίστεως ἕνεκεν ἀκολούθοις πάθεσι χρησάμενος."},{"number":477,"text":"Πρὸς δὲ τὴν ἐν Σκυθοπόλει φθορὰν αἱ λοιπαὶ πόλεις ἐπανίσταντο τοῖς καθʼ ἑαυτὴν Ἰουδαίοις ἑκάστη, καὶ πεντακοσίους μὲν ἐπὶ δισχιλίοις Ἀσκαλωνῖται, Πτολεμαεῖς δὲ δισχιλίους ἀνεῖλον ἔδησάν τʼ οὐκ ὀλίγους."},{"number":478,"text":"καὶ Τύριοι συχνοὺς μὲν διεχειρίσαντο, πλείστους δʼ αὐτῶν δεσμώτας ἐφρούρουν, Ἱππηνοί τε καὶ Γαδαρεῖς ὁμοίως τοὺς μὲν θρασυτέρους ἀπεσκευάσαντο, τοὺς δὲ φοβεροὺς διὰ φυλακῆς εἶχον, αἵ τε λοιπαὶ πόλεις τῆς Συρίας, ὅπως ἑκάστη πρὸς τὸ Ἰουδαϊκὸν ἢ μίσους ἢ δέους εἶχον."},{"number":479,"text":"μόνοι δὲ Ἀντιοχεῖς καὶ Σιδώνιοι καὶ Ἀπαμεῖς ἐφείσαντο τῶν μετοικούντων καὶ οὔτε ἀνελεῖν τινας Ἰουδαίων ὑπέμειναν οὔτε δῆσαι, τάχα μὲν καὶ διὰ τὸ σφέτερον πλῆθος ὑπερορῶντες αὐτῶν πρὸς τὰ κινήματα, τὸ πλέον δὲ ἔμοιγε δοκεῖν οἴκτῳ πρὸς οὓς οὐδὲν ἑώρων νεωτερίζοντας."},{"number":480,"text":"Γερασηνοί τε οὔτε εἰς τοὺς ἐμμείναντας ἐπλημμέλησαν καὶ τοὺς ἐξελθεῖν ἐθελήσαντας προέπεμψαν μέχρι τῶν ὅρων."},{"number":481,"text":"Συνέστη δὲ καὶ κατὰ τὴν Ἀγρίππα βασιλείαν ἐπιβουλὴ κατὰ Ἰουδαίων. αὐτὸς γὰρ ἐπεπόρευτο πρὸς Κέστιον Γάλλον εἰς Ἀντιόχειαν, καταλέλειπτο δὲ διοικεῖν τὰ πράγματα τούτου τῶν ἑταίρων τις τοὔνομα Νόαρος, Σοαίμῳ τῷ βασιλεῖ προσήκων κατὰ γένος."},{"number":482,"text":"ἧκον δʼ ἐκ τῆς Βαταναίας ἑβδομήκοντα τὸν ἀριθμὸν ἄνδρες οἱ κατὰ γένος καὶ σύνεσιν τῶν πολιτῶν δοκιμώτατοι στρατιὰν αἰτοῦντες, ἵνʼ εἴ τι γένοιτο κίνημα καὶ περὶ σφᾶς, ἔχοιεν ἀξιόχρεω φυλακὴν κωλύειν τοὺς ἐπανισταμένους."},{"number":483,"text":"τούτους ὁ Νόαρος ἐκπέμψας νύκτωρ τῶν βασιλικῶν τινας ὁπλιτῶν ἅπαντας ἀναιρεῖ, τολμήσας μὲν τοὖργον δίχα τῆς Ἀγρίππα γνώμης, διὰ δὲ φιλαργυρίαν ἄμετρον εἰς τοὺς ὁμοφύλους ἑλόμενος ἀσεβεῖν τὴν βασιλείαν διέφθειρεν· διετέλει τε ὠμῶς εἰς τὸ ἔθνος παρανομῶν, μέχρι πυθόμενος Ἀγρίππας ἀνελεῖν μὲν αὐτὸν ᾐδέσθη διὰ Σόαιμον, ἔπαυσεν δὲ τῆς ἐπιτροπῆς."},{"number":484,"text":"οἱ δὲ στασιασταὶ καταλαβόμενοί τι φρούριον, ὃ καλεῖται μὲν Κύπρος, καθύπερθεν δʼ ἦν Ἱεριχοῦντος, τοὺς μὲν φρουροὺς ἀπέσφαξαν, τὰ δʼ ἐρύματα κατέρριψαν εἰς γῆν."},{"number":485,"text":"κατὰ δὲ τὰς αὐτὰς ἡμέρας καὶ τῶν ἐν Μαχαιροῦντι Ἰουδαίων τὸ πλῆθος ἔπειθεν τοὺς φρουροῦντας Ῥωμαίους ἐκλείπειν τὸ φρούριον καὶ παραδιδόναι σφίσιν."},{"number":486,"text":"οἱ δὲ τὴν ἐκ βίας ἀφαίρεσιν εὐλαβηθέντες συντίθενται πρὸς αὐτοὺς ἐκχωρήσειν ὑπόσπονδοι, καὶ λαβόντες τὰ πιστὰ παραδιδόασι τὸ φρούριον, ὅπερ φυλακῇ κρατυνάμενοι κατεῖχον οἱ Μαχαιρῖται."},{"number":487,"text":"Κατὰ δὲ τὴν Ἀλεξάνδρειαν ἀεὶ μὲν ἦν στάσις πρὸς τὸ Ἰουδαϊκὸν τοῖς ἐπιχωρίοις ἀφʼ οὗ χρησάμενος προθυμοτάτοις κατὰ τῶν Αἰγυπτίων Ἰουδαίοις Ἀλέξανδρος γέρας τῆς συμμαχίας ἔδωκεν τὸ μετοικεῖν κατὰ τὴν πόλιν ἐξ ἴσου † μοίρας πρὸς τοὺς Ἕλληνας."},{"number":488,"text":"διέμεινεν δʼ αὐτοῖς ἡ τιμὴ καὶ παρὰ τῶν διαδόχων, οἳ καὶ τόπον ἴδιον αὐτοῖς ἀφώρισαν, ὅπως καθαρωτέραν ἔχοιεν τὴν δίαιταν ἧττον ἐπιμισγομένων τῶν ἀλλοφύλων, καὶ χρηματίζειν ἐπέτρεψαν Μακεδόνας, ἐπεί τε Ῥωμαῖοι κατεκτήσαντο τὴν Αἴγυπτον, οὔτε Καῖσαρ ὁ πρῶτος οὔτε τῶν μετʼ αὐτόν τις ὑπέμεινεν τὰς ἀπʼ Ἀλεξάνδρου τιμὰς Ἰουδαίων ἐλαττῶσαι."},{"number":489,"text":"συμβολαὶ δʼ ἦσαν αὐτῶν ἀδιάλειπτοι πρὸς τοὺς Ἕλληνας, καὶ τῶν ἡγεμόνων πολλοὺς ὁσημέραι παρʼ ἀμφοῖν κολαζόντων ἡ στάσις μᾶλλον παρωξύνετο."},{"number":490,"text":"τότε δʼ ὡς καὶ παρὰ τοῖς ἄλλοις ἐτετάρακτο, μᾶλλον ἐξήφθη τὰ παρʼ ἐκείνοις. καὶ δὴ τῶν Ἀλεξανδρέων ἐκκλησιαζόντων περὶ ἧς ἔμελλον ἐκπέμπειν πρεσβείας ἐπὶ Νέρωνα συνερρύησαν μὲν εἰς τὸ ἀμφιθέατρον ἅμα τοῖς Ἕλλησιν συχνοὶ Ἰουδαίων,"},{"number":491,"text":"κατιδόντες δὲ αὐτοὺς οἱ διάφοροι παραχρῆμα ἀνεβόων πολεμίους καὶ κατασκόπους λέγοντες· ἔπειτα ἀναπηδήσαντες ἐπέβαλλον τὰς χεῖρας αὐτοῖς. οἱ μὲν οὖν λοιποὶ φεύγοντες διεσπάρησαν, τρεῖς δὲ ἄνδρας συλλαβόντες ἔσυρον ὡς ζῶντας καταφλέξοντες."},{"number":492,"text":"ἤρθη δὲ πᾶν τὸ Ἰουδαϊκὸν ἐπὶ τὴν ἄμυναν, καὶ τὸ μὲν πρῶτον λίθοις τοὺς Ἕλληνας ἔβαλλον, αὖθις δὲ λαμπάδας ἁρπασάμενοι πρὸς τὸ ἀμφιθέατρον ὥρμησαν ἀπειλοῦντες ἐν αὐτῷ καταφλέξειν τὸν δῆμον αὔτανδρον. κἂν ἔφθησαν τοῦτο δράσαντες, εἰ μὴ τοὺς θυμοὺς αὐτῶν ἀνέκοψεν Τιβέριος Ἀλέξανδρος ὁ τῆς πόλεως ἡγεμών."},{"number":493,"text":"οὐ μὴν οὗτός γε ἀπὸ τῶν ὅπλων ἤρξατο σωφρονίζειν, ἀλλʼ ὑποπέμψας τοὺς γνωρίμους αὐτοῖς παύσασθαι παρεκάλει καὶ μὴ καθʼ ἑαυτῶν ἐρεθίζειν τὸ Ῥωμαίων στράτευμα. καταχλευάζοντες δὲ τῆς παρακλήσεως οἱ στασιώδεις ἐβλασφήμουν τὸν Τιβέριον."},{"number":494,"text":"Κἀκεῖνος συνιδὼν ὡς χωρὶς μεγάλης συμφορᾶς οὐκ ἂν παύσαιντο νεωτερίζοντες, ἐπαφίησιν αὐτοῖς τὰ κατὰ τὴν πόλιν Ῥωμαίων δύο τάγματα καὶ σὺν αὐτοῖς δισχιλίους στρατιώτας κατὰ τύχην παρόντας εἰς τὸν Ἰουδαίων ὄλεθρον ἐκ Λιβύης· ἐπέτρεψεν δὲ οὐ μόνον ἀναιρεῖν, ἀλλὰ καὶ τὰς κτήσεις αὐτῶν διαρπάζειν καὶ τὰς οἰκίας καταφλέγειν."},{"number":495,"text":"οἱ δʼ ὁρμήσαντες εἰς τὸ καλούμενον Δέλτα, συνῴκιστο γὰρ ἐκεῖ τὸ Ἰουδαϊκόν, ἐτέλουν τὰς ἐντολάς, οὐ μὴν ἀναιμωτί· συστραφέντες γὰρ οἱ Ἰουδαῖοι καὶ τοὺς ἄμεινον ὡπλισμένους ἑαυτῶν προταξάμενοι μέχρι πλείστου μὲν ἀντέσχον, ἅπαξ δʼ ἐγκλίναντες ἀνέδην διεφθείροντο."},{"number":496,"text":"καὶ παντοῖος ἦν αὐτῶν ὄλεθρος, τῶν μὲν ἐν τῷ πεδίῳ καταλαμβανομένων, τῶν δʼ εἰς τὰς οἰκίας συνωθουμένων. ὑπεπίμπρασαν δὲ καὶ ταύτας οἱ Ῥωμαῖοι προδιαρπάζοντες τὰ ἔνδον, καὶ οὔτε νηπίων ἔλεος αὐτοὺς οὔτε αἰδὼς εἰσῄει γερόντων,"},{"number":497,"text":"ἀλλὰ διὰ πάσης ἡλικίας ἐχώρουν κτείνοντες, ὡς ἐπικλυσθῆναι μὲν αἵματι πάντα τὸν χῶρον, πέντε δὲ μυριάδες ἐσωρεύθησαν νεκρῶν, περιελείφθη δʼ ἂν οὐδὲ τὸ λοιπόν, εἰ μὴ πρὸς ἱκετηρίας ἐτράποντο. κατοικτείρας δʼ αὐτοὺς Ἀλέξανδρος ἀναχωρεῖν τοὺς Ῥωμαίους ἐκέλευσεν."},{"number":498,"text":"οἱ μὲν οὖν ἐξ ἔθους τὸ πειθήνιον ἔχοντες ἅμα νεύματι τοῦ φονεύειν ἐπαύσαντο, τὸ δημοτικὸν δὲ τῶν Ἀλεξανδρέων διʼ ὑπερβολὴν μίσους δυσανάκλητον ἦν καὶ μόλις ἀπεσπᾶτο τῶν σωμάτων."},{"number":499,"text":"Τοιοῦτον μὲν τὸ κατὰ τὴν Ἀλεξάνδρειαν πάθος συνηνέχθη· Κεστίῳ δὲ οὐκέτι ἠρεμεῖν ἐδόκει πανταχοῦ τῶν Ἰουδαίων ἐκπεπολεμωμένων."},{"number":500,"text":"ἀναλαβὼν δὲ ἀπὸ τῆς Ἀντιοχείας τὸ μὲν δωδέκατον τάγμα πλῆρες, ἀπὸ δὲ τῶν λοιπῶν ἀνὰ δισχιλίους ἐπιλέκτους, πεζῶν τε ἓξ σπείρας καὶ τέσσαρας ἴλας ἱππέων, πρὸς αἷς τὰς παρὰ τῶν βασιλέων συμμαχίας, Ἀντιόχου μὲν δισχιλίους ἱππεῖς καὶ πεζοὺς τρισχιλίους τοξότας πάντας, Ἀγρίππα δὲ πεζοὺς μὲν τοὺς ἴσους ἱππεῖς δὲ δισχιλίων ἐλάττους,"},{"number":501,"text":"εἵπετο δὲ καὶ Σόαιμος μετὰ τετρακισχιλίων, ὧν ἦσαν ἱππεῖς ἡ τρίτη μοῖρα καὶ τὸ πλέον τοξόται, προῆλθεν εἰς Πτολεμαΐδα."},{"number":502,"text":"πλεῖστοι δὲ κἀκ τῶν πόλεων ἐπίκουροι συνελέγησαν, ἐμπειρίᾳ μὲν ἡττώμενοι τῶν στρατιωτῶν, ταῖς δὲ προθυμίαις καὶ τῷ κατὰ Ἰουδαίων μίσει τὸ λεῖπον ἐν ταῖς ἐπιστήμαις ἀντιπληροῦντες. παρῆν δὲ καὶ αὐτὸς Ἀγρίππας Κεστίῳ τῆς τε ὁδοῦ καὶ τῶν συμφερόντων ἐξηγούμενος."},{"number":503,"text":"ἀναλαβὼν δὲ μέρος τῆς δυνάμεως Κέστιος ὥρμησεν ἐπὶ πόλιν καρτερὰν τῆς Γαλιλαίας Χαβουλών, ἣ καλεῖται ἀνδρῶν, διορίζει δὲ ἀπὸ τοῦ ἔθνους τὴν Πτολεμαΐδα."},{"number":504,"text":"καὶ καταλαβὼν αὐτὴν ἔρημον μὲν ἀνδρῶν, ἀναπεφεύγει γὰρ τὸ πλῆθος εἰς τὰ ὄρη, πλήρη δὲ παντοίων κτημάτων, τὰ μὲν ἐφῆκεν τοῖς στρατιώταις διαρπάζειν, τὸ δὲ ἄστυ καίτοι θαυμάσας τοῦ κάλλους ἔχον τὰς οἰκίας ὁμοίως ταῖς ἐν Τύρῳ καὶ Σιδῶνι καὶ Βηρυτῷ δεδομημένας, ἐνέπρησεν."},{"number":505,"text":"ἔπειτα τὴν χώραν καταδραμὼν καὶ διαρπάσας μὲν πᾶν τὸ προσπῖπτον καταφλέξας δὲ τὰς πέριξ κώμας ὑπέστρεψεν εἰς τὴν Πτολεμαΐδα."},{"number":506,"text":"πρὸς δὲ ταῖς ἁρπαγαῖς ἔτι τῶν Σύρων ὄντων καὶ τὸ πλέον Βηρυτίων ἀναθαρσήσαντες οἱ Ἰουδαῖοι, καὶ γὰρ ἀποκεχωρηκότα συνίεσαν Κέστιον, τοῖς ἀπολειφθεῖσιν ἀδοκήτως ἐπέπεσον καὶ περὶ δισχιλίους αὐτῶν διέφθειραν."},{"number":507,"text":"Ὁ δὲ Κέστιος ἀναζεύξας ἀπὸ τῆς Πτολεμαΐδος αὐτὸς μὲν εἰς Καισάρειαν ἀφικνεῖται, μοῖραν δὲ τῆς στρατιᾶς προέπεμψεν εἰς Ἰόππην, προστάξας, εἰ μὲν καταλαβέσθαι δυνηθεῖεν τὴν πόλιν, φρουρεῖν, εἰ δὲ προαίσθοιντο τὴν ἔφοδον, περιμένειν αὐτόν τε καὶ τὴν ἄλλην δύναμιν."},{"number":508,"text":"τῶν δὲ οἱ μὲν κατὰ θάλασσαν οἱ δὲ κατὰ γῆν ἐπειχθέντες ἀμφοτέρωθεν αἱροῦσιν τὴν πόλιν ῥᾳδίως· καὶ μηδὲ φυγεῖν φθασάντων τῶν οἰκητόρων, οὐχ ὅπως παρασκευάσασθαι πρὸς μάχην, ἐμπεσόντες ἅπαντας ἀνεῖλον σὺν ταῖς γενεαῖς καὶ τὴν πόλιν διαρπάσαντες ἐνέπρησαν·"},{"number":509,"text":"ὁ δὲ ἀριθμὸς τῶν φονευθέντων τετρακόσιοι πρὸς ὀκτακισχιλίοις. ὁμοίως δὲ καὶ εἰς τὴν ὅμορον τῆς Καισαρείας Ναρβατηνὴν τοπαρχίαν ἔπεμψεν συχνοὺς τῶν ἱππέων, οἳ τήν τε γῆν ἔτεμον καὶ πολὺ πλῆθος διέφθειραν τῶν ἐπιχωρίων τάς τε κτήσεις διήρπασαν καὶ τὰς κώμας κατέφλεξαν."},{"number":510,"text":"Εἰς δὲ τὴν Γαλιλαίαν ἀπέστειλεν Καισέννιον Γάλλον ἡγεμόνα τοῦ δωδεκάτου τάγματος παραδοὺς δύναμιν ὅσην ἀρκέσειν πρὸς τὸ ἔθνος ὑπελάμβανεν."},{"number":511,"text":"τοῦτον ἡ καρτερωτάτη τῆς Γαλιλαίας πόλις Σέπφωρις μετʼ εὐφημίας δέχεται, καὶ πρὸς τὴν ταύτης εὐβουλίαν αἱ λοιπαὶ πόλεις ἠρέμουν. τὸ δὲ στασιῶδες καὶ λῃστρικὸν πᾶν ἔφυγεν εἰς τὸ μεσαίτατον τῆς Γαλιλαίας ὄρος, ὃ κεῖται μὲν ἀντικρὺ τῆς Σεπφώρεως, καλεῖται δὲ Ἀσαμών. τούτοις ὁ Γάλλος ἐπῆγε τὴν δύναμιν."},{"number":512,"text":"οἱ δὲ ἕως μὲν ἦσαν ὑπερδέξιοι, ῥᾳδίως τοὺς Ῥωμαίους ἠμύναντο προσιόντας καὶ πρὸς διακοσίους αὐτῶν ἀνεῖλον, περιελθόντων δὲ καὶ γενομένων ἐν τοῖς ὑψηλοτέροις ἡττῶντο ταχέως, καὶ οὔτε γυμνῆτες ὁπλίτας συστάδην ἔφερον οὔτε ἐν τῇ τροπῇ τοὺς ἱππεῖς ἐξέφευγον, ὥστε ὀλίγους μὲν ἐν ταῖς δυσχωρίαις διαλαθεῖν, ἀναιρεθῆναι δὲ ὑπὲρ δισχιλίους."}],"19":[{"number":513,"text":"Γάλλος μὲν οὖν ὡς οὐδὲν ἔτι ἑώρα κατὰ τὴν Γαλιλαίαν νεωτεριζόμενον, ὑπέστρεφεν μετὰ τῆς στρατιᾶς εἰς Καισάρειαν· Κέστιος δὲ μετὰ πάσης τῆς δυνάμεως ἀναζεύξας ἐνέβαλεν εἰς Ἀντιπατρίδα, καὶ πυθόμενος ἔν τινι πύργῳ Ἀφεκοῦ καλουμένῳ συνηθροῖσθαι Ἰουδαίων δύναμιν οὐκ ὀλίγην προέπεμπεν τοὺς συμβαλοῦντας."},{"number":514,"text":"οἱ δὲ πρὶν εἰς χεῖρας ἐλθεῖν δέει τοὺς Ἰουδαίους διεσκέδασαν, ἐπελθόντες δὲ ἔρημον τὸ στρατόπεδον καὶ τὰς πέριξ κώμας ἐνέπρησαν."},{"number":515,"text":"ἀπὸ δὲ τῆς Ἀντιπατρίδος Κέστιος εἰς Λύδδα προελθὼν κενὴν ἀνδρῶν τὴν πόλιν καταλαμβάνει· διὰ γὰρ τὴν τῆς σκηνοπηγίας ἑορτὴν ἀναβεβήκει πᾶν τὸ πλῆθος εἰς Ἱεροσόλυμα."},{"number":516,"text":"πεντήκοντα δὲ τῶν παραφανέντων διαφθείρας καὶ τὸ ἄστυ κατακαύσας ἐχώρει πρόσω, καὶ διὰ Βαιθώρων ἀναβὰς στρατοπεδεύεται κατά τινα χῶρον Γαβαὼ καλούμενον, ἀπέχοντα τῶν Ἱεροσολύμων πεντήκοντα σταδίους."},{"number":517,"text":"Οἱ δὲ Ἰουδαῖοι κατιδόντες ἤδη πλησιάζοντα τῇ μητροπόλει τὸν πόλεμον, ἀφέμενοι τὴν ἑορτὴν ἐχώρουν ἐπὶ τὰ ὅπλα, καὶ μέγα τῷ πλήθει θαρροῦντες ἄτακτοι μετὰ κραυγῆς ἐξεπήδων ἐπὶ τὴν μάχην μηδὲ τῆς ἀργῆς ἑβδομάδος ἔννοιαν λαβόντες· ἦν γὰρ δὴ τὸ μάλιστα παρʼ αὐτοῖς θρησκευόμενον σάββατον."},{"number":518,"text":"ὁ δʼ ἐκσείσας αὐτοὺς τῆς εὐσεβείας θυμὸς ἐποίησεν πλεονεκτῆσαι καὶ κατὰ τὴν μάχην· μετὰ τοσαύτης γοῦν ὁρμῆς τοῖς Ῥωμαίοις προσέπεσον, ὡς διαρρῆξαι τὰς τάξεις αὐτῶν καὶ διὰ μέσων χωρεῖν ἀναιροῦντας."},{"number":519,"text":"εἰ δὲ μὴ τῷ χαλασθέντι τῆς φάλαγγος οἵ τε ἱππεῖς ἐκπεριελθόντες ἐπήμυναν καὶ τοῦ πεζοῦ τὸ μὴ σφόδρα κάμνον, κἂν ἐκινδύνευσεν ὅλῃ τῇ δυνάμει Κέστιος. ἀπέθανον δὲ Ῥωμαίων πεντακόσιοι δεκαπέντε· τούτων ἦσαν οἱ τετρακόσιοι πεζοί, τὸ δὲ λοιπὸν ἱππεῖς· τῶν δὲ Ἰουδαίων δύο πρὸς τοῖς εἴκοσι."},{"number":520,"text":"γενναιότατοι δʼ αὐτῶν ἔδοξαν οἱ Μονοβάζου τοῦ τῆς Ἀδιαβηνῆς βασιλέως συγγενεῖς, Μονόβαζός τε καὶ Κενεδαῖος, μεθʼ οὓς ὁ Περαΐτης Νίγερ καὶ Σίλας ὁ Βαβυλώνιος αὐτομολήσας εἰς τοὺς Ἰουδαίους ἀπʼ Ἀγρίππα τοῦ βασιλέως·"},{"number":521,"text":"ἐστρατεύετο γὰρ παρʼ αὐτῷ. κατὰ πρόσωπον μὲν οὖν ἀνακοπέντες Ἰουδαῖοι πρὸς τὴν πόλιν ὑπέστρεφον, κατόπιν δὲ τοῖς Ῥωμαίοις ἐπὶ τὴν Βεθώραν ἀνιοῦσιν προσπεσὼν ὁ τοῦ Γιώρα Σίμων πολὺ τῆς οὐραγίας ἐσπάραξεν καὶ συχνὰ τῶν σκευοφόρων ἀποσπάσας ἤγαγεν εἰς τὴν πόλιν."},{"number":522,"text":"μένοντος δὲ τοῦ Κεστίου κατὰ χώραν τρισὶν ἡμέραις οἱ Ἰουδαῖοι τὰ μετέωρα κατειληφότες ἐπετήρουν τὰς παρόδους δῆλοί τε ἦσαν οὐκ ἠρεμήσοντες ἀρξαμένων τῶν Ῥωμαίων ὁδεύειν."},{"number":523,"text":"Ἔνθα δὴ κατιδὼν Ἀγρίππας οὐδὲ τὰ Ῥωμαίων ἀκίνδυνα πλήθους ἀπείρου πολεμίων τὰ ὄρη περισχόντος ἔκρινεν ἀποπειραθῆναι τῶν Ἰουδαίων λόγοις· ἢ γὰρ πάντας πείσειν καταθέσθαι τὸν πόλεμον ἢ τῶν ἐναντιωθέντων ἀποστήσειν τὸ μὴ συμφρονοῦν."},{"number":524,"text":"ἔπεμψεν οὖν τῶν παρʼ ἑαυτῷ τοὺς μάλιστα γνωρίμους ἐκείνοις Βόρκιόν τε καὶ Φοῖβον, δεξιάς τε παρὰ Κεστίου καὶ συγγνώμην παρὰ Ῥωμαίοις ἀσφαλῆ περὶ τῶν ἡμαρτημένων ὑπισχνούμενος, εἰ τὰ ὅπλα ῥίψαντες πρὸς αὐτοὺς μεταβάλοιντο."},{"number":525,"text":"δείσαντες δὲ οἱ στασιασταὶ μὴ πᾶν τὸ πλῆθος ἀδείας ἐλπίδι πρὸς τὸν Ἀγρίππαν μεταβάληται, τοὺς ἀπʼ αὐτοῦ πρεσβεύοντας ὥρμησαν ἀνελεῖν."},{"number":526,"text":"καὶ πρὶν ἢ φθέγξασθαι τὸν μὲν Φοῖβον διέφθειραν, ὁ δὲ Βόρκιος τρωθεὶς ἔφθη διαφυγεῖν· τοῦ δήμου δὲ τοὺς ἀγανακτήσαντας λίθοις καὶ ξύλοις παίοντες εἰς τὸ ἄστυ συνήλασαν."},{"number":527,"text":"Κέστιος δὲ τὴν πρὸς ἀλλήλους αὐτῶν ταραχὴν εὔκαιρον ἰδὼν εἰς ἐπίθεσιν ἅπασαν ἐπῆγεν τὴν δύναμιν καὶ τραπέντας μέχρι Ἱεροσολύμων κατεδίωξεν."},{"number":528,"text":"στρατοπεδευσάμενος δὲ ἐπὶ τοῦ καλουμένου Σκοποῦ, διέχει δʼ οὗτος ἑπτὰ τῆς πόλεως σταδίους, τρισὶ μὲν ἡμέραις οὐκ ἐπεχείρει τῇ πόλει τάχα τι παρὰ τῶν ἔνδον ἐνδοθήσεσθαι προσδοκῶν, εἰς δὲ τὰς πέριξ κώμας ἐφʼ ἁρπαγὴν σίτου πολλοὺς διαφῆκεν τῶν στρατιωτῶν· τῇ τετάρτῃ δέ, ἥτις ἦν τριακὰς Ὑπερβερεταίου μηνός, διατάξας τὴν στρατιὰν εἰσῆγεν εἰς τὴν πόλιν."},{"number":529,"text":"ὁ μὲν οὖν δῆμος ὑπὸ τοῖς στασιασταῖς ἔμφρουρος ἦν, οἱ δὲ στασιασταὶ τὴν εὐταξίαν τῶν Ῥωμαίων καταπλαγέντες τῶν μὲν ἔξω τῆς πόλεως μερῶν εἶκον, εἰς δὲ τὴν ἐνδοτέρω καὶ τὸ ἱερὸν ἀνεχώρουν."},{"number":530,"text":"Κέστιος δὲ παρελθὼν ὑποπίμπρησιν τήν τε Βεθεζὰν προσαγορευομένην καὶ τὴν Καινόπολιν καὶ τὸ καλούμενον Δοκῶν ἀγοράν, ἔπειτα πρὸς τὴν ἄνω πόλιν ἐλθὼν ἀντικρὺ τῆς βασιλικῆς αὐλῆς ἐστρατοπεδεύετο."},{"number":531,"text":"κἂν εἴπερ ἠθέλησεν κατʼ αὐτὴν ἐκείνην τὴν ὥραν ἐντὸς τῶν τειχέων βιάσασθαι, παραυτίκα τὴν πόλιν ἔσχεν καὶ τὸν πόλεμον συνέβη καταλελύσθαι· ἀλλὰ γὰρ ὅ τε στρατοπεδάρχης Τυράννιος Πρῖσκος καὶ τῶν ἱππάρχων οἱ πλεῖστοι χρήμασιν ὑπὸ Φλώρου δεκασθέντες ἀπέστρεψαν αὐτὸν τῆς ἐπιχειρήσεως."},{"number":532,"text":"καὶ παρὰ τὴν αἰτίαν ταύτην ὅ τε πόλεμος ἐπὶ τοσοῦτον μῆκος προύβη καὶ ἀνηκέστων Ἰουδαίους συμφορῶν ἀναπλησθῆναι συνέπεσεν."},{"number":533,"text":"Ἐν δὲ τούτῳ πολλοὶ τῶν γνωρίμων δημοτῶν Ἀνάνῳ τῷ Ἰωνάθου παιδὶ πεισθέντες ἐκάλουν τὸν Κέστιον ὡς ἀνοίξοντες αὐτῷ τὰς πύλας."},{"number":534,"text":"ὁ δὲ καὶ πρὸς ὀργὴν ὑπεριδὼν καὶ μὴ πάνυ πιστεύσας διεμέλλησεν, ἕως οἱ στασιασταὶ τὴν προδοσίαν αἰσθόμενοι τοὺς μὲν περὶ τὸν Ἄνανον ἀπὸ τοῦ τείχους κατέβαλον καὶ λίθοις παίοντες συνήλασαν εἰς τὰς οἰκίας, αὐτοὶ δὲ διαστάντες ἀπὸ τῶν πύργων τοὺς ἀποπειρωμένους τοῦ τείχους ἔβαλλον."},{"number":535,"text":"πέντε μὲν οὖν ἡμέραις πάντοθεν ἐπιχειροῦσιν τοῖς Ῥωμαίοις ἀμήχανος ἦν ἡ προσβολή, τῇ δʼ ἐπιούσῃ ἀναλαβὼν ὁ Κέστιος τῶν τε ἐπιλέκτων συχνοὺς καὶ τοὺς τοξότας κατὰ τὸ προσάρκτιον ἐπεχείρει κλίμα τῷ ἱερῷ."},{"number":536,"text":"Ἰουδαῖοι δὲ ἀπὸ τῆς στοᾶς εἶργον, καὶ πολλάκις μὲν ἀπεκρούσαντο τοὺς τῷ τείχει προσελθόντας, τέλος δὲ τῷ πλήθει τῶν βελῶν ἀνακοπέντες ὑπεχώρησαν."},{"number":537,"text":"τῶν δὲ Ῥωμαίων οἱ πρῶτοι τοὺς θυρεοὺς ἐξερείσαντες εἰς τὸ τεῖχος καὶ κατὰ τούτων οἱ κατόπιν ἄλλους οἵ τε ἑξῆς ὁμοίως τὴν καλουμένην παρʼ αὐτοῖς χελώνην ἐφράξαντο, καθʼ ἧς τὰ βέλη φερόμενα περιωλίσθανεν ἄπρακτα, μηδὲν δὲ οἱ στρατιῶται κακούμενοι τὸ τεῖχος ὑπέσυρον καὶ τοῦ ἱεροῦ τὴν πύλην ὑποπιμπράναι παρεσκευάζοντο."},{"number":538,"text":"Δεινὴ δὲ τοὺς στασιαστὰς ἔκπληξις κατέλαβεν· ἤδη δὲ πολλοὶ διεδίδρασκον ἀπὸ τῆς πόλεως ὡς ἁλωσομένης αὐτίκα. τὸν δὲ δῆμον ἐπὶ τούτοις συνέβαινεν θαρρεῖν, καὶ καθὸ παρείκοιεν οἱ πονηροί, προσῄεσαν αὐτοὶ τὰς πύλας ἀνοίξοντες καὶ δεξόμενοι τὸν Κέστιον ὡς εὐεργέτην."},{"number":539,"text":"ὃς εἰ βραχὺ τῇ πολιορκίᾳ προσελιπάρησεν, κἂν εὐθέως τὴν πόλιν παρέλαβεν· ἀλλʼ οἶμαι διὰ τοὺς πονηροὺς ἀπεστραμμένος ὁ θεὸς ἤδη καὶ τὰ ἅγια τέλος λαβεῖν ἐπʼ ἐκείνης τῆς ἡμέρας ἐκώλυσεν τὸν πόλεμον."},{"number":540,"text":"Ὁ γοῦν Κέστιος οὔτε τὴν τῶν πολιορκουμένων ἀπόγνωσιν οὔτε τοῦ δήμου τὸ φρόνημα συνιδὼν ἐξαίφνης ἀνεκάλεσεν τοὺς στρατιώτας καὶ καταγνοὺς ἐπʼ οὐδεμιᾷ πληγῇ τῶν ἐλπίδων παραλογώτατα ἀπὸ τῆς πόλεως ἀνέζευξεν."},{"number":541,"text":"πρὸς δὲ τὴν ἀδόκητον αὐτοῦ τροπὴν ἀναθαρσήσαντες οἱ λῃσταὶ κατὰ τῶν ὑστάτων ἐπεξέδραμον καὶ συχνοὺς τῶν ἱππέων καὶ πεζῶν διέφθειραν."},{"number":542,"text":"τότε μὲν οὖν ἐν τῷ κατὰ τὸν Σκοπὸν αὐλίζεται στρατοπέδῳ Κέστιος, τῇ δʼ ἐπιούσῃ προσωτέρω χωριζόμενος μᾶλλον ἐξεκαλέσατο τοὺς πολεμίους, καὶ τοὺς ὑστάτους αὐτῶν προσκείμενοι διέφθειρον καὶ καθʼ ἑκάτερον τῆς ὁδοῦ περιιόντες ἠκόντιζον εἰς πλαγίους."},{"number":543,"text":"οὔτε δὲ ἐπιστραφῆναι πρὸς τοὺς κατόπιν τιτρώσκοντας ἐθάρρουν οἱ τελευταῖοι ἄπειρόν τι πλῆθος οἰόμενοι διώκειν καὶ τοὺς κατὰ πλευρὸν ἐγκειμένους ἀναστέλλειν οὐχ ὑπέμενον, αὐτοὶ μὲν ὄντες βαρεῖς καὶ δεδοικότες τὴν τάξιν διασπᾶν, τοὺς δὲ Ἰουδαίους ὁρῶντες κούφους καὶ πρὸς τὰς ἐπιδρομὰς εὐκόλους· ὥστε συνέβαινεν αὐτοῖς πολλὰ κακοῦσθαι μηδὲν ἀντιβλάπτουσιν τοὺς ἐχθρούς."},{"number":544,"text":"παρʼ ὅλην δὲ τὴν ὁδὸν παιόμενοι καὶ τῆς φάλαγγος ἐκσειόμενοι κατέπιπτον, μέχρι πολλῶν διαφθαρέντων, ἐν οἷς ἦν Πρῖσκος μὲν στρατάρχης τάγματος ἕκτου, Λογγῖνος δὲ χιλίαρχος, ἔπαρχος δὲ ἴλης Αἰμίλιος Ἰούκουνδος ὄνομα, μόλις εἰς Γαβαὼν κατήντησαν ἐπὶ τὸ πρότερον στρατόπεδον, τὰ πολλὰ καὶ τῶν σκευῶν ἀποβαλόντες."},{"number":545,"text":"ἔνθα δύο μὲν ἡμέρας ἐπέμεινεν ὁ Κέστιος ἀμηχανῶν, ὅ τι χρὴ ποιεῖν, τῇ τρίτῃ δὲ πολλῷ πλείους τοὺς πολεμίους θεασάμενος καὶ πάντα τὰ κύκλῳ μεστὰ Ἰουδαίων ἔγνω καθʼ ἑαυτοῦ τε βραδύνας κἂν ἔτι μείνῃ πλείοσιν χρησόμενος ἐχθροῖς."},{"number":546,"text":"Ἵνα δὲ συντονωτέρᾳ χρήσαιτο φυγῇ, τὰ τὴν στρατιὰν ἀνθέλκοντα περικόπτειν προσέταξεν. διαφθαρέντων δὲ τῶν τε ὀρέων καὶ τῶν ὄνων ἔτι δὲ καὶ τῶν ὑποζυγίων πλὴν ὅσα βέλη παρεκόμιζεν καὶ μηχανάς, τούτων γὰρ διὰ τὴν χρείαν περιείχοντο καὶ μάλιστα δεδοικότες, μὴ Ἰουδαίοις κατʼ αὐτῶν ἁλῷ, προῆγε τὴν δύναμιν ἐπὶ Βεθώρων."},{"number":547,"text":"οἱ δὲ Ἰουδαῖοι κατὰ μὲν τὰς εὐρυχωρίας ἧττον ἐπέκειντο, συνειληθέντων δὲ εἰς τὰ στενὰ καὶ τὴν κατάβασιν οἱ μὲν φθάσαντες εἶργον αὐτοὺς τῆς ἐξόδου, ἄλλοι δὲ τοὺς ὑστάτους κατεώθουν εἰς τὴν φάραγγα, τὸ δὲ πᾶν πλῆθος παρεκταθὲν ὑπὲρ τὸν αὐχένα τῆς ὁδοῦ κατεκάλυπτε τὴν φάλαγγα τοῖς βέλεσιν."},{"number":548,"text":"ἔνθα καὶ τῶν πεζῶν ἀμηχανούντων προσαμύνειν ἑαυτοῖς ἐπισφαλέστερος τοῖς ἱππεῦσιν ὁ κίνδυνος ἦν· οὔτε γὰρ ἐν τάξει κατὰ τῆς ὁδοῦ βαδίζειν ἐδύναντο βαλλόμενοι, καὶ τὸ πρόσαντες ἐπὶ τοὺς πολεμίους ἱππάσιμον οὐκ ἦν·"},{"number":549,"text":"τὸ δὲ ἐπὶ θάτερα κρημνοὶ καὶ φάραγγες, εἰς οὓς ἀποσφαλέντες κατεφθείροντο, καὶ οὔτε φυγῆς τις τόπον οὔτε ἀμύνης εἶχεν ἐπίνοιαν, ἀλλʼ ὑπʼ ἀμηχανίας ἐπʼ οἰμωγὴν ἐτράποντο καὶ τοὺς ἐν ἀπογνώσεσιν ὀδυρμούς· ἀντήχει δʼ αὐτοῖς τὸ παρὰ Ἰουδαίων ἐγκέλευσμα καὶ κραυγὴ χαιρόντων ἅμα καὶ τεθυμωμένων."},{"number":550,"text":"ὀλίγου δὲ δεῖν πᾶσαν ἀνήρπασαν τὴν ἅμα Κεστίῳ δύναμιν, εἰ μὴ νὺξ ἐπέλαβεν, ἐν ᾗ Ῥωμαῖοι μὲν εἰς τὴν Βεθώραν κατέφυγον, Ἰουδαῖοι δὲ πάντα τὰ κύκλῳ περισχόντες ἐφρούρουν αὐτῶν τὴν ἔξοδον."},{"number":551,"text":"Ἔνθα δὴ Κέστιος τὴν φανερὰν ὁδὸν ἀπογνοὺς δρασμὸν ἐβουλεύετο καὶ διακρίνας τοὺς εὐψυχοτάτους στρατιώτας ὡσεὶ τετρακοσίους ἐπέστησεν τῶν δωμάτων, προστάξας ἀναβοᾶν τὰ σημεῖα τῶν ἐν τοῖς στρατοπέδοις φυλάκων, ὅπως Ἰουδαῖοι πᾶσαν οἴωνται τὴν δύναμιν κατὰ χώραν μένειν· αὐτὸς δὲ τοὺς λοιποὺς ἀναλαβὼν ἡσυχῆ τριάκοντα πρόεισιν σταδίους."},{"number":552,"text":"ἕωθεν δὲ Ἰουδαῖοι κατιδόντες ἔρημον τὴν ἔπαυλιν αὐτῶν ἐπὶ τοὺς ἐξαπατήσαντας τετρακοσίους ἔδραμον, κἀκείνους μὲν ταχέως κατηκόντισαν, ἐδίωκον δὲ τὸν Κέστιον."},{"number":553,"text":"ὁ δὲ τῆς τε νυκτὸς οὐκ ὀλίγον προειλήφει καὶ συντονώτερον ἔφευγεν μεθʼ ἡμέραν, ὥστε τοὺς στρατιώτας ὑπʼ ἐκπλήξεως καὶ δέους τάς τε ἑλεπόλεις καὶ τοὺς ὀξυβελεῖς καὶ τὰ πολλὰ τῶν ἄλλων ὀργάνων καταλιπεῖν, ἃ τότε Ἰουδαῖοι λαβόντες αὖθις ἐχρήσαντο κατὰ τῶν ἀφέντων."},{"number":554,"text":"προῆλθον δὲ τοὺς Ῥωμαίους διώκοντες μέχρι Ἀντιπατρίδος. ἔπειθʼ ὡς οὐ κατελάμβανον, ὑποστρέφοντες τάς τε μηχανὰς ᾖρον καὶ τοὺς νεκροὺς ἐσύλων τήν τε ἀπολειφθεῖσαν λείαν συνῆγον καὶ μετὰ παιάνων εἰς τὴν μητρόπολιν ἐπαλινδρόμουν,"},{"number":555,"text":"αὐτοὶ μὲν ὀλίγους ἀποβεβλημένοι παντάπασιν, τῶν δὲ Ῥωμαίων καὶ τῶν συμμάχων πεζοὺς μὲν πεντακισχιλίους καὶ τριακοσίους ἀνῃρηκότες, ἱππεῖς δὲ ὀγδοήκοντα καὶ τετρακοσίους. τάδε μὲν οὖν ἐπράχθη Δίου μηνὸς ὀγδόῃ δωδεκάτῳ τῆς Νέρωνος ἡγεμονίας ἔτει."}],"20":[{"number":556,"text":"Μετὰ δὲ τὴν Κεστίου συμφορὰν πολλοὶ τῶν ἐπιφανῶν Ἰουδαίων ὥσπερ βαπτιζομένης νηὸς ἀπενήχοντο τῆς πόλεως. Κοστόβαρος γοῦν καὶ Σάουλος ἀδελφοὶ σὺν Φιλίππῳ τῷ Ἰακίμου, στρατοπεδάρχης δʼ ἦν οὗτος Ἀγρίππα τοῦ βασιλέως, διαδράντες ἐκ τῆς πόλεως ᾤχοντο πρὸς Κέστιον·"},{"number":557,"text":"ὁ δὲ σὺν τούτοις κατὰ τὴν βασιλικὴν αὐλὴν πολιορκηθεὶς Ἀντίπας ὑπεριδὼν τὴν φυγὴν αὖθις ὡς ὑπὸ τῶν στασιαστῶν διεφθάρη δηλώσομεν."},{"number":558,"text":"Κέστιος δὲ τοὺς περὶ Σάουλον ἀξιώσαντας ἀνέπεμψεν εἰς Ἀχαΐαν πρὸς Νέρωνα τήν τε αὐτῶν δηλώσοντας ἀνάγκην καὶ τὰς αἰτίας τοῦ πολέμου τρέψοντας εἰς Φλῶρον· τὴν γὰρ ἐπʼ ἐκεῖνον ὀργὴν κουφίσειν καὶ τοὺς ἑαυτοῦ κινδύνους ἤλπισεν."},{"number":559,"text":"Κἀν τούτῳ Δαμασκηνοὶ τὴν τῶν Ῥωμαίων φθορὰν πυθόμενοι τοὺς παρʼ ἑαυτοῖς Ἰουδαίους ἀνελεῖν ἐσπούδασαν."},{"number":560,"text":"καὶ καθὸ μὲν εἶχον αὐτοὺς ἐν τῷ γυμνασίῳ συνηθροισμένους πάλαι διὰ τὰς ὑποψίας τοῦτο πραγματευσάμενοι, ῥᾴστην τὴν ἐπιχείρησιν ἐδόκουν· ἐδεδοίκεισαν δὲ τὰς ἑαυτῶν γυναῖκας ἁπάσας πλὴν ὀλίγων ὑπηγμένας τῇ Ἰουδαϊκῇ θρησκείᾳ·"},{"number":561,"text":"διὸ μέγιστος αὐτοῖς ἀγὼν ἐγένετο λαθεῖν ἐκείνας. τοὺς δὲ Ἰουδαίους ὡς ἂν ἐν στενῷ χωρίῳ τὸν ἀριθμὸν μυρίους καὶ πεντακοσίους πάντας ἀνόπλους ἐπελθόντες ὑπὸ μίαν ὥραν ἀδεῶς ἀπέσφαξαν."},{"number":562,"text":"Οἱ δὲ διώξαντες τὸν Κέστιον ὡς ὑπέστρεψαν εἰς Ἱεροσόλυμα, τοὺς μὲν βίᾳ τῶν ἔτι ῥωμαϊζόντων τοὺς δὲ πειθοῖ προσήγοντο, καὶ συναθροισθέντες εἰς τὸ ἱερὸν στρατηγοὺς ἀπεδείκνυσαν τοῦ πολέμου πλείονας."},{"number":563,"text":"ᾑρέθη δὲ Ἰώσηπός τε υἱὸς Γωρίονος καὶ ὁ ἀρχιερεὺς Ἄνανος τῶν τε κατὰ τὴν πόλιν ἁπάντων αὐτοκράτορες καὶ μάλιστα τὰ τείχη τῆς πόλεως ἀνεγείρειν·"},{"number":564,"text":"τὸν γὰρ τοῦ Σίμωνος υἱὸν Ἐλεάζαρον καίπερ ὑφʼ ἑαυτῷ πεποιημένον τὴν Ῥωμαίων λείαν καὶ τὰ ἁρπαγέντα Κεστίου χρήματα, πρὸς οἷς πολλὰ τῶν δημοσίων θησαυρῶν, ὅμως οὐκ ἐπέστησαν ταῖς χρείαις αὐτόν τε τυραννικὸν ὁρῶντες καὶ τοὺς ὑπʼ αὐτῷ ζηλωτὰς δορυφόρων ἔθεσι χρωμένους."},{"number":565,"text":"κατʼ ὀλίγον γε μὴν ἥ τε χρεία τῶν χρημάτων καὶ γοητεύων Ἐλεάζαρος ἐκπεριῆλθε τὸν δῆμον ὥστε αὐτῷ πειθαρχεῖν περὶ τῶν ὅλων."},{"number":566,"text":"Εἰς δὲ τὴν Ἰδουμαίαν ἑτέρους ἐπελέξαντο στρατηγοὺς Ἰησοῦν υἱὸν Σαπφᾶ τῶν ἀρχιερέων ἕνα καὶ Ἐλεάζαρον ἀρχιερέως υἱὸν Νέου· τῷ δʼ ἄρχοντι τότε τῆς Ἰδουμαίας Νίγερι, γένος δʼ ἦν ἐκ τῆς περὶ Ἰορδάνην Περαίας, διὸ καὶ Περαΐτης ἐκαλεῖτο, προσέταξαν ὑποτάσσεσθαι τοῖς στρατηγοῖς."},{"number":567,"text":"ἠμέλουν δὲ οὐδὲ τῆς ἄλλης χώρας, ἀλλʼ εἰς μὲν Ἱεριχοῦν Ἰώσηπος ὁ Σίμωνος, εἰς δὲ τὴν Περαίαν Μανασσῆς, Θαμνᾶ δὲ τοπαρχίας Ἰωάννης ὁ Ἐσσαῖος στρατηγήσων ἐπέμφθη· προσκεκλήρωτο δʼ αὐτῷ Λύδδα καὶ Ἰόππη καὶ Ἀμμαοῦς."},{"number":568,"text":"τῆς δὲ Γοφνιτικῆς καὶ Ἀκραβεττηνῆς ὁ Ἀνανίου Ἰωάννης ἡγεμὼν ἀποδείκνυται καὶ τῆς Γαλιλαίας ἑκατέρας Ἰώσηπος Ματθίου· προσώριστο δὲ τῇ τούτου στρατηγίᾳ καὶ Γάμαλα τῶν ταύτῃ πόλεων ὀχυρωτάτη."},{"number":569,"text":"Τῶν μὲν οὖν ἄλλων στρατηγῶν ἕκαστος ὡς εἶχεν προθυμίας ἢ συνέσεως διῴκει τὰ πεπιστευμένα· Ἰώσηπος δὲ εἰς τὴν Γαλιλαίαν ἐλθὼν πρῶτον ἐφρόντισεν τῆς εἰς ἑαυτὸν εὐνοίας τῶν ἐπιχωρίων, εἰδὼς ὅτι ταύτῃ πλεῖστα κατορθώσει, κἂν τἆλλα διαμαρτάνῃ."},{"number":570,"text":"συνιδὼν δὲ ὅτι τοὺς μὲν δυνατοὺς οἰκειώσεται μεταδιδοὺς τῆς ἐξουσίας αὐτοῖς, τὸ δὲ πᾶν πλῆθος εἰ διʼ ἐπιχωρίων καὶ συνήθων τὰ πολλὰ προστάσσοι, τῶν μὲν γηραιῶν ἑβδομήκοντα τοὺς σωφρονεστάτους ἐπιλέξας ἐκ τοῦ ἔθνους κατέστησεν ἄρχοντας ὅλης τῆς Γαλιλαίας,"},{"number":571,"text":"ἑπτὰ δὲ ἐν ἑκάστῃ πόλει δικαστὰς τῶν εὐτελεστέρων διαφόρων· τὰ γὰρ μείζω πράγματα καὶ τὰς φονικὰς δίκας ἐφʼ ἑαυτὸν ἀναπέμπειν ἐκέλευσεν καὶ τοὺς ἑβδομήκοντα."},{"number":572,"text":"Καταστησάμενος δὲ τὰ πρὸς ἀλλήλους νόμιμα τῶν κατὰ πόλιν ἐπὶ τὴν ἔξωθεν αὐτῶν ἀσφάλειαν ἐχώρει."},{"number":573,"text":"καὶ γινώσκων Ῥωμαίους προεμβαλοῦντας εἰς τὴν Γαλιλαίαν τὰ ἐπιτήδεια τῶν χωρίων ἐτείχιζεν, Ἰωτάπατα μὲν καὶ Βηρσαβὲ καὶ Σελάμην, ἔτι δὲ Καφαρεκχὼ καὶ Ἰαφὰ καὶ Σιγὼφ τό τε Ἰταβύριον καλούμενον ὄρος καὶ Ταριχέας καὶ Τιβεριάδα, πρὸς δὲ τούτοις τὰ περὶ Γεννησὰρ τὴν λίμνην σπήλαια κατὰ τὴν κάτω καλουμένην Γαλιλαίαν ἐτειχίσατο, τῆς δὲ ἄνω Γαλιλαίας τήν τε προσαγορευομένην Ἀκχαβάρων πέτραν καὶ Σὲπφ καὶ Ἰαμνεὶθ καὶ Μηρώ."},{"number":574,"text":"κατὰ δὲ τὴν Γαυλανιτικὴν Σελεύκειάν τε καὶ Σωγαναίαν καὶ Γάμαλαν ὠχύρωσεν· μόνοις δὲ Σεπφωρίταις ἐφῆκε καθʼ ἑαυτοὺς τεῖχος ἀναδείμασθαι χρημάτων τε εὐπόρους ὁρῶν ὄντας καὶ προθύμους ἐπὶ τὸν πόλεμον δίχα προστάγματος."},{"number":575,"text":"ὁμοίως δὲ καὶ Γίσχαλα Ἰωάννης ὁ Ληΐου καθʼ ἑαυτὸν ἐτείχιζεν Ἰωσήπου κελεύσαντος· τοῖς δʼ ἄλλοις ἐρύμασιν ἅπασιν αὐτὸς συμπονῶν ἅμα καὶ προστάσσων παρῆν."},{"number":576,"text":"κατέλεξεν δὲ καὶ δύναμιν ἐκ τῆς Γαλιλαίας ὑπὲρ δέκα μυριάδας νέων ἀνδρῶν, οὓς πάντας ἔκ τε τῶν συλλεγομένων παλαιῶν ὅπλων ἐγκατασκευαζόμενος ὥπλιζεν."},{"number":577,"text":"Ἔπειτα συνιδὼν ἀήττητον τὴν Ῥωμαίων ἰσχὺν γεγενημένην εὐπειθείᾳ μάλιστα καὶ μελέτῃ τῶν ὅπλων, τὴν μὲν διδασκαλίαν ἀπέγνω τῇ χρείᾳ διωκομένην, τὸ δʼ εὐπειθὲς ὁρῶν περιγινόμενον ἐκ τοῦ πλήθους τῶν ἡγεμόνων ῥωμαϊκώτερον ἔτεμνεν τὴν στρατιὰν καὶ πλείους καθίστατο ταξιάρχους."},{"number":578,"text":"στρατιωτῶν τε γὰρ ἀπεδείκνυεν διαφοράς, καὶ τούτους μὲν ὑπέτασσεν δεκαδάρχαις καὶ ἑκατοντάρχαις ἔπειτα χιλιάρχοις, κἀπὶ τούτοις ἡγεμόνας ταγμάτων ἁδροτέρων ἀφηγουμένους."},{"number":579,"text":"ἐδίδασκεν δὲ σημείων παραδόσεις καὶ σάλπιγγος προκλήσεις τε καὶ ἀνακλήσεις προσβολάς τε κεράτων καὶ περιαγωγάς, καὶ πῶς δεῖ πρὸς μὲν τὸ κάμνον ἐπιστρέφειν ἐκ τοῦ περιόντος, ἐν δὲ τῷ πονοῦντι συμπαθεῖν."},{"number":580,"text":"ὅσα τε εἰς παράστασιν ψυχῆς ἢ καρτερίαν συνετέλει σώματος ἀφηγεῖτο· μάλιστα δʼ αὐτοὺς ἤσκει πρὸς τὸν πόλεμον παρʼ ἕκαστα τὴν Ῥωμαίων εὐταξίαν διηγούμενος, καὶ ὡς πολεμήσουσιν πρὸς ἄνδρας, οἳ διʼ ἀλκὴν σώματος καὶ ψυχῆς παράστημα πάσης ὀλίγου δεῖν τῆς οἰκουμένης κρατοῦσιν."},{"number":581,"text":"ἔφη δὲ πεῖραν αὐτῶν λήψεσθαι τῆς κατὰ τὸν πόλεμον πειθαρχίας καὶ πρὸ παρατάξεως, εἰ τῶν συνήθων ἀδικημάτων ἀπόσχοιντο, κλοπῆς τε καὶ λῃστείας καὶ ἁρπαγῆς τοῦ τε ἐξαπατᾶν τὸ ὁμόφυλον τοῦ τε κέρδος οἰκεῖον ἡγεῖσθαι τὴν βλάβην τῶν συνηθεστάτων·"},{"number":582,"text":"διοικεῖσθαι γὰρ κάλλιστα τοὺς πολέμους παρʼ οἷς ἂν ἀγαθὸν τὸ συνειδὸς ἔχωσιν πάντες οἱ στρατευόμενοι, τοὺς δὲ οἴκοθεν φαύλους οὐ μόνον τοῖς ἐπιοῦσιν ἐχθροῖς ἀλλὰ καὶ τῷ θεῷ χρῆσθαι πολεμίῳ."},{"number":583,"text":"Πολλὰ τοιαῦτα παραινῶν διετέλει. καὶ τὸ μὲν ἕτοιμον εἰς παράταξιν αὐτῷ συνεκεκρότητο πεζῶν μὲν ἓξ μυριάδες, ἱππεῖς δὲ πεντήκοντα καὶ τριακόσιοι, χωρὶς δὲ τούτων οἷς ἐπεποίθει μάλιστα μισθοφόροι περὶ τετρακισχιλίους καὶ πεντακοσίους· ἐπιλέκτους δὲ περὶ αὑτὸν εἶχεν ἑξακοσίους φύλακας τοῦ σώματος."},{"number":584,"text":"ἔτρεφον δὲ πλὴν τῶν μισθοφόρων τὴν ἄλλην στρατιὰν αἱ πόλεις ῥᾳδίως· τῶν γὰρ καταλεγέντων ἑκάστη τοὺς ἡμίσεις ἐπὶ τὴν στρατιὰν ἐκπέμπουσα τοὺς λοιποὺς ἐπὶ συμπορισμὸν αὐτοῖς τῶν ἐπιτηδείων κατεῖχον, ὡς τοὺς μὲν εἰς ὅπλα, τοὺς δὲ εἰς ἐργασίαν διῃρῆσθαι, καὶ τοῖς τὰ σῖτα πέμπουσιν ἀντιχορηγεῖσθαι παρὰ τῶν ὁπλιτῶν τὴν ἀσφάλειαν."}],"21":[{"number":585,"text":"Διοικοῦντι δʼ οὕτως τῷ Ἰωσήπῳ τὰ κατὰ τὴν Γαλιλαίαν παρανίσταταί τις ἐπίβουλος ἀνὴρ ἀπὸ Γισχάλων, υἱὸς Ληΐου, Ἰωάννης ὄνομα, πανουργότατος μὲν καὶ δολιώτατος τῶν ἐπισήμων ἐν τοῖσδε τοῖς πονηρεύμασιν ἁπάντων, πένης δὲ τὰ πρῶτα καὶ μέχρι πολλοῦ κώλυμα σχὼν τῆς κακίας τὴν ἀπορίαν,"},{"number":586,"text":"ἕτοιμος μὲν ψεύσασθαι, δεινὸς δʼ ἐπιθεῖναι πίστιν τοῖς ἐψευσμένοις, ἀρετὴν ἡγούμενος τὴν ἀπάτην καὶ ταύτῃ κατὰ τῶν φιλτάτων χρώμενος, ὑποκριτὴς φιλανθρωπίας καὶ διʼ ἐλπίδα κέρδους φονικώτατος,"},{"number":587,"text":"ἀεὶ μὲν ἐπιθυμήσας μεγάλων, τρέφων δὲ τὰς ἐλπίδας ἐκ τῶν ταπεινῶν κακουργημάτων· λῃστὴς γὰρ ἦν μονότροπος, ἔπειτα καὶ συνοδίαν εὗρεν τῆς τόλμης τὸ μὲν πρῶτον ὀλίγην, προκόπτων δʼ ἀεὶ πλείονα."},{"number":588,"text":"φροντὶς δʼ ἦν αὐτῷ μηδένα προσλαμβάνειν εὐάλωτον, ἀλλὰ τοὺς εὐεξίᾳ σώματος καὶ ψυχῆς παραστήματι καὶ πολέμων ἐμπειρίᾳ διαφέροντας ἐξελέγετο, μέχρι καὶ τετρακοσίων ἀνδρῶν στῖφος συνεκρότησεν, οἳ τὸ πλέον ἐκ τῆς Τυρίων χώρας καὶ τῶν ἐν αὐτῇ κωμῶν φυγάδες ἦσαν·"},{"number":589,"text":"διʼ ὧν πᾶσαν ἐλῄζετο τὴν Γαλιλαίαν καὶ μετεώρους ὄντας ἐπὶ τῷ μέλλοντι πολέμῳ τοὺς πολλοὺς ἐσπάρασσεν."},{"number":590,"text":"Ἤδη δʼ αὐτὸν στρατηγιῶντα καὶ μειζόνων ἐφιέμενον ἔνδεια χρημάτων κατεῖχεν. ἐπεὶ δὲ τὸν Ἰώσηπον ὁρῶν αὐτοῦ [σφόδρα] χαίροντα τῷ δραστηρίῳ πείθει πρῶτον μὲν αὐτῷ πιστεῦσαι τὸ τεῖχος ἀνοικοδομῆσαι τῆς πατρίδος, ἐν ᾧ πολλὰ παρὰ τῶν πλουσίων ἐκέρδανεν·"},{"number":591,"text":"ἔπειτα συνθεὶς σκηνὴν πανουργοτάτην, ὡς ἄρα φυλάττοιντο πάντες οἱ κατὰ τὴν Συρίαν Ἰουδαῖοι ἐλαίῳ χρῆσθαι μὴ διʼ ὁμοφύλων ἐγκεχειρισμένῳ, πέμπειν αὐτοῖς ἐπὶ τὴν μεθορίαν ἐξῃτήσατο."},{"number":592,"text":"συνωνούμενος δὲ τοῦ Τυρίου νομίσματος, ὃ τέσσαρας Ἀττικὰς δύναται, τέσσαρας ἀμφορεῖς, τῆς αὐτῆς ἐπίπρασκεν τιμῆς ἡμιαμφόριον. οὔσης δὲ τῆς Γαλιλαίας ἐλαιοφόρου μάλιστα καὶ τότε εὐφορηκυίας, εἰς σπανίζοντας εἰσπέμπων πολὺ καὶ μόνος ἄπειρόν τι πλῆθος συνῆγεν χρημάτων, οἷς εὐθέως ἐχρῆτο κατὰ τοῦ τὴν ἐργασίαν παρασχόντος."},{"number":593,"text":"καὶ ὑπολαβών, εἰ καταλύσειεν τὸν Ἰώσηπον, αὐτὸς ἡγήσεσθαι τῆς Γαλιλαίας, τοῖς μὲν ὑφʼ ἑαυτὸν λῃσταῖς προσέταξεν εὐτονώτερον ἐγχειρεῖν ταῖς ἁρπαγαῖς, ὅπως πολλῶν νεωτεριζομένων κατὰ τὴν χώραν ἢ διαχρήσαιτό που τὸν στρατηγὸν ἐκβοηθοῦντα λοχήσας ἢ περιορῶντα τοὺς λῃστὰς διαβάλλοι πρὸς τοὺς ἐπιχωρίους."},{"number":594,"text":"ἔπειτα διεφήμιζεν πόρρωθεν, ὡς ἄρα προδιδοίη τὰ πράγματα Ῥωμαίοις Ἰώσηπος, καὶ πολλὰ τοιαῦτα πρὸς κατάλυσιν τἀνδρὸς ἐπραγματεύετο."},{"number":595,"text":"Καθʼ ὃν καιρὸν ἀπὸ Δεβαρίθθων κώμης νεανίσκοι τινὲς τῶν ἐν τῷ μεγάλῳ πεδίῳ καθεζομένων φυλάκων ἐνεδρεύσαντες Πτολεμαῖον τὸν Ἀγρίππα καὶ Βερνίκης ἐπίτροπον ἀφείλοντο πᾶσαν ὅσην ἦγεν ἀποσκευήν, ἐν ᾗ πολυτελεῖς τε ἐσθῆτες οὐκ ὀλίγαι καὶ πλῆθος ἐκπωμάτων ἀργυρῶν χρυσοῖ τε ἦσαν ἑξακόσιοι."},{"number":596,"text":"μὴ δυνάμενοι δὲ διαθέσθαι κρύφα τὴν ἁρπαγὴν πάντα πρὸς Ἰώσηπον εἰς Ταριχέας ἐκόμισαν."},{"number":597,"text":"ὁ δὲ μεμψάμενος αὐτῶν τὸ πρὸς τοὺς βασιλικοὺς βίαιον τίθησιν τὰ κομισθέντα παρὰ τῷ δυνατωτάτῳ τῶν Ταριχεατῶν Ἀνναίῳ, πέμψαι κατὰ καιρὸν τοῖς δεσπόταις προαιρούμενος· ὃ δὴ μέγιστον αὐτῷ κίνδυνον ἐπήγαγεν."},{"number":598,"text":"οἱ γὰρ ἁρπάσαντες ἅμα μὲν ἐπὶ τῷ μηδεμιᾶς τυχεῖν μερίδος ἐκ τῶν κεκομισμένων ἀγανακτοῦντες, ἅμα δὲ καὶ προσκεψάμενοι τοῦ Ἰωσήπου τὴν διάνοιαν, ὅτι μέλλοι τὸν πόνον αὐτῶν τοῖς βασιλεῦσιν χαρίζεσθαι. νύκτωρ εἰς τὰς κώμας διέδραμον καὶ πᾶσιν ἐνεδείκνυντο τὸν Ἰώσηπον ὡς προδότην· ἐνέπλησαν δὲ καὶ τὰς πλησίον πόλεις ταραχῆς, ὥστε ὑπὸ τὴν ἕω δέκα μυριάδας ὁπλιτῶν ἐπʼ αὐτὸν συνδραμεῖν."},{"number":599,"text":"καὶ τὸ μὲν πλῆθος ἐν τῷ κατὰ Ταριχέας ἱπποδρόμῳ συνηθροισμένον πολλὰ πρὸς ὀργὴν ἀνεβόα καὶ καταλεύειν οἱ δὲ καίειν τὸν προδότην ἐκεκράγεσαν· παρώξυνεν δὲ τοὺς πολλοὺς ὁ Ἰωάννης καὶ σὺν αὐτῷ Ἰησοῦς τις υἱὸς Σαπφία, τότε ἄρχων τῆς Τιβεριάδος."},{"number":600,"text":"οἱ μὲν οὖν φίλοι καὶ σωματοφύλακες τοῦ Ἰωσήπου καταπλαγέντες τὴν ὁρμὴν τοῦ πλήθους ἔφυγον πλὴν τεσσάρων πάντες, αὐτὸς δὲ κοιμώμενος ἤδη προσφερομένου τοῦ πυρὸς διανίσταται,"},{"number":601,"text":"καὶ παραινούντων φεύγειν τῶν τεσσάρων, οἳ παρέμειναν, οὔτε πρὸς τὴν καθʼ ἑαυτὸν ἐρημίαν οὔτε πρὸς τὸ πλῆθος τῶν ἐφεστώτων καταπλαγεὶς προπηδᾷ, περιρρηξάμενος μὲν τὴν ἐσθῆτα, καταπασάμενος δὲ τῆς κεφαλῆς κόνιν, ἀποστρέψας δὲ ὀπίσω τὰς χεῖρας καὶ τὸ ἴδιον ξίφος ἐπιδήσας τῷ τένοντι."},{"number":602,"text":"πρὸς ταῦτα τῶν μὲν οἰκείως ἐχόντων, καὶ μάλιστα τῶν Ταριχεατῶν, οἶκτος ἦν, οἱ δʼ ἀπὸ τῆς χώρας καὶ τῶν πλησίον ὅσοις ἐδόκει φορτικὸς ἐβλασφήμουν, προφέρειν τε τὰ κοινὰ χρήματα θᾶττον ἐκέλευον καὶ τὰς προδοτικὰς συνθήκας ἐξομολογεῖσθαι·"},{"number":603,"text":"προειλήφεσαν γὰρ ἐκ τοῦ σχήματος οὐδὲν αὐτὸν ἀρνήσεσθαι τῶν ὑπονοηθέντων, ἀλλʼ ἐπὶ συγγνώμης πορισμῷ πάντα πεποιηκέναι τὰ πρὸς τὸν ἔλεον."},{"number":604,"text":"τῷ δʼ ἦν ἡ ταπείνωσις προπαρασκευὴ στρατηγήματος, καὶ τεχνιτεύων τοὺς ἀγανακτοῦντας κατʼ αὐτοῦ κατʼ ἀλλήλων στασιάσαι, ἐφʼ οἷς ὠργίζοντο πάνθʼ ὁμολογήσων,"},{"number":605,"text":"ἔπειτα δοθὲν αὐτῷ λέγειν, ἐγὼ ταῦτα, ἔφη, τὰ χρήματα οὔτε ἀναπέμπειν Ἀγρίππᾳ προῃρούμην οὔτε κερδαίνειν αὐτός· μὴ γὰρ ἡγησαίμην ποτὲ ἢ φίλον τὸν ὑμῖν διάφορον ἢ κέρδος τὸ φέρον τῷ κοινῷ βλάβην."},{"number":606,"text":"ὁρῶν δέ, ὦ Ταριχεᾶται, μάλιστα τὴν ὑμετέραν πόλιν ἀσφαλείας δεομένην καὶ πρὸς κατασκευὴν τείχους χρῄζουσαν ἀργυρίου, δεδοικὼς δὲ τὸν Τιβεριέων δῆμον καὶ τὰς ἄλλας πόλεις ἐφεδρευούσας τοῖς ἡρπαγμένοις, κατασχεῖν ἡσυχῆ τὰ χρήματα προειλόμην, ἵνα ὑμῖν περιβάλωμαι τεῖχος."},{"number":607,"text":"εἰ μὴ δοκεῖ, προφέρω τὰ κεκομισμένα καὶ παρέχω διαρπάζειν· εἰ μὴ καλῶς ὑμῖν ἐβουλευσάμην, κολάζετε τὸν εὐεργέτην."},{"number":608,"text":"Ἐπὶ τούτοις οἱ Ταριχεῶται μὲν αὐτὸν ἀνευφήμουν, οἱ δʼ ἀπὸ τῆς Τιβεριάδος σὺν τοῖς ἄλλοις ἐκάκιζον καὶ διηπείλουν· καταλιπόντες δʼ ἑκάτεροι τὸν Ἰώσηπον ἀλλήλοις διεφέροντο. κἀκεῖνος θαρρῶν ἤδη τοῖς ᾠκειωμένοις, ἦσαν δὲ εἰς τετρακισμυρίους Ταριχεᾶται, παντὶ τῷ πλήθει παρρησιαστικώτερον ὡμίλει."},{"number":609,"text":"καὶ πολλὰ τὴν προπέτειαν αὐτῶν κατονειδίσας ἐκ μὲν τῶν παρόντων Ταριχέας ἔφη τειχίσειν, ἀσφαλιεῖσθαι δὲ ὁμοίως καὶ τὰς ἄλλας πόλεις· οὐ γὰρ ἀπορήσειν χρημάτων, ἐὰν ὁμονοῶσιν ἐφʼ οὓς δεῖ πορίζειν καὶ μὴ παροξύνωνται κατὰ τοῦ πορίζοντος."},{"number":610,"text":"Ἔνθα δὴ τὸ μὲν ἄλλο πλῆθος τῶν ἠπατημένων ἀνεχώρει καίτοι διωργισμένον, δισχίλιοι δʼ ἐπʼ αὐτὸν ὥρμησαν ἔνοπλοι, καὶ φθάσαντος εἰς τὸ δωμάτιον παρελθεῖν ἀπειλοῦντες ἐφεστήκεσαν."},{"number":611,"text":"ἐπὶ τούτοις Ἰώσηπος ἀπάτῃ δευτέρᾳ χρῆται· ἀναβὰς γὰρ ἐπὶ τὸ τέγος καὶ τῇ δεξιᾷ καταστείλας τὸν θόρυβον αὐτῶν ἀγνοεῖν ἔφη τίνων ἀξιοῦσιν τυχεῖν· οὐ γὰρ κατακούειν διὰ τὴν τῆς βοῆς σύγχυσιν· ὅσα δʼ ἂν κελεύσωσιν πάντα ποιήσειν, εἰ τοὺς διαλεξομένους ἡσυχῆ πέμψειαν εἴσω πρὸς αὐτόν."},{"number":612,"text":"ταῦτα ἀκούσαντες οἱ γνώριμοι σὺν τοῖς ἄρχουσιν εἰσῄεσαν. ὁ δὲ σύρας αὐτοὺς εἰς τὸ μυχαίτατον τῆς οἰκίας καὶ τὴν αὔλειον ἀποκλείσας ἐμαστίγωσεν, μέχρι πάντων τὰ σπλάγχνα γυμνῶσαι· περιειστήκει δὲ τέως τὸ πλῆθος δικαιολογεῖσθαι μακρότερα τοὺς εἰσελθόντας οἰόμενον."},{"number":613,"text":"ὁ δὲ τὰς θύρας ἐξαπίνης ἀνοίξας ᾑμαγμένους ἐξαφῆκεν τοὺς ἄνδρας καὶ τοσαύτην τοῖς ἀπειλοῦσιν ἐνειργάσατο κατάπληξιν, ὥστε ῥίψαντας τὰ ὅπλα φεύγειν."},{"number":614,"text":"Πρὸς ταῦτα Ἰωάννης ἐπέτεινεν τὸν φθόνον καὶ δευτέραν ἤρτυσεν ἐπιβουλὴν κατὰ τοῦ Ἰωσήπου. σκηψάμενος δὴ νόσον ἱκέτευσεν διʼ ἐπιστολῆς τὸν Ἰώσηπον ἐπιτρέψαι πρὸς θεραπείαν αὐτῷ χρήσασθαι τοῖς ἐν Τιβεριάδι θερμοῖς ὕδασιν."},{"number":615,"text":"ὁ δέ, οὔπω γὰρ ὑπώπτευεν τὸν ἐπίβουλον, γράφει τοῖς κατὰ τὴν πόλιν ὑπάρχοις ξενίαν τε καὶ τὰ ἐπιτήδεια Ἰωάννῃ παρασχεῖν. ὧν ἀπολαύσας μετὰ δύο ἡμέρας ἐφʼ ὃ παρῆν διεπράττετο, καὶ τοὺς μὲν ἀπάταις τοὺς δὲ χρήμασι διαφθείρων ἀνέπειθεν ἀποστῆναι Ἰωσήπου."},{"number":616,"text":"καὶ γνοὺς ταῦτα Σίλας ὁ φυλάσσειν τὴν πόλιν ὑπὸ Ἰωσήπου καθεσταμένος γράφει τὰ περὶ τὴν ἐπιβουλὴν αὐτῷ κατὰ τάχος. ὁ δὲ Ἰώσηπος ὡς ἔλαβεν τὴν ἐπιστολήν, νυκτὸς ὁδεύσας συντόνως ἑωθινὸς παρῆν πρὸς τὴν Τιβεριάδα."},{"number":617,"text":"καὶ τὸ μὲν ἄλλο πλῆθος αὐτῷ ὑπήντα, Ἰωάννης δὲ καίτοι τὴν παρουσίαν ὑποπτεύσας ἐπʼ αὐτὸν ὅμως πέμψας τινὰ τῶν γνωρίμων ὑπεκρίνατο τὴν ἀσθένειαν καὶ κλινήρης ὢν ὑστερῆσαι τῆς θεραπείας ἔλεγεν."},{"number":618,"text":"ὡς δὲ εἰς τὸ στάδιον τοὺς Τιβεριεῖς ἀθροίσας ὁ Ἰώσηπος ἐπειρᾶτο διαλέγεσθαι περὶ τῶν ἐπεσταλμένων, ὑποπέμψας ὁπλίτας προσέταξεν αὐτὸν ἀνελεῖν."},{"number":619,"text":"τούτους τὰ ξίφη γυμνοῦντας ὁ δῆμος προϊδὼν ἀνεβόησεν· πρὸς δὲ τὴν κραυγὴν ὁ Ἰώσηπος ἐπιστραφεὶς καὶ θεασάμενος ἐπὶ τῆς σφαγῆς ἤδη τὸν σίδηρον ἀπεπήδησεν εἰς τὸν αἰγιαλόν· εἱστήκει δὲ δημηγορῶν ἐπὶ βουνοῦ τινος ἑξαπήχους τὸ ὕψος· καὶ παρορμοῦντος ἐπιπηδήσας σκάφους σὺν δυσὶν σωματοφύλαξιν εἰς μέσην τὴν λίμνην ἀνέφυγεν."},{"number":620,"text":"Οἱ στρατιῶται δʼ αὐτοῦ ταχέως ἁρπάσαντες τὰ ὅπλα κατὰ τῶν ἐπιβούλων ἐχώρουν. ἔνθα δείσας ὁ Ἰώσηπος, μὴ πολέμου κινηθέντος ἐμφυλίου διʼ ὀλίγων φθόνον παραναλώσῃ τὴν πόλιν, πέμπει τοῖς σφετέροις ἄγγελον μόνης προνοεῖν τῆς ἑαυτῶν ἀσφαλείας, μήτε δὲ κτείνειν τινὰ μήτʼ ἀπελέγχειν τῶν αἰτίων."},{"number":621,"text":"καὶ οἱ μὲν τῷ παραγγέλματι πεισθέντες ἠρέμησαν, οἱ δʼ ἀνὰ τὴν πέριξ χώραν πυθόμενοι τήν τε ἐπιβουλὴν καὶ τὸν συσκευάσαντα συνηθροίζοντο κατὰ Ἰωάννου· φθάνει δʼ ἐκεῖνος εἰς Γίσχαλα φυγὼν τὴν πατρίδα."},{"number":622,"text":"συνέρρεον δὲ πρὸς τὸν Ἰώσηπον οἱ Γαλιλαῖοι κατὰ πόλεις, καὶ πολλαὶ μυριάδες ὁπλιτῶν γενόμεναι παρεῖναι σφᾶς ἐπὶ τὸν Ἰωάννην τὸν κοινὸν ἐπίβουλον ἐβόων· συγκαταφλέξειν γὰρ αὐτῷ καὶ τὴν ὑποδεξαμένην πατρίδα."},{"number":623,"text":"ὁ δὲ ἀποδέχεσθαι μὲν αὐτῶν ἔφασκεν τὴν εὔνοιαν, ἀνεῖργεν δὲ τὴν ὁρμήν, χειρώσασθαι συνέσει τοὺς ἐχθροὺς μᾶλλον ἢ κτεῖναι προαιρούμενος."},{"number":624,"text":"ἐκλαβὼν δὲ τοὺς ἀφʼ ἑκάστης πόλεως Ἰωάννῃ συναφεστῶτας κατʼ ὄνομα, προθύμως δὲ ἐνεδείκνυντο τοὺς σφετέρους οἱ δημόται, καὶ διὰ κηρύκων ἀπειλήσας ἐντὸς ἡμέρας πέμπτης τῶν μὴ καταλιπόντων Ἰωάννην τάς τε οὐσίας διαρπάσειν καὶ τὰς οἰκίας ἅμα ταῖς γενεαῖς καταφλέξειν,"},{"number":625,"text":"τρισχιλίους μὲν ἀπέστησεν εὐθέως, οἳ παραγενόμενοι τὰ ὅπλα παρὰ τοῖς ποσὶν ἔρριψαν αὐτοῦ, σὺν δὲ τοῖς καταλειφθεῖσιν, ἦσαν δʼ ὅσον εἰς δισχιλίους Σύρων φυγάδες, ἀνέστελλεν Ἰωάννης πάλιν ἐπὶ τὰς λαθραίους ἐπιβουλὰς ἐκ τῶν φανερωτέρων."},{"number":626,"text":"κρύφα γοῦν ἔπεμπεν ἀγγέλους εἰς Ἱεροσόλυμα διαβάλλων τὸν Ἰώσηπον ἐπὶ τῷ μεγέθει τῆς δυνάμεως, φάσκων ὅσον οὐδέπω τύραννον ἐλεύσεσθαι τῆς μητροπόλεως, εἰ μὴ προκαταληφθείη."},{"number":627,"text":"ταῦθʼ ὁ μὲν δῆμος προειδὼς οὐ προσεῖχεν, οἱ δυνατοὶ δὲ κατὰ φθόνον καὶ τῶν ἀρχόντων τινὲς λάθρα τῷ Ἰωάννῃ χρήματα πρὸς συλλογὴν μισθοφόρων ἔπεμψαν, ὅπως πολεμῇ πρὸς Ἰώσηπον· ἐψηφίσαντο δὲ καθʼ ἑαυτοὺς καὶ μετακαλεῖν αὐτὸν ἀπὸ τῆς στρατηγίας."},{"number":628,"text":"οὐ μὴν ἠξίουν ἀποχρήσειν τὸ δόγμα· δισχιλίους δὲ καὶ πεντακοσίους ὁπλίτας καὶ τέσσαρας τῶν ἐπιφανῶν ἄνδρας ἔστειλαν, τόν τε τοῦ Νομικοῦ Ἰώεσδρον καὶ Ἀνανίαν Σαδούκι καὶ Σίμωνα καὶ Ἰούδην Ἰωνάθου, πάντας εἰπεῖν δυνατωτάτους, ἵνʼ οὗτοι τὴν πρὸς τὸν Ἰώσηπον εὔνοιαν ἀποστρέψωσιν, κἂν μὲν ἑκὼν παραγένηται, λόγον ὑποσχεῖν ἐᾶν αὐτόν, εἰ δὲ βιάζοιτο μένειν, ὡς πολεμίῳ χρῆσθαι."},{"number":629,"text":"Ἰωσήπῳ δὲ παραγίνεσθαι μὲν στρατιὰν ἐπεστάλκεσαν οἱ φίλοι, τὴν δʼ αἰτίαν οὐ προεδήλουν ἅτε δὴ λάθρα τῶν ἐχθρῶν βεβουλευμένων. διὸ καὶ μὴ προφυλαξαμένου τέσσαρες πόλεις εὐθέως πρὸς τοὺς διαφόρους ἀπέστησαν ἐλθόντας, Σέπφωρίς τε καὶ Γάβαρα καὶ Γίσχαλα καὶ Τιβεριάς."},{"number":630,"text":"ταχέως δὲ καὶ ταύτας προσηγάγετο δίχα τῶν ὅπλων καὶ χειρωσάμενος στρατηγήμασιν τοὺς τέσσαρας ἡγεμόνας τῶν τε ὁπλιτῶν τοὺς δυνατωτάτους ἀνέπεμψεν εἰς Ἱεροσόλυμα."},{"number":631,"text":"πρὸς οὓς ὁ δῆμος οὐ μετρίως ἠγανάκτησεν καὶ σὺν αὐτοῖς ὥρμησεν τοὺς προπέμψαντας ἀνελεῖν, εἰ μὴ φθάσαντες ἀπέδρασαν."},{"number":632,"text":"Ἰωάννην δὲ λοιπὸν ἐντὸς τοῦ Γισχάλων τείχους ὁ παρὰ Ἰωσήπου φόβος ἐφρούρει. καὶ μετʼ ὀλίγας ἡμέρας πάλιν ἀπέστη Τιβεριὰς ἐπικαλεσαμένων τῶν ἔνδον Ἀγρίππαν τὸν βασιλέα."},{"number":633,"text":"καὶ τοῦ μὲν μὴ καταντήσαντος ἐφʼ ἣν συντέτακτο προθεσμίαν, Ῥωμαϊκῶν δʼ ὀλίγων ἱππέων κατʼ ἐκείνην τὴν ἡμέραν παραφανέντων, τὸν Ἰώσηπον ἐξεκήρυσσον."},{"number":634,"text":"τῶν δʼ ἠγγέλη μὲν εἰς Ταριχέας ἡ ἀπόστασις εὐθέως, ἐκπεπομφὼς δὲ πάντας τοὺς στρατιώτας ἐπὶ σίτου συλλογὴν οὔτε μόνος ἐξορμᾶν ἐπὶ τοὺς ἀποστάντας οὔτε μένειν ὑπέμενεν, δεδοικὼς μὴ βραδύναντος αὐτοῦ φθάσωσιν οἱ βασιλικοὶ παρελθεῖν εἰς τὴν πόλιν· οὐδὲ γὰρ τὴν ἐπιοῦσαν ἡμέραν ἐνεργὸν ἕξειν ἔμελλεν ἐπέχοντος σαββάτου."},{"number":635,"text":"δόλῳ δὴ περιελθεῖν ἐπενόει τοὺς ἀποστάντας. καὶ τὰς μὲν πύλας τῶν Ταριχεῶν ἀποκλεῖσαι κελεύσας, ὡς μὴ προεξαγγείλειέ τις τὸ σκέμμα τοῖς ἐπιχειρουμένοις, τὰ δʼ ἐπὶ τῆς λίμνης σκάφη πάντα συναθροίσας, τριάκοντα δʼ εὑρέθησαν καὶ τριακόσια, καὶ ναῦται τεσσάρων οὐ πλείους ἦσαν ἐν ἑκάστῳ, διὰ τάχους ἐλαύνει πρὸς τὴν Τιβεριάδα."},{"number":636,"text":"καὶ τοσοῦτον ἀποσχὼν τῆς πόλεως ἐξ ὅσου συνιδεῖν οὐ ῥᾴδιον ἦν κενὰς τὰς ἁλιάδας μετεώρους σαλεύειν ἐκέλευσεν, αὐτὸς δὲ μόνους ἑπτὰ τῶν σωματοφυλάκων ἀνόπλους ἔχων ἔγγιον ὀφθῆναι προσῄει."},{"number":637,"text":"θεασάμενοι δʼ αὐτὸν ἀπὸ τῶν τειχῶν ἔτι βλασφημοῦντες οἱ διάφοροι καὶ διὰ τὴν ἔκπληξιν πάντα τὰ σκάφη γέμειν ὁπλιτῶν νομίσαντες ἔρριψαν τὰ ὅπλα καὶ κατασείοντες ἱκετηρίας ἐδέοντο φείσασθαι τῆς πόλεως."},{"number":638,"text":"Ὁ δὲ Ἰώσηπος πολλὰ διαπειλησάμενος αὐτοῖς καὶ κατονειδίσας, εἰ πρῶτον μὲν ἀράμενοι τὸν πρὸς Ῥωμαίους πόλεμον εἰς στάσεις ἐμφυλίους προαναλίσκουσιν τὴν ἰσχὺν καὶ τὰ εὐκταιότατα δρῶσιν τοῖς ἐχθροῖς, ἔπειτα τὸν κηδεμόνα τῆς ἀσφαλείας αὐτῶν ἀναρπάσαι σπεύδουσιν καὶ κλείειν οὐκ αἰδοῦνται τὴν πόλιν αὐτῷ τῷ τειχίσαντι, προσδέχεσθαι τοὺς ἀπολογησομένους ἔφασκεν καὶ διʼ ὧν βεβαιώσεται τὴν πόλιν."},{"number":639,"text":"κατέβαινον δʼ εὐθέως δέκα τῶν Τιβεριέων οἱ δυνατώτατοι· καὶ τοὺς μὲν ἀναλαβὼν μιᾷ τῶν ἁλιάδων ἀνήγαγεν πορρωτέρω, πεντήκοντα δʼ ἑτέρους τῆς βουλῆς τοὺς μάλιστα γνωρίμους κελεύει προελθεῖν ὡς καὶ παρʼ ἐκείνων πίστιν τινὰ βουλόμενος λαβεῖν."},{"number":640,"text":"ἔπειτα καινοτέρας σκήψεις ἐπινοῶν ἄλλους ἐπʼ ἄλλοις ὡς ἐπὶ συνθήκαις προυκαλεῖτο."},{"number":641,"text":"τοῖς δὲ κυβερνήταις ἐκέλευσεν τῶν πληρουμένων διὰ τάχους εἰς Ταριχέας ἀναπλεῖν καὶ συγκλείειν τοὺς ἄνδρας εἰς τὸ δεσμωτήριον, μέχρι πᾶσαν μὲν τὴν βουλὴν οὖσαν ἑξακοσίων, περὶ δὲ δισχιλίους τῶν ἀπὸ τοῦ δήμου συλλαβὼν ἀνήγαγεν σκάφεσιν εἰς Ταριχέας."},{"number":642,"text":"Βοώντων δὲ τῶν λοιπῶν αἴτιον εἶναι μάλιστα τῆς ἀποστάσεως Κλεῖτόν τινα καὶ παρακαλούντων εἰς ἐκεῖνον ἀπερείδεσθαι τὴν ὀργήν, ὁ Ἰώσηπος ἀνελεῖν μὲν οὐδένα προῄρητο, Ληουὶν δέ τινα τῶν ἑαυτοῦ φυλάκων ἐκέλευσεν ἐξελθεῖν, ἵνα ἀποκόψῃ τὰς χεῖρας τοῦ Κλείτου."},{"number":643,"text":"δείσας δὲ ἐκεῖνος εἰς ἐχθρῶν στῖφος ἀποβήσεσθαι μόνος οὐκ ἔφη. σχετλιάζοντα δὲ τὸν Ἰώσηπον ἐπὶ τοῦ σκάφους ὁ Κλεῖτος ὁρῶν καὶ προθυμούμενον αὐτὸν ἐπιπηδᾶν ἐπὶ τὴν τιμωρίαν ἱκέτευεν ἀπὸ τῆς ἀκτῆς τὴν ἑτέραν τῶν χειρῶν καταλιπεῖν."},{"number":644,"text":"κἀκείνου κατανεύσαντος ἐφʼ ᾧ τὴν ἑτέραν αὐτὸς ἀποκόψειεν ἑαυτοῦ, σπασάμενος τῇ δεξιᾷ τὸ ξίφος ἀπέκοψεν τὴν λαιάν· εἰς τοσοῦτον δέους ὑπὸ τοῦ Ἰωσήπου προήχθη."},{"number":645,"text":"τότε μὲν δὴ κενοῖς σκάφεσιν καὶ δορυφόροις ἑπτὰ τὸν δῆμον αἰχμαλωτισάμενος πάλιν Τιβεριάδα προσηγάγετο, μετὰ δʼ ἡμέρας ὀλίγας Σεπφωρίταις συναποστᾶσαν εὑρὼν ἐπέτρεψεν διαρπάσαι τοῖς στρατιώταις."},{"number":646,"text":"συναγαγὼν μέντοι πάντα τοῖς δημόταις ἔδωκεν τοῖς τε κατὰ Σέπφωριν ὁμοίως· καὶ γὰρ ἐκείνους χειρωσάμενος νουθετῆσαι διὰ τῆς ἁρπαγῆς ἠθέλησεν, τῇ δʼ ἀποδόσει τῶν χρημάτων πάλιν εἰς εὔνοιαν προσηγάγετο."}],"22":[{"number":647,"text":"Τὰ μὲν οὖν κατὰ Γαλιλαίαν ἐπέπαυτο κινήματα, καὶ τῶν ἐμφυλίων παυσάμενοι θορύβων ἐπὶ τὰς πρὸς Ῥωμαίους ἐτράποντο παρασκευάς·"},{"number":648,"text":"ἐν δὲ τοῖς Ἱεροσολύμοις Ἄνανός τε ὁ ἀρχιερεὺς καὶ τῶν δυνατῶν ὅσοι μὴ τὰ Ῥωμαίων ἐφρόνουν τό τε τεῖχος ἐπεσκεύαζον καὶ πολλὰ τῶν πολεμιστηρίων ὀργάνων."},{"number":649,"text":"καὶ διὰ πάσης μὲν τῆς πόλεως ἐχαλκεύετο βέλη καὶ πανοπλία, πρὸς ἀτάκτοις δὲ γυμνασίαις τὸ τῶν νέων πλῆθος ἦν, καὶ μεστὰ πάντα θορύβου, δεινὴ δὲ κατήφεια τῶν μετρίων, καὶ πολλοὶ τὰς μελλούσας προορώμενοι συμφορὰς ἀπωλοφύροντο."},{"number":650,"text":"θειασμοί τε τοῖς εἰρήνην ἀγαπῶσιν δύσφημοι, τοῖς δὲ τὸν πόλεμον ἐξάψασιν ἐσχεδιάζοντο πρὸς ἡδονήν, καὶ τὸ κατάστημα τῆς πόλεως πρὶν ἐπελθεῖν Ῥωμαίους ἦν οἷον ἀπολουμένης."},{"number":651,"text":"Ἀνάνῳ γε μὴν φροντὶς ἦν κατὰ μικρὸν ἀφισταμένῳ τῶν εἰς τὸν πόλεμον παρασκευῶν κάμψαι πρὸς τὸ συμφέρον τούς τε στασιαστὰς καὶ τὴν τῶν κληθέντων ζηλωτῶν ἀφροσύνην, ἡττήθη δὲ τῆς βίας, κἀν τοῖς ἑξῆς οἵου τέλους ἔτυχεν δηλώσομεν."},{"number":652,"text":"Κατὰ δὲ τὴν Ἀκραβετηνὴν τοπαρχίαν ὁ Γιώρα Σίμων πολλοὺς τῶν νεωτεριζόντων συστησάμενος ἐφʼ ἁρπαγὰς ἐτράπετο καὶ οὐ μόνον τὰς οἰκίας ἐσπάρασσεν τῶν πλουσίων, ἀλλὰ καὶ τὰ σώματα κατῃκίζετο δῆλός τε ἦν ἤδη πόρρωθεν ἀρχόμενος τυραννεῖν."},{"number":653,"text":"πεμφθείσης δʼ ἐπʼ αὐτὸν ὑπʼ Ἀνάνου καὶ τῶν ἀρχόντων στρατιᾶς πρὸς τοὺς ἐν Μασάδᾳ λῃστὰς μεθʼ ὧν εἶχεν κατέφυγεν, κἀκεῖ μέχρι τῆς Ἀνάνου καὶ τῆς τῶν ἄλλων ἐχθρῶν ἀναιρέσεως μένων συνελῄζετο τὴν Ἰδουμαίαν·"},{"number":654,"text":"ὥστε τοὺς ἄρχοντας τοῦ ἔθνους διὰ τὸ πλῆθος τῶν φονευομένων καὶ τὰς συνεχεῖς ἁρπαγὰς στρατιὰν ἀθροίσαντας ἐμφρούρους τὰς κώμας ἔχειν. καὶ τὰ μὲν κατὰ τὴν Ἰδουμαίαν ἐν τούτοις ἦν."}]},"count":654};})();